window.STORY_CATEGORIES = window.STORY_CATEGORIES || {}; window.STORY_CATEGORIES[4] = [{"id":326,"category_id":4,"category_code":"s4","source_id":1,"title":"سادگی","content":"يک روز يک پسر و دختر جوان دست در دست هم از خياباني عبور ميکردند\r\nجلوي ويترين يک مغازه مي ايستند\r\nدختر:واي چه پالتوي زيبايي\r\nپسر: عزيزم بيا بريم تو بپوش ببين دوست داري؟\r\nوارد مغازه ميشوند دختر پالتو را امتحان ميکند و بعد از نيم ساعت ميگه که خوشش اومده\r\nپسر: ببخشيد قيمت اين پالتو چنده؟\r\nفروشنده:360 هزار تومان\r\nپسر: باشه ميخرمش\r\nدختر:آروم ميگه ولي تو اينهمه پول رو از کجا مياري؟\r\nپسر:پس اندازه 1ساله ام هست نگران نباش\r\n\r\nچشمان دختر از شدت خوشحالي برق ميزند\r\nدختر:ولي تو خيلي براي جمع آوري اين پول زحمت کشيدي\r\nميخواستي گيتار مورد علاقه ات رو بخري\r\nپسر جوان رو به دختر بر ميگرده و ميگه:\r\nمهم نيست عزيزم مهم اينکه با اين هديه تو را خوشحال ميکنم\r\nبراي خريد گيتار ميتونم 1سال ديگه صبر کنم\r\nبعد از خريد پالتو هردو روانه پارک شدن\r\nپسر:عزيزم من رو دوست داري؟\r\nدختر: آره\r\nپسر: چقدر؟\r\nدختر: خيلي\r\n\r\nپسر: يعني به غير از من هيچکس رو دوست نداري و نداشتي؟\r\nدختر: خوب معلومه نه\r\nيک فالگير به آنها نزديک ميشود رو به دختر ميکند و ميگوييد بيا فالت رو بگيرم\r\nدست دختر را ميگيرد\r\nفالگير: بختت بلنده دختر زندگي خوبي داري و آينده اي درخشان عاشقي عاشق\r\nچشمان پسر جوان از شدت خوشحالي برق ميزند\r\nفالگير: عاشق يک پسر جوان يک پسر قدبلند با موهاي مشکي و چشمان آبي\r\nدختر ناگهان دست و پايش را گم ميکند\r\nپسر وا ميرود\r\nدختر دستهايش را از دستهاي فالگير بيرون ميکشد\r\nچشمان پسر پر از اشک ميشود\r\nرو به دختر مي ايستدو ميگوييد: \r\nاو را ميشناسم همين حالا از او يک پالتو خريديم\r\nدختر سرش را پايين مي اندازد\r\nپسر: تو اون پالتو را نميخواستي فقط ميخواستي او را ببيني\r\nما هر روز از آن مغازه عبور ميکرديم و هميشه\r\nتو از آنجا چيزي ميخواستي چقدر ساده بودم نفهميدم چرا با من اينکارو کردي چرا؟\r\nدختر آروم از کنارش عبور کرد او حتي پالتو مورد علاقه اش را با خود نبرد\r\n"},{"id":327,"category_id":4,"category_code":"s4","source_id":2,"title":"امتحان عشق","content":"جان بلانکارد” از روی نیمکت برخاست\r\nلباس ارتشی اش را مرتب کرد و به تماشای انبوه مردم که راه خود را از میان ایستگاه بزرگ مرکزی پیش می گرفتند مشغول شد.\r\nاو به دنبال دختری می گشت که چهره او را هرگز ندیده بود اما قلبش را می شناخت\r\nدختری با یک گل سرخ.\r\n \r\nاز سیزده ماه پیش دلبستگی‌اش به او آغاز شده بود.\r\nاز یک کتابخانه مرکزی در فلوریدا, با برداشتن کتابی از قفسه ناگهان خود را شیفته و مسحور یافته بود.\r\nاما نه شیفته کلمات کتاب بلکه شیفته یادداشتهایی با مداد, که در حاشیه صفحات آن به چشم می‌خورد.\r\nدست خطی لطیف که بازتابی از ذهنی هوشیار و درون بین و باطنی ژرف داشت\r\nدر صفحه اول ” جان” توانست نام صاحب کتاب را بیابد: “دوشیزه هالیس می نل\"\r\nبا اندکی جست و جو و صرف وقت او توانست نشانی دوشیزه هالیس را پیدا کند.\r\n” جان ” برای او نامه ای نوشت و ضمن معرفی خود از او درخواست کرد که به نامه نگاری با او بپردازد. \r\n\r\nروز بعد جان سوار کشتی شد تا برای خدمت در جنگ جهانی دوم عازم شود.\r\nدر طول یکسال و یک ماه پس از آن , آن دو به تدریج با مکاتبه و نامه نگاری به شناخت یکدیگر پرداختند. \r\nهر نامه همچون دانه ای بود که بر خاک قلبی حاصلخیز فرو می افتاد و به تدریج عشق شروع به جوانه زدن کرد. \r\n جان  درخواست عکس کرد ولی با مخالفت ” میس هالیس ” روبه رو شد \r\nبه نظر هالیس اگر ” جان ” قلبا به او توجه داشت دیگر شکل ظاهری اش نمی توانست برای او چندان با اهمیت باشد. \r\nولی سرانجام روز بازگشت ” جان ” فرارسید آن ها قرار نخستین ملاقات خود را گذاشتند : ۷ بعد الظهر در ایستگاه مرکزی نیویورک. \r\nهالیس نوشته بود : تو مرا خواهی شناخت از روی گل سرخی که بر کلاهم خواهم گذاشت \r\nبنابراین راس ساعت ۷ بعدالظهر ” جان ” به دنبال دختری می گشت که\r\nقلبش را سخت دوست می داشت اما چهره اش را هرگز ندیده بود. \r\nادامه ماجرا را از زبان خود جان بشنوید: \r\n زن جوانی داشت به سمت من می‌آمد, بلند قامت و خوش اندام\r\nموهای طلایی‌اش در حلقه‌های زیبا کنار گوش‌های ظریفش جمع شده بود\r\nچشمان آبی رنگش به رنگ آبی گل ها بود\r\nو در لباس سبز روشنش به بهاری می مانست که جان گرفته باشد\r\nمن بی اراده به سمت او قدم برداشتم , کاملا بدون توجه به این که او آن نشان گل سرخ را بر روی کلاهش ندارد. \r\nاندکی به او نزدیک شدم . لب هایش با لبخند پرشوری از هم گشوده شد\r\nاما به آهستگی گفت ” ممکن است اجازه دهید عبور کنم ؟\" \r\nبی‌اختیار یک قدم دیگر به او نزدیک شدم ودر این حال میس هالیس را دیدم. \r\nتقریبا پشت سر آن دختر ایستاده بود زنی حدودا ۴۰ ساله با موهای خاکستری رنگ که در زیر کلاهش جمع شده بود. \r\nاندکی چاق بود و مچ پایش نسبتا کلفتش توی کفش های بدون پاشنه جا گرفته بودند.\r\n\r\nدختر سبز پوش از من دور می شد , من احساس کردم که بر سر یک دوراهی قرارگرفته ام.\r\nاز طرفی شوق وتمنایی عجیب مرا به سمت آن دختر سبز پوش فرا میخواند\r\nو از سویی علاقه ای عمیق به زنی که روحش مرا به معنای واقعی کلمه مسحور کرده بود به ماندن دعوتم می کرد. \r\nاو آن جا ایستاده بود با صورت رنگ پریده و چروکیده اش که بسیار آرام و موقر به نظر می رسید.\r\nوچشمانی خاکستری و گرم که از مهربانی می درخشید.\r\nدیگر به خود تردید راه ندادم. \r\nکتاب جلد چرمی آبی رنگی در دست داشتم که در واقع نشان معرفی من به حساب می آمد.\r\nاز همان لحظه فهمیدم که دیگر عشقی در کار نخواهد بود.\r\nاما چیزی به دست آورده بودم که ارزشش حتی از عشق بیشتر بود.\r\nدوستی گرانبهایی که می توانستم همیشه به آن افتخار کنم. \r\n\r\nبه نشانه احترام و سلام خم شدم و کتاب را برای معرفی خود به سوی او دراز کردم. \r\nبا این وجود وقتی شروع به صحبت کردم از تلخی ناشی از تاثری که در کلامم بود متحیر شدم. \r\nمن ” جان بلانکارد” هستم و شما هم باید دوشیزه می نل باشید. \r\nاز ملاقات شما بسیار خوشحالم \r\nممکن است دعوت مرا به شام بپذیرید؟\r\nچهره آن زن با تبسمی شکیبا از هم گشوده شد\r\nو به آرامی گفت: فرزندم من اصلا متوجه نمی‌شوم!\r\nولی آن خانم جوان که لباس سبز به تن داشت و هم اکنون از کنار ما گذشت\r\nاز من خواست که این گل سرخ را روی کلاهم بگذارم و گفت اگر شما مرا به شام دعوت کردید باید به شما بگویم که\r\nاو در رستوران بزرگ آن طرف خیابان منتظر شماست.\r\nاو گفت که این فقط یک امتحان است! \r\n"},{"id":328,"category_id":4,"category_code":"s4","source_id":3,"title":"طلاق","content":"پس از کلی دردسر با پسر مورد علاقه ام ازدواج کردم...\r\nما همدیگرو به حد مرگ دوست داشتیم.\r\nسالای اول زندگیمون خیلی خوب بود.\r\nاما چند سال که گذشت کمبود بچه رو به وضوح حس می کردیم.\r\nمی دونستیم بچه دار نمی شیم.\r\nولی نمی دونستیم که مشکل از کدوم یکی از ماست\r\nاولاش نمی خواستیم بدونیم\r\nبا خودمون می گفتیم\r\nعشقمون واسه یه زندگی رویایی کافیه\r\nبچه می خوایم چی کار؟\r\nدر واقع خودمونو گول می زدیم\r\n\r\nهم من هم اون…هر دومون عاشق بچه بودیم\r\nتا اینکه یه روز علی نشست رو به رومو گفت\r\nاگه مشکل از من باشه \r\nتو چی کار می کنی؟\r\nفکر نکردم تا شک کنه که دوسش ندارم\r\nخیلی سریع بهش گفتم…من حاضرم به خاطر تو رو همه چی خط سیاه بکشم\r\nعلی که انگار خیالش راحت شده بود یه نفس راحت کشید و از سر میز بلند شد و راه افتاد\r\nگفتم:تو چی؟ گفت:من؟\r\nگفتم:آره… اگه مشکل از من باشه… تو چی کار می کنی؟ \r\nبرگشت…زل زد به چشام…گفت: تو به عشق من شک داری؟\r\nفرصت جواب نداد و گفت: من وجود تو رو با هیچی عوض نمی کنم\r\n\r\nبا لبخندی که رو صورتم نمایان شد \r\nخیالش راحت شد که من مطمئن شدم اون هنوزم منو دوس داره\r\nگفتم:پس فردا می ریم آزمایشگاه\r\nگفت:موافقم…فردا می ریم\r\nو رفتیم… نمی دونم چرا اما دلم مثل سیر و سرکه می جوشید\r\nاگه واقعا عیب از من بود چی؟\r\nسر خودمو با کار گرم کردم تا دیگه فرصت فکر کردن به این حرفارو به خودم ندم\r\nطبق قرارمون صبح رفتیم آزمایشگاه\r\nهم من هم اون…هر دو آزمایش دادیم\r\nبهمون گفتن جواب تا یک هفته دیگه حاضره\r\nیه هفته واسمون قد صد سال طول کشید\r\nاضطرابو می شد خیلی اسون تو چهره هردومون دید\r\n\r\nبا این حال به همدیگه اطمینان می دادیم که جواب ازمایش واسه هیچ کدوممون مهم نیست\r\nبالاخره اون روز رسید\r\nعلی مثل همیشه رفت سر کار و من خودم باید جواب ازمایشو می گرفتم\r\nدستام مثل بید می لرزید\r\nداخل ازمایشگاه شدم\r\nعلی که اومد خسته بود\r\nاما کنجکاو…ازم پرسید جوابو گرفتی؟\r\nمنم زدم زیر گریه…فهمید که مشکل از منه\r\nاما نمی دونم که تغییر چهره اش از ناراحتی بود\r\n\r\nیا از خوشحالی\r\nروزا می گذشتن و علی روز به روز نسبت به من سردتر و سردتر می شد\r\n\r\nتا اینکه یه روز که دیگه صبرم از این رفتاراش طاق شده بود\r\nبهش گفتم:علی… تو چته؟ چرا این جوری می کنی…؟\r\nاونم عقده شو خالی کرد گفت: من بچه دوس دارم مهناز…مگه گناهم چیه؟\r\nمن نمی تونم یه عمر بی بچه تو یه خونه سر کنم\r\nدهنم خشک شده بود… چشام پراشک… گفتم اما تو خودت گفتی همه جوره منو دوس داری\r\nگفتی حاضری بخاطرم قید بچه رو بزنی… پس چی شد؟\r\nگفت:آره گفتم… اما اشتباه کردم… الان می بینم نمی تونم… نمی کشم\r\nنخواستم بحثو ادامه بدم… پی یه جای خلوت می گشتم تا یه دل سیر گریه کنم\r\nاتاقو انتخاب کردم\r\nمن و علی دیگه با هم حرفی نزدیم… تا اینکه علی احضاریه اورد برام و گفت می خوام طلاقت بدم\r\nیا زن بگیرم… نمی تونم خرج دو نفرو با هم بدم… بنابراین از فردا تو واسه خودت…منم واسه خودم\r\nدلم شکست… نمی تونستم باور کنم کسی که یه عمر به حرفای قشنگش دل خوش کرده بودم\r\nحالا به همه چی پا زده \r\nدیگه طاقت نیاوردم\r\nلباسامو پوشیدمو ساکمم بستم\r\nبرگه جواب ازمایش هنوز توی جیب مانتوام بود\r\nدرش اوردم یه نامه نوشتم و گذاشتم روش و هر دو رو کنار گلدون گذاشتم\r\nاحضاریه رو برداشتم و از خونه زدم بیرون\r\nتوی نامه نوشت بودم:\r\nعلی جان…سلام\r\nامیدوارم پای حرفت واساده باشی و منو طلاق بدی\r\nچون اگه این کارو نکنی خودم ازت جدا می شم\r\n\r\nمی دونی که می تونم \r\nدادگاه این حقو به من می ده که از مردی که بچه دار نمی شه جدا شم\r\nوقتی جواب ازمایشارو گرفتم و دیدم که عیب از توئه\r\nباور کن اون قدر برام بی اهمیت بود که حاضر بودم برگه رو همون جاپاره کنم\r\nاما نمی دونم چرا خواستم یه بار دیگه عشقت به من ثابت شه\r\nتوی دادگاه منتظرتم…امضا…مهناز!\r\n"},{"id":329,"category_id":4,"category_code":"s4","source_id":4,"title":"حقیقتی پنهان","content":"در اتاقو قفل کرد\r\nپرده پنجره اتاق رو کشید \r\nنشست روی صندلی \r\nسیگار نیمه کشیده شو برداشت و پک عمیقی بهش زد \r\nتاریکی و دود بود که در هم می آمیخت \r\nو مرد , با چشم های نیمه باز و سرخ \r\nبه این هم آغوشی رخوتناک , نگاه می کرد \r\nدود سفید و تنبل سیگار , مواج و ملایم , در آغوش تاریکی فرو می رفت و محو میشد \r\nانگار تاریکی , دود رو می بلعید و اونو درون خودش , خفه می کرد \r\nمرد از تماشای این هماغوشی بی رحمانه , سرگیجه گرفت و به سرفه افتاد \r\n. \r\nروزهای اول گل سرخ بود و چشم ها \r\nلرزش خفیف لب ها بود و نگاه های پر از ترانه \r\nشنیدن بود و تپیدن \r\nعشق بود و رعشه های خفیف و گرم زیر پوستی \r\nروزهایی که همه چیز معنای خاصی داشت و سلام ها مثل قهوه داغ \r\nدر یک بعد از ظهر سرد زمستان , حسابی , می چسبید \r\nتعریف مرد , از عشق , دوست داشتنی فرا تز از مرزهای منطق بود و زن \r\nعشق را به ایثار دل , تفسیر می کرد\r\nمرد , که هیچگاه عاشق نشده بود \r\nاز گرمای با او بودن \r\nلذت می برد \r\nو حس می کرد چیزی در درونش متحول می شود \r\nو زن , مدام لبخند می زد \r\nو گاهی چشم هایش از هیجان , مرطوب میشد و دستهایش مرتعش از لمس با هم بودن \r\nدستهای مرد را در آغوش میکشید \r\nروزهای اول , همیشه زیباست \r\nمثل روز اول خریدن یک کفش چرم براق \r\nمثل روز اول مدرسه \r\nمثل روز تولد \r\nهر تماسی , پر بود از فدایت شوم ها و دوستت دارم ها و بی تو هرگز \r\nو هر نگاهی , لبریز بود از تمنا و خواستن و نیاز \r\nزن , مثل بهار شده بود \r\nپراز طراوت و تازگی و تبسم های پنهان همیشگی \r\nو مرد , شاد تر از تمام روزهای تنها بودنش , راست قامت و بی پروا \r\nروی این وسعت سفید , لکه ای هم اگر بود , محو بود و مبهم \r\nیا اگر خیلی هم بزرگ بود \r\nبه چشم هیچکدامشان , نمی آمد \r\nشعرهای عاشقانه بود و وعده های مخفیانه \r\n\r\nروزهای خوب , زود می گذرد \r\nقانون \" بودن \" همین است \r\nروزهای خوب , عمرش , مثل عمر پروانه هاست \r\nکوتاه و زیبا \r\nو روزهای خوب , کم کم , تمام میشد \r\nمرد ؛ باز , آهسته , به زیر لب ترانه های غمگین می خواند \r\nو زن , تبسم های کنج لبش را , گم کرده بود \r\nتکرار و تکرار و تکرار \r\nشاید همین تکرار بود که همه چیز را فدای بودن خویش کرده بود \r\nو شاید هم , با هم بودن ها , بوی کهنگی و نم گرفته بود \r\nهر چه بود , مثل سرمایی سوزناک و خشک , به زیر پوست عشق , نفوذ کرده بود \r\nو شاید هم , اصلا , عشقی در کار نبود \r\n\r\n- من هیچوقت عاشق نمی شم \r\nهیچوقت... \r\nفکر کردی منم ازونام که به خاطر یکی , خودشو از روی ساختمون پرت میکنه ؟\r\nفکر کردی اگه نباشی تب می کنم ؟\r\nنه جونم ... اینطوریام نیس , دوستت دارم ولی خل و چل بازی بلد نیستم \r\nحالا دو روز مارو بی خبر میذاری و به تلفونامونم جواب نمیدی بی معرفت ؟\r\nفکر کردی با این کارت , عشقتو توی دلم میکاری ؟\r\nنه به خدا , این کارا همش از بی مرامیته .... حتما یادت رفته اون شباییکه تا صدامو نمیشنیدی خوابت نمی برد \r\nعیبی نداره ... میگذره \r\nیه جورایی می سوزم , حتما کیف می کنی نه ؟\r\nمیسوزم از اینکه گفتم همدلمی ... نگو فقط همرام بودی ... دلت کجا بودو فقط شیطون میدونه \r\nمرد میگفت و از پس دودهای مواج , روزهای گذشته را , جستجو می کرد \r\nو زن , همه چیز انگار , برایش خوابی بود کوتاه و سنگین\r\n- خودت چی ؟\r\nخودت اگه یه هفته هم بری توی غار تنهاییت , هیچکی حق نداره صداش در بیاد \r\nحالا یه تلفنتو جواب ندادم شدم بدترین آدم دنیا \r\nخب چی داری برام بگی ؟ فکر نمی کنی همه چی خیلی بیخودی و تکراری شده ؟\r\nخسته ام کردی , هیچ حس و حالی تو صدات نیست , انگار دارم با سنگ صحبت می کنم \r\nحرفامون جمله به جمله اش اونقدر تکراری شده که نگفته همه شو از برم \r\nنگفتم عاشقم باشو خودتو برام از رو ساختمونا پرت کن پایین \r\nفقط خواستم بفهمم بودن و نبودنم فرقی ام برات داره یا نه \r\nکه تو هم خوب جوابمو دادی\r\nبوق ممتد \r\nمثل یک دیوار آجری بلند است \r\nتا آسمان \r\nانگار که دیوار, آسمان آبی را دو تا می کند \r\nبوق ممتد , یعنی رفتن , بدون خداحافظی \r\nیعنی , چیزی شبیه فحش های بد \r\n...\r\nمرد دست در جیب \r\nبا قدی خمیده و چشمانی بی خواب \r\nقدم زدن را برای فراموش کردن , امتحان می کرد \r\nو زن , بی پروا , عشقی تازه می خواست \r\nاندام نحیفش , تحمل بار تنهایی را نداشت \r\nصدای تازه , گرمتر از صداهای تکراری و واژه های تکراریست \r\nعشق تازه , آدم را دوباره نو می کند \r\nانگار آدم برای ادامه زندگی اش , دوپینگ می کند \r\nعشق تازه , جسارت فراموشی خاطرات عشق کهنه را می طلبد و لگد زدن به تمام با هم بودن های قدیم \r\nمرد نمی توانست \r\nمردها گاهی خیلی سخت می شوند \r\nسخت و بیروح و لایه لایه\r\nو مردی که واپس زده از عشقی نافرجام باشد ,\r\nمی شکند ,\r\nذوب می شود و اینبار به جای شیشه ,\r\nسنگی می شود سخت تر از خارا \r\nآدم دلش تنگ می شود \r\nدل آدم هم که تنگ شود , نفسش میگیرد \r\nهوای گذشته ها را می خواهد \r\nحتی شده به یک نفس عمیق\r\nیکسال گذشت \r\nتنهایی همراه مرد بود \r\nو زن , انگار دوباره , واپس زده عشقی چندین باره بود \r\nمرد , نه اینکه عاشق بوده باشد ... نه .... فقط از روی دلتنگی \r\nگوشی تلفن را بر می دارد و شماره ها را برای شنیدن , نوازش می کند :\r\n-... الو \r\nصدای زن شکسته و خراشیده است \r\nانگار قبلش سیگار کشیده باشد .. آنطوری \r\nصدا , در عین غریبه گی اش , دل مرد را می لرزاند \r\nآن روزها چقدر خوب بود ها \r\n- الو ... بفرمایید \r\nمرد , دلش می خواهد نفس عمیق بکشد \r\nدلش می خواهد نفس حبس شده در سینه اش را با سلامی تازه , بدمد بیرون \r\nگاهی می شود در یک آن , همه چیزهای بد را فراموش کرد \r\nانگار که از همان اول نبوده \r\nمرد تصمیمش را گرفت که ناگهان از پس صدای زن , صدای مردی غریبه آمد \r\nصدای قلدر و خشن: \r\n- الو .... د چرا حرف نمی زنی مزاحم \r\nقلب مرد انگار که , ایستاد \r\nگوشی را کوبید روی تلفن \r\nمردی غریبه ! ... رویا که رنگش می پرد می شود کابوس \r\nو مرد غریبه کابوس رویاهای دلتنگی مرد شد \r\nمرد , نحیف و قد خمیده \r\nدر اتاقو قفل کرد\r\nپرده پنجره اتاق رو کشید \r\nنشست روی صندلی \r\nسیگار نیمه کشیده شو برداشت و پک عمیقی بهش زد \r\nتاریکی و دود بود که در هم می آمیخت و مرد ,\r\nبا چشم های نیمه باز و سرخ , به این هم آغوشی رخوتناک , نگاه می کرد\r\nزن , نشسته بود لبه تخت \r\nشکسته و بیروح\r\nمرد غریبه لباس هایش را پوشید \r\nبوسه سرد مرد غریبه , شانه های لخت زن را آزرد \r\n- دوستت دارم \r\nصدای مرد غریبه , شبیه سائیدن ناخن به دیوار سیمانی بود \r\nزن خوب گوش سپرد \r\nنه ... این صدا هم تازگی نداشت \r\nاین صدا هم تکراری بود \r\nزن , در جستجوی تازه تر شدن , \r\nاندازه تمامی دستمالهای کاغذی دنیا , چروکیده بود \r\nرسم است زیبایی ها را می نویسند و \r\nبعد ها افسانه می خوانندش \r\nو نسل به نسل , آدم ها با ولع \r\nتمام کلمه هایش را می خوانند و حفظ می کنند \r\nحقیقت را که بنویسی \r\nنه کسی می خواند \r\nنه کسی حفظش می کند \r\nحقیقت , آنقدر زشت است گاهی که آدم ها ترجیح می دهند در عمیق ترین نقطه قلبشان , به خاکش بسپارند \r\nتمام.\r\n"},{"id":330,"category_id":4,"category_code":"s4","source_id":5,"title":"عشق و آرامش","content":"استادى از شاگردانش پرسید: چرا ما وقتى عصبانى هستیم داد می‌زنیم؟ چرا مردم هنگامى كه خشمگین هستند صدایشان را بلند می‌كنند و سر هم داد می‌كشند؟\r\nشاگردان فكرى كردند و یكى از آنها گفت: چون در آن لحظه، آرامش و خونسردیمان را از دست می‌دهیم.\r\nاستاد پرسید: این كه آرامشمان را از دست می‌دهیم درست است امّا چرا با وجودى كه طرف مقابل كنارمان قرار دارد داد می‌زنیم؟ آیا نمی‌توان با صداى ملایم صحبت كرد؟ چرا هنگامى كه خشمگین هستیم داد می‌زنیم؟ \r\nشاگردان هر كدام جواب‌هایى دادند امّا پاسخ‌هاى هیچكدام استاد را راضى نكرد...\r\nسرانجام او چنین توضیح داد: هنگامى كه دو نفر از دست یكدیگر عصبانى هستند، قلب‌هایشان از یكدیگر فاصله می‌گیرد. آنها براى این كه فاصله را جبران كنند مجبورند كه داد بزنند. هر چه میزان عصبانیت و خشم بیشتر باشد، این فاصله بیشتر است و آنها باید صدایشان را بلندتر كنند. \r\nسپس استاد پرسید: هنگامى كه دو نفر عاشق همدیگر باشند چه اتفاقى می‌افتد؟ \r\nآنها سر هم داد نمی‌زنند بلكه خیلى به آرامى با هم صحبت می‌كنند.\r\nچرا؟ چون قلب‌هایشان خیلى به هم نزدیك است. فاصله قلب‌هاشان بسیار كم است.\r\nاستاد ادامه داد: هنگامى كه عشقشان به یكدیگر بیشتر شد، چه اتفاقى می‌افتد؟ \r\nآنها حتى حرف معمولى هم با هم نمی‌زنند و فقط در گوش هم نجوا می‌كنند و عشقشان باز هم به یكدیگر بیشتر می‌شود.\r\nسرانجام، حتى از نجوا كردن هم بی‌نیاز می‌شوند و فقط به یكدیگر نگاه می‌كنند! \r\nاین هنگامى است كه دیگر هیچ فاصله‌اى بین قلب‌هاى آن‌ها باقى نمانده باشد.\r\n"},{"id":331,"category_id":4,"category_code":"s4","source_id":6,"title":"داداشی...","content":"\r\nیه خانواده ی سه نفری بود\r\nیه دختر کوچولو بود با مادر و پدرش\r\nبعد از یه مدتی خدا یه داداش کوچولوی خوشگل \r\nبه دختر کوچولوی ما میده\r\nبعد از چند روز که از تولد نوزاد گذشت. \r\nدختر کوچولو هی به مامان و باباش اصرار می کنه \r\nکه اونو با داداش کوچولوش تنها بذارن. \r\nاما مامان و باباش می ترسیدن \r\nکه دختر کوچولوشون حسودی کنه\r\nو یه بلایی سر داداش کوچولوش بیاره\r\nاصرارهای دختر کوچولو اونقدر زیاد شد که \r\nپدر و مادرش تصمیم گرفتن اینکارو بکنن \r\nاما پشت ِ در اتاق مواظبش باشن \r\nدختر کوچولو که با برادرش تنها شد... \r\nخم شد: روی سرش و گفت \r\nداداش کوچولو! تو تازه از پیش خدا اومدی\r\nبه من میگی قیافه ی خدا چه شکلیه ؟\r\nآخه من کم کم داره یادم میره...\r\n"},{"id":332,"category_id":4,"category_code":"s4","source_id":7,"title":"جزیره","content":"در روزگارهاي قديم جزيره اي دور افتاده بود که همه احساسات در آن زندگي مي کردند: شادي، غم، دانش عشق و باقي\r\nاحساسات . روزي به همه آنها اعلام شد که جزيره در حال غرق شدن است. بنابراين هر يک شروع به تعمير قايقهايشان کردند.\r\nاما عشق تصميم گرفت که تا لحظه آخر در جزيره بماند. زمانيکه ديگر چيزی از جزيره روي آب نمانده بود عشق تصميم گرفت\r\nتا براي نجات خود از ديگران کمک بخواهد. در همين زمان او از ثروت که با کشتي با شکوهش در حال گذشتن از آنجا بود کمک خواست.\r\n“ثروت، مرا هم با خود مي بري؟”\r\nثروت جواب داد\"\r\n“نه نمي توانم. مفدار زيادي طلا و نقره در اين قايق هست. من هيچ جايي براي تو ندارم.”\r\nعشق تصميم گرفت که از غرور که با قايقي زيبا در حال رد شدن از جزيره بود کمک بخواهد.\r\n“غرور لطفاً به من کمک کن”\r\n“نمي توانم عشق. تو خيس شده اي و ممکن است قايقم را خراب کني”\r\nپس عشق از غم که در همان نزديکي بود درخواست کمک کرد\r\n“غم لطفاً مرا با خود ببر.”\r\n“آه عشق. آنقدر ناراحتم که دلم مي خواهد تنها باشم.”\r\nشادي هم از کنار عشق گذشت اما آنچنان غرق در خوشحالي بود که اصلاً متوجه عشق نشد.\r\nناگهان صدايي شنيد:\r\n”. بيا اينجا عشق. من تو را با خود مي برم”\r\nصداي يک بزرگتر بود. عشق آنقدر خوشحال شد که حتي فراموش کرد اسم ناجي خود را بپرسد. هنگاميکه به خشکي رسيدند\r\nناجي به راه خود رفت.\r\nعشق که تازه متوجه شده بود که چقدر به ناجي خود مديون است از دانش که او هم از عشق بزرگتر بود پرسيد:\r\n” چه کسي به من کمک کرد؟”\r\nدانش جواب داد: “او زمان بود.\"\r\nزمان؟ اما چرا به من کمک کرد؟\r\nدانش لبخندي زد و با دانايي جواب داد که\r\n“چون تنها زمان بزرگي عشق را درک مي کند\r\n"},{"id":333,"category_id":4,"category_code":"s4","source_id":8,"title":"سی دی ها","content":"پسري يه دختري رو خيلي دوست داشت که توي يه سي دی فروشي کار ميکرد. اما به دخترک در مورد عشقش هيچي نگفت. هر روز به اون فروشگاه ميرفت و يک سي دي مي خريد فقط بخاطر صحبت کردن با اون... بعد از يک ماه پسرک مرد... وقتي دخترک به خونه اون رفت و ازش خبر گرفت مادر پسرک گفت که او مرده و اون رو به اتاق پسر برد... دخترک ديد که تمامي سي دي ها باز نشده... دخترک گريه کرد و گريه کرد تا مرد... ميدوني چرا گريه ميکرد؟ چون تمام نامه هاي عاشقانه اش رو توي جعبه سي دي ميگذاشت و به پسرک ميداد."},{"id":334,"category_id":4,"category_code":"s4","source_id":9,"title":"اتفاق","content":"مرد زنگ در را زد ! کسی جواب نداد . از در وارد خانه شد و سلام کرد ولی کسی جوابش را نداد ، همسر به او اعتنایی نکرد ، حتی دختر کوچکش هم به او توجهی نکرد ، آرام رفت و روی مبل نسشت ، صدای زنگ تلفن به صدا درآمد ، زن تلفن را برداشت ، صدایی از پشت خط گفت : متاسفانه همسر شما چند ساعت پیش درسانحه ای جان خود را از دست داده است."},{"id":335,"category_id":4,"category_code":"s4","source_id":10,"title":"دیوونه","content":"اوایل حالش خوب بود ؛ نمیدونم چرا یهو زد به سرش. حالش اصلا طبیعی نبود .همش بهم نگاه میکرد و میخندید. به خودم گفتم : عجب غلطی کردم قبول کردم ها.... اما دیگه برای                        این حرفا دیر شده بود. باید تا برگشتن اونا از عروسی پیشش میموندم                   .خوب یه جورائی اونا هم حق داشتن که اونو با خودشون نبرن؛ اگه وسط جشن یهو میزد به سرش و دیوونه میشد ممکن بود همه چیزو به هم بریزه وکلی آبرو ریزی میشد.\r\nاونشب برای اینکه آرومش کنم سعی کردم بیشتر بش نزدیک بشم وباش صحبت کنم. بعضی وقتا خوب بود ولی گاهی دوباره به هم میریخت.    یه بار بی مقدمه گفت : توهم از اون قرصها داری؟ قبل از اینکه چیزی بگم گفت : وقتی از اونا میخورم حالم خیلی خوب میشه . انگار دارم رو ابرا راه میرم....روی ابرا کسی بهم نمیگه دیوونه...! بعد با بغض پرسید تو هم فکر میکنی من دیوونه ام؟؟؟ ... اما اون از من دیوونه تره . بعد بلند خندید وگفت : آخه به من میگفت دوستت دارم . اما با یکی دیگه عروسی کرد و بعد آروم گفت : امشبم عروسیشه...\r\n"},{"id":336,"category_id":4,"category_code":"s4","source_id":11,"title":"تخته سنگ","content":"روزي از گورستاني مي گذشتم روي تخته سنگي نوشته يافتم كه نوشته بود: \" اگر جواني عاشق شد چه كند؟ \" من هم زير آن نوشتم: \" صبر \" براي بار دوم كه از آنجا گذر كردم زير نوشته ي من كسي نوشته بود: \" اگر صبر نداشته باشد چه كند؟ \" من هم با بي حوصلگي نوشتم: \"مرگ\" براي بار سوم كه از آنجا عبور مي كردم انتظار داشتم زير نوشته من نوشته اي باشد اما زير تخته سنگ ، جواني را مرده يافتم..."},{"id":337,"category_id":4,"category_code":"s4","source_id":12,"title":"شکلات","content":"\r\nدختر بچه ای از برادرش پرسید:\r\nمعنی عشق چیست؟\r\nداداشش گفت عشق یعنی تو هر روز شکلات من رو از داخل کوله پشتیم برمیداری و من هر روز شکلاتم دوباره اونجا میزارم.\r\n"},{"id":338,"category_id":4,"category_code":"s4","source_id":13,"title":"همه مردند...","content":"دوستی می گفت: خیلی سال پیش که دانشجو بودم،\r\nبعضی از اساتید عادت به حضور و غیاب داشتند.\r\nتعدادی هم برای محکم کاری دو بار این کار را انجام می دادند، ابتدا و انتها که مجبور باشی تمام ساعت را سر کلاس بنشینی. \r\n  همرشته ایی داشتم که شیفته یکی از دختران هم دوره اش بود. هر وقت این خانم سر کلاس حاضر بود، حتی اگر نصف کلاس غایب بودند، جناب مجنون می گفت: استاد همه حاضرند! \r\nو بالعکس، اگر تنها غایب کلاس این خانم بود میگفت: همه غایبند!\r\nتا اینکه باهم ازداواج کردند, دورادور من خبرشون رو داشتم تا اینکه متوجه شده خانم فوت کرده و آقا اطلاعیه ترحیم زده بود:\r\nهیچ کس زنده نیست, همه مردند...\r\n"},{"id":339,"category_id":4,"category_code":"s4","source_id":14,"title":"کوزه ی سفالی","content":"مرد نصفه شب در حالی که مست بوده میاد خونه و دستش می خوره به کوزه ی سفالی گرون قیمتی که زنش خیلی دوستش داشته، میوفته زمین و میشکنه مرد هم همونجا خوابش می بره...\r\nزن اون رو می کشه کنار و همه چیو تمیز می کنه...\r\nصبح که مرد از خواب بیدار میشه انتظار\r\nداشت که زنش جر و بحث و شروع کنه و این کارو تا شب ادامه بده\r\nمرد در حالی که دعا می کرد که این اتفاق نیوفته میره اشپزخونه تا یه چیزی بخوره \r\nکه متوجه یه نامه روی در یخچال می شه که زنش براش نوشته\r\nزن: عشق من صبحانه ی مورد علاقت روی میز آمادست\r\nمن صبح زود باید بیدار می شدم تا برم برای ناهار مورد علاقت خرید کنم\r\nزود بر می گردم پیشت عشق من\r\nدوست دارم خیلی زیاد\r\nمرد که خیلی تعجب کرده بود\r\nمیره پیشه پسرش و ازش می پرسه که دیشب چه اتفاقی افتاده بود؟\r\nپسرش می گه : دیشب وقتی مامان تو رو برد تو تخت خواب که بخوابی و شروع کرد به اینکه لباس و کفشت رو در بیاره تو در حالی که خیلی مست بودی بهش گفتی:  \r\nهی خانوووم ، تنهااااام بزار ، بهم دست نزن...\r\nمن ازدواج کردم...\r\n"},{"id":340,"category_id":4,"category_code":"s4","source_id":15,"title":"گل فروش","content":"رفتم نشستم کنارش گفتم : برای چی نمیری گـُلات رو بفروشی؟ \r\nگفت : بفروشم که چی ؟ تا دیروز می فروختم که با پولش آبجی مو ببرم دکتر دیشب حالش بد شد و مُرد ، با گریه گفت : تو می خواستی گـُل بخری ؟\r\n گفتم: بخرم که چی؟ تا دیروز برای عشقم میخریدم که دیشب فهمیدم باید فرامشش کنم...\r\nاشکاشو که پاک کرد, یه گل بهم داد گفت بگیر, باید از نوع شروع کرد.\r\nتو بدون عشقت و من بدون خواهرم...\r\n"},{"id":341,"category_id":4,"category_code":"s4","source_id":16,"title":"خدای عزیز...","content":"لوئیز رفدفن، زنی بود با لباس های کهنه و مندرس و نگاهی غم آلود وارد خواربار فروشی\r\nمحله شد و با فروتنی از صاحب مغازه خواست کمی خواربار به او بدهد\r\nبه نرمی گفت: شوهرش بیمار است و نمی تواند کار کند و شش\r\nبچه شان بی غذا مانده اند.\r\nجان لانگ هاوس، صاحب مغازه،\r\nبا بی اعتنایی محلش نگذاشت و با حالت بدی خواست او را بیرون کند.\r\n\r\nزن نیازمند در حالی که اصرار می کرد گفت:\r\nآقا شما را به خدا به محض اینکه بتوانم پولتان را پرداخت می کنم.\r\nجان گفت نسیه نمیدهم.\r\nمشتری دیگری که کنار پیشخوان ایستاده بود و به گفت و گوی بین آنها گوش می کرد،\r\nبه مغازه دار گفت: ببین این خانم چه میخواهد،\r\nمن پرداخت می کنم.\r\nخواربار فروش گفت : لازم نیست خودم میدهم، لیست خریدت کو؟\r\nلوئیز گفت: اینجاست.صاحب مغازه گفت:\r\nلیستت را بگذار روی ترازو و به اندازه وزنش هر چه میخواهی ببر!\r\n\r\nلوئیز با خجالت یک لحظه مکث کرد، از کیفش تکه کاغذی\r\nدر آورد و چیزی رویش نوشت و آن را روی کفه ترازو گذاشت\r\nهمه با تعجب دیدند کفه ترازو پایین رفت!خواربار فروش باورش نمی شد.\r\nلوئیز از سر رضایت خندید! \r\nمغازه دار با ناباوری شروع به گذاشتن جنس در کفه ی دیگر ترازو کرد و کفه ی ترازو برابر\r\nنشد! آنقدر چیز گذاشت تا کفه ها برابر شدند.در این وقت، خواروبار فروش با تعجب و\r\nدلخوری تکه کاغذ را برداشت ببیند روی آن چه نوشته است!\r\n\r\nکاغذ لیست خرید نبود! دعای زن بود که نوشته بود\r\nای خدای عزیزم! تو از نیاز من با خبری، آن را برآورده کن...\r\n"},{"id":342,"category_id":4,"category_code":"s4","source_id":17,"title":"شراکت دو عاشق","content":"در یک شب سرد زمستانی یک زوج سالمند وارد رستوران بزرگی شدند. \r\nآنها در میان زوج های جوانی که در آنجا حضور داشتند بسیار جلب توجه می کردند \r\nبسیاری از آنان ،\r\nزوج سالخورده را تحسین می کردند و به راحتی می شد فکر شان را از نگاه شان خواند\r\n: نگاه کنید ، این دو نفر عمری است که در کنار یکدیگر زندگی می کنند و چقدر در کنار\r\nهم خوشبختند. \r\nپیرمرد برای سفارش غذا به طرف صندوق رفت.\r\nغذا سفارش داد ، پولش را پرداخت و غذا آماده شد. با سینی به طرف میزی که\r\nهمسرش پشت آن نشسته بود رفت و رو به رویش نشست. \r\nیک ساندویچ همبرگر ، یک بشقاب سیب زمینی خلال شده و یک نوشابه در سینی بود \r\n\r\nپیرمرد همبرگر را از لای کاغذ در آورد و آن را با دقت به دو تکه ی مساوی تقسیم کرد. \r\nسپس سیب زمینی ها را به دقت شمرد و تقسیم کرد. \r\nپیرمرد کمی نوشابه خورد و همسرش نیز از همان لیوان کمی نوشید. \r\nهمین که پیرمرد به ساندویچ خود گاز می زد مشتریان دیگر با ناراحتی\r\nبه آنها نگاه می کردند و این بار به این فکر می کردند که آن زوج پیر احتمالا آن قدر فقیر\r\nهستند که نمی توانند دو ساندویچ سفارش بدهند.\r\nپیرمرد شروع کرد به خوردن سیب زمینی هایش.\r\nمرد جوانی از جای خو برخاست و به طرف میز زوج پیر آمد و به پیر مرد پیشنهاد کرد تا\r\nبرای شان یک ساندویچ و نوشابه بگیرد . اما پیر مرد قبول نکرد و گفت: \r\n«. همه چیز رو به راه است ، ما عادت داریم در همه چیز شریک باشیم  »\r\n\r\nمردم کم کم متوجه شدند در تمام مدتی که پیرمرد غذایش را می خورد ،\r\nپیرزن او را نگاه می کند و لب به غذایش نمی زند. \r\nبار دیگر همان جوان به طرف میز رفت و از آنها خواهش کرد که اجازه بدهند یک ساندویچ\r\nدیگر برای شان سفارش بدهد و این دفعه پیر زن توضیح داد:\r\n« ما عادت داریم در همه چیز با هم شریک باشیم  »\r\n\r\nهمین که پیرمرد غذایش را تمام کرد ،\r\nمرد جوان طاقت نیاورد و باز به طرف میز آن دو آمد و گفت: \r\n« می توانم سوالی از شما بپرسم خانم ؟ »\r\n\r\nپیرزن جواب داد : بفرمایید \r\n\r\n- چرا شما چیزی نمی خورید ؟ شما که گفتید در همه چیز با هم شریک هستید \r\nمنتظر چی هستید ؟ \r\nپیرزن جواب داد : منتظر دندان ها!\r\n"},{"id":343,"category_id":4,"category_code":"s4","source_id":18,"title":"چشمها","content":"یه روزگار بد یه دختر کور بود که پسری رو دوست داشت پسره هم اونو خیلی دوست داشت . روزی دختره میگه:\r\nاگه من بینا بودم اونوقت می فهمیدی که چقدر دوستت دارم .بعد ها  یکی پیدا میشه چشماشو می ده به دختره و\r\nدختره که بینا میشه می بینه دوست پسرش کوره  ترکش می کنه ولی پسره بهش می گه برو ولی خیلی\r\nمراقب چشام باش !\r\n"},{"id":344,"category_id":4,"category_code":"s4","source_id":19,"title":"عاشق هیچ","content":"پرسيد به خاطر كي زنده هستي؟ با  اينكه دلم مي خواست با تمام وجودم داد بزنم \"بخاطر تو\" بهش \r\nگفتم به خاطر هيچ كس. \r\nپرسيد پس به خاطر چه  زنده هستي؟ با اينكه دلم فرياد ميزد \"به خاطر تو\"\r\n با يك بغض غمگين گفتم به خاطر هيچ چيز.\r\n ازش پرسيدم تو به خاطر چي زنده هستي؟ در حاليكه اشك تو چشمانش جمع شده بود\r\nگفت به خاطر كسي كه به خاطر هيچ زنده است.\r\n"},{"id":345,"category_id":4,"category_code":"s4","source_id":20,"title":"مرد وفادار","content":"روزی زنی نزد شیوانا استاد معرفت آمد و به او گفت که همسرش نسبت به او و فرزندانش بی‌تفاوت شده است و او می‌ترسد که نکند مرد زندگی اش دلش را به دیگری سپرده باشد. شیوانا از زن پرسید: “آیا مرد نگران سلامتی او و بچه‌هایش هست و برایشان غذا و مسکن و امکانات رفاهی را فراهم می‌کند؟!”  زن پاسخ داد: “آری، در رفع نیازهای ما سنگ تمام می‌گذارد و از هیچ چیز کوتاهی نمی‌کند!” شیوانا تبسمی کرد و گفت: “پس نگران نباش و با خیال راحت به زندگی خود ادامه بده!”\r\nدو ماه بعد دوباره همان زن نزد شیوانا آمد و گفت: “به مرد زندگی‌اش مشکوک شده است. او بعضی شبها به منزل نمی‌آید و با ارباب جدیدش که زنی پولدار و بیوه است صمیمی شده است. زن به شیوانا گفت که می‌ترسد مردش را از دست بدهد.” شیوانا از زن خواست تا بی‌خبر به همراه بچه ها به منزل پدر برود و واکنش همسرش را نزد او گزارش دهد.\r\nروز بعد زن نزد شیوانا آمد و گفت شوهرش روز قبل وقتی خسته از سر کار آمده و کسی را در منزل ندیده هراسان و مضطرب همه جا را زیر پا گذاشته تا زن و بچه‌اش را پیدا کند و دیشب کلی همه را دعوا کرده که چرا بی‌خبر منزل را ترک کرده اند.. شیوانا تبسمی کرد و گفت: “نگران مباش! مرد تو مال توست. آزارش مده و بگذار به کارش برسد. او مادامی که نگران شماست، به شما تعلق دارد.”\r\nشش ماه بعد زن گریان نزد شیوانا آمد و گفت: “ای کاش پیش شما نمی‌آمدم و همان روز جلوی شوهرم را می‌گرفتم. او یک هفته پیش به خانه ارباب جدیدش یعنی همان زن پولدار و بیوه رفته و دیگر نزد ما نیامده و این نشانه آن است که او دیگر زن و زندگی را ترک کرده است و قصد زندگی با زن پولدار را دارد.”\r\nزن به شدت می ‌گریست و از بی‌وفایی شوهرش زمین و زمان را دشنام می داد. شیوانا دستی به صورت خود کشید و خطاب به زن گفت: “هر چه زودتر مردان فامیل را صدا بـزن و بی‌مقدمه به منزل ارباب پولدار بروید. حتماً بلایی سر شوهرت آمده است!” زن هراسناک مردان فامیل را خبر کرد و همگی به اتفاق شیوانا به در منزل ارباب پولدار رفتند. ابتدا زن پولدار از شوهر زن اظهار بی‌اطلاعی کرد. اما وقتی سماجت شیوانا در وارسی منزل را دید تسلیم شد.\r\nسرانجام شوهر زن را درون چاهی در داخل باغ ارباب پیدا کردند. او را در حالی که بسیار ضعیف و درمانده شده بود از چاه بیرون کشیدند. مرد به محض اینکه از چاه بیرون آمد به مردان اطراف گفت که سریعاً به همسر و فرزندانش خبر سلامتی او را بدهند که نگران نباشند. شیوانا لبخندی زد و گفت: این مرد هنوز نگران است. پس هنوز قابل اعتماد است و باید حرفش را باور کرد.\r\nبعداً مشخص شد که زن بیوه ارباب هر چه تلاش کرده بود تا مرد را فریب دهد موفق نشده بود و به خاطر وفاداری مرد او را درون چاه زندانی کرده بود. یک سال بعد زن هدیه ای برای شیوانا آورد. شیوانا پرسید: “شوهرت چطور است؟!” زن با تبسم گفت: “هنوز نگران من و فرزندانم است؛ بنابراین دیگر نگران از دست دادنش نیستم!\r\n"},{"id":346,"category_id":4,"category_code":"s4","source_id":21,"title":"عشق تا پای جان","content":"روزی مرد ثروتمندی همراه دخترش مقدار زیادی شیرینی و خوردنی به مدرسه شیوانا آورد و گفت اینها هدایای ازدواج تنها دختر او با پسر جوان و بیکاری از یک خانواده فقیر است.\r\nشیوانا پرسید: چگونه این دو نفر با دو سطح زندگی متفاوت با همدیگر وصلت کرده اند؟\r\nمرد ثروتمند پاسخ داد: این پسر شیفته‌ی دخترم است و برای ازدواج با او خودش را عاشق و دلداده نشان داده و به همین دلیل دل دخترم را ربوده است. درحالی که پسر یکی از دوستانم، هم نجیب است و هم عاقل، با اصرار می‌خواهد با دخترم ازدواج کند اما دخترم می‌گوید او بیش از حد جدی نیست و شور و جنون جوانی در حرکات و رفتارش وجود ندارد. اما این پسر بیکار هرچه ندارد دیوانگی و شور و عشق جوانی‌اش بی‌نظیر است. دخترم را نصیحت می‌کنم که فریب نخورد و کمی عاقلانه‌تر تصمیم بگیرد اما او اصلا به حرف من گوش نمی‌دهد. من هم به ناچار به ازدواج آن دو با هم رضایت دادم.\r\nشیوانا از دختر پرسید: چقدر مطمئن هستی که او عاشق توست؟\r\nدختر گفت: از همه بیشتر به عشق او ایمان دارم!\r\nشیوانا به دختر گفت: بسیار خوب بیا امتحان کنیم. نزد این عاشق و دلداده برو و به او بگو که پدرت تهدید کرده اگر با او ازدواج کنی حتی یک سکه از ثروتش را به شما نمی‌دهد. بگو که پدرت تهدید کرده که اگر سرو کله‌اش اطراف منزل شما پیدا شود او را به شدت تنبیه خواهد کرد.\r\nدختر با خنده گفت: من مطمئنم او به این سادگی میدان را خالی نمی‌کند. ولی قبول می‌کنم و به او چنین می‌گویم. چند هفته بعد مرد ثروتمند با دخترش دوباره نزد شیوانا آمدند. شیوانا متوجه شد که دختر غمگین و افسرده است. از او دلیل اندوهش را پرسید.\r\nدختر گفت: به محض اینکه به او گفتم پدرم گفته یک سکه به من نمی‌دهد و هر وقت او را ببیند تنبیه‌اش می‌کند، فوراً از مقابل چشمانم دور شد . از این دهکده فرار کرد. حتی برای خداحافظی هم نیامد.\r\nشیوانا با خنده گفت: اینکه ناراحتی ندارد. اگر او عاشق واقعی تو بود حتی اگر تو هم می‌گفتی که دیگر علاقه‌ای به او نداری و درخواست جدایی می‌کردی، او هرگز قبول نمی‌کرد. وقتی کسی چیزی را واقعا بخواهد با تمام جان و دل می‌خواهد و هرگز اجازه نمی‌دهد حتی برای یک لحظه آن چیز را از دست بدهد. اگر دیدی او به راحتی رهایت کرد و رفت مطمئن باش که او تو را از همان ابتدا نمی‌خواسته و نفع و صلاح خودش را به تو ترجیح داده است. دیگر برای کسی که از همان ابتدا به تو علاقه‌ای نداشته ناراحتی چه معنایی می تواند داشته باشد\r\n"},{"id":347,"category_id":4,"category_code":"s4","source_id":22,"title":"آخرین صدا","content":"زن و شوهر پیری با هم زندگی می کردند. پیر مرد همیشه از خروپف همسرش شکایت داشت و پیر زن هرگز زیر بار نمی رفت و گله های شوهرش رو به حساب بهانه گیری های او می گذاشت.                                                                               این بگو مگوها همچنان ادامه داشت تا اینکه فکری به ذهن پیرمرد رسید برای اینکه ثابت کند زنش در خواب خروپف می کند و آسایش او را مختل کرده است ضبط صوتی را آماده می کند و شبی همه سر و صدای خرناس های گوشخراش همسرش را ضبط می کند\r\n پیرمرد صبح از خواب بیدار می شود و شادمان از اینکه سند معتبری برای ثابت کردن خروپف های شبانه او دارد به سراغ همسر پیرش\r\n می رود و او را صدا می کند، غافل از اینکه زن بیچاره به خواب ابدی فرو رفته است! از آن شب به بعد خروپف های ضبط شده پیرزن، لالایی آرام بخش شبهای تنهایی او می شود. قدر هر کسی رو بدونیم تا یه روزی پشیمون نشیم.\r\n"},{"id":348,"category_id":4,"category_code":"s4","source_id":23,"title":"شاعر و فرشته","content":"  شاعر وفرشته ای باهم دوست شدند فرشته پری به شاعر داد و شاعرشعری به فرشته . شاعر پر فرشته را لای دفترش گذاشت وشعرهایش بوی اسمان گرفت وفرشته شعر شاعر را زمزمه کردودهانش مزه عشق گرفت. خدا گفت:دیگر تمام شد.دیگر زندگی برای هردوتان دشوار می شود.زیرا شاعری که بوی اسمان را بشنود زمین برایش کوچک است وفرشته ای که مزه عشق را بچشد اسمان برایش تنگ. پر فرشته دست شاعر را گرفت تا راههای اسمان را نشانش بدهد و شاعر بال فرشته را گرفت تا کوچه پس کوچه ای زمین را نشانش بدهد شب که هر دو به خانه برگشتند روی بال فرشته قدری خاک بود و روی شانه های شاعر چند تا پر."},{"id":349,"category_id":4,"category_code":"s4","source_id":24,"title":"نابینا و ماه","content":"\r\n ماه گفت: چه طوري؟ تو که نمي بيني. \r\nنابينا گفت: چون نمي بينمت دوستت دارم. \r\n ماه گفت: چرا؟\r\n نابينا گفت: اگر مي ديدمت عاشق زيباييت مي شدم ولي حالا که نمي بينمت عاشق خودت هستم\r\n"},{"id":350,"category_id":4,"category_code":"s4","source_id":25,"title":"صداقت","content":"250سال پيش از ميلاد در چين باستان شاهزاده اي تصميم به ازدواج گرفت. با مرد خردمندي مشورت کرد و تصميم گرفت تمام دختران جوان منطقه را دعوت کند تا دختر سزاوار را انتخاب کند .وقتي خدمتکار پير قصر ماجرا را شنيد بشدت غمگين شد چون دختر او مخفيانه عاشق شاهزاده بود ، دخترش گفت او هم به آن مهماني خواهد رفت . مادر گفت : تو شانسي نداري ، نه ثروتمندي و نه خيلي زيبا .دختر جواب داد : مي دانم هرگز مرا انتخاب نمي کند ، اما فرصتي است که دست کم يک بار او را از نزديک ببينم .روز موعود فرا رسيد و شاهزاده به دختران گفت : به هر يک از شما دانه اي مي دهم ، کسي که بتواند در عرض 6 ماه زيباترين گل را براي من بياورد ، ملکه آينده چين مي شود .دختر پيرزن هم دانه را گرفت و در گلداني کاشت .سه ماه گذشت و هيچ گلي سبز نشد ، دختر با باغبانان بسياري صحبت کرد و راه گلکاري را به او آموختند ، اما بي نتيجه بود ، گلي نروييد.روز ملاقات فرا رسيد ، دختر با گلدان خالي اش منتظر ماند و ديگر دختران هر کدام گل بسيار زيبايي به رنگها و شکلهاي مختلف در گلدان هاي خود داشتند .لحظه موعود فرا رسيد شاهزاده هر کدام از گلدان ها را با دقت بررسي کرد و در پايان اعلام کرد دختر خدمتکار همسر آينده او خواهد بود .همه اعتراض کردند که شاهزاده کسي را انتخاب کرده که در گلدانش هيچ گلي سبز نشده است . شاهزاده توضيح داد : اين دختر تنها کسي است که گلي را به ثمر رسانده که او را سزاوار همسري امپراتور مي کند : گل صداقت ...همه دانه هايي که به شما دادم عقيم بودند ، امکان نداشت گلي از آنها سبز شود"},{"id":351,"category_id":4,"category_code":"s4","source_id":26,"title":"محاکمه ی عشق","content":"جلسه محاكمه عشق بود، عقل قاضی ، و عشق محكوم \r\nبه دلیل تبعید به دورترین نقطه مغز یعنی فراموشی ، قلب تقاضای عفو عشق را داشت ولی همه اعضا با او مخالف بودند\r\nقلب شروع كرد به طرفداری از عشق\r\nآهای چشم مگر تو نبودی كه هر روز آرزوی دیدن چهره زیبایش را داشتی؟ \r\nای گوش مگر تو نبودی كه در آرزوی شنیدن صدایش بودی ؟ \r\nوشما پاها كه همیشه مشتاق رفتن به سویش بودید حالا چرا اینچنین با او مخالفید ؟\r\nهمه اعضا روی برگرداندند و به نشانه اعتراض جلسه را ترك كردند ،\r\nتنها عقل و قلب در جلسه ماندند عقل گفت\r\nدیدی قلب همه از عشق بی زارند ، ولی متحیرم با وجودی كه عشق بیشتر از همه تورا آزرده چرا هنوز از او حمایت میكنی !؟\r\nقلب نالید و گفت\r\nمن بی وجود عشق دیگر نخواهم بود و تنها تكه گوشتی هستم كه هر ثانیه كار ثانیه قبل را تكرار میكند و فقط با عشق میتوانم یك قلبی واقعی باشم\r\n"},{"id":352,"category_id":4,"category_code":"s4","source_id":27,"title":"عشق و ازدواج","content":"شاگردی از استادش پرسید: عشق چست\r\nاستاد در جواب گفت: به گندم زار برو و پر خوشه ترین شاخه را بیاور اما در هنگام عبور از گندم زار، به یاد داشته باش كه نمی توانی به عقب برگردی تا خوشه ای بچینی\r\nشاگرد به گندم زار رفت و پس از مدتی طولانی برگشت. استاد پرسید: چه آوردی؟ و شاگرد با حسرت جواب داد: هیچ! هر چه جلو میرفتم، خوشه های پر پشت تر میدیدم و به امید پیدا كردن پرپشت ترین، تا انتهای گندم زار رفتم.\r\nاستاد گفت: عشق یعنی همین \r\nشاگرد پرسید: پس ازدواج چیست؟\r\nاستاد به سخن آمد كه: به جنگل برو و بلندترین درخت را بیاور اما به یاد داشته باش كه باز هم نمی توانی به عقب برگردی \r\nشاگرد رفت و پس از مدت كوتاهی با درختی برگشت. استاد پرسید كه شاگرد را چه شد و او در جواب گفت: به جنگل رفتم و اولین درخت بلندی را كه دیدم، انتخاب كردم. ترسیدم كه اگر جلو بروم، باز هم دست خالی برگردم استاد باز گفت\r\nازدواج هم یعنی همین \r\n"},{"id":353,"category_id":4,"category_code":"s4","source_id":28,"title":"تا...","content":"با يك شكلات شروع شد. من يك شكلات گذاشتم كف دستش. او هم يك شكلات گذاشتم توي دستم. من بچه بودم، او هم بچه بود. سرم را بالا كردم. سرش را بالا كرد. ديد كه مرا مي شناسد. خنديدم. گفت: «دوستيم؟» گفتم: «دوست دوست» گفت: «تا كجا؟» گفتم: «دوستي كه تا ندارد» گفت: «تا مرگ؟» خنديدم و گفتم: «من كه گفتم تا ندارد» گفت: «باشد، تا پس از مرگ» گفتم: «نه، نه، گفتم كه تا ندارد». گفت: «قبول، تا آن جا كه همه دوباره زنده مي شود، يعني زندگي پس از مرگ. باز هم با هم دوستيم. تا بهشت، تا جهنم، تا هر جا كه باشد من و تو با هم دوستيم.» خنديدم و گفتم: «تو برايش تا هر كجا كه دلت مي خواهد يك تا بگذار. اصلأ يك تا بكش از سر اين دنيا تا آن دنيا. اما من اصلأ تا نمي گذارم» نگاهم كرد. نگاهش كردم. باور نمي كرد. مي دانستم. او مي خواست حتمأ دوستي مان تا داشته باشد. دوستی بدون تا را نمي فهميد.\r\nگفت: «بيا براي دوستي مان يك نشانه بگذاريم». گفتم: «باشد. تو بگذار.» گفت: «شكلات. هر بار كه همديگر را مي بينيم يك شكلات مال تو و يكي مال من، باشد؟» گفتم: «باشد»\r\nهر بار يك شكلات مي گذاشتم توي دستش، او هم يك شكلات توي دست من. باز همديگر را نگاه مي كرديم. يعني كه دوستيم. دوست دوست. من تندي شكلاتم را باز مي كردم و مي گذاشتم توي دهانم و تند تند آن را مي مكيدم. مي گفت: «شكمو! تو دوست شكمويي هستي» و شكلاتش را مي گذاشت توي يك صندوق كوچولوي قشنگ. مي گفتم «بخورش» مي گفت: «تمام مي شود. مي خواهم تمام نشود. مي خواهم براي هميشه بماند.»\r\nصندوقش پر از شكلات شده بود. هيچ كدامش را نمي خورد. من همه اش را خورده بودم. گفتم: «اگر يك روز شكلات هايت را مورچه ها بخورند يا كرم ها، آن وقت چه كار مي كني؟» گفت: «مواظبشان هستم» مي گفت «مي خواهم تا موقعي كه دوست هستيم » و من شكلات را مي گذاشتم توي دهانم و مي گفتم: «نه، نه، تا ندارد. دوستي كه تا ندارد.»\r\nيك سال، دو سال، چهار سال، هفت سال، ده سال و بيست سال شده است. او بزرگ شده است. من بزرگ شده ام. من همه شكلات ها را خورده ام. او همه شكلات ها را نگه داشته است. او آمده است امشب تا خداحافظي كند. مي خواهد برود آن دور دورها. مي گويد «مي روم، اما زود برمي گردم». من مي دانم، مي رود و بر نمي گردد. يادش رفت به من شكلات بدهد. من يادم نرفت. يك شكلات گذاشتم كف دستش. گفتم «اين براي خوردن» يك شكلات هم گذاشتم كف آن دستش: «اين هم آخرين شكلات براي صندوق كوچكت». يادش رفته بود كه صندوقي دارد براي شكلات هايش. هر دو را خورد. خنديدم. مي دانستم دوستي من «تا» ندارد. مثل هميشه. خوب شد همه شكلات هايم را خوردم. اما او هيچ كدامشان را نخورد. حالا با يك صندوق پر از شكلات نخورده چه خواهد كرد\r\n"},{"id":354,"category_id":4,"category_code":"s4","source_id":29,"title":" عشق و نفرت","content":"زن و شوهر جوانی که تازه ازدواج کرده بودند برای تبرک و گرفتن نصیحتی از پیر دانا نزد او رفتند.\r\nپیرمرد دانا به حرمت زوج جوان از جا برخاست و آنها را کنار خود نشاند او از مرد پرسید: تو چقدر همسرت را دوست داری!؟\r\n  مرد جوان لبخندی زد و گفت: تا سرحد مرگ او را می پرستم! و تا ابد هم چنین خواهم بود!\r\nو از همسرش نیز پرسید: تو چطور! به همسرت تا چه اندازه علاقه داری!؟\r\n  زن شرمناک تبسمی کرد و گفت: من هم مانند او تا سرحد مرگ دوستش دارم و تا زمان مرگ از او جدا نخواهم شد و هرگز از این احساسم نسبت به او کاسته نخواهد شد.\r\nپیر عاقل تبسمی کرد و گفت: بدانید که در طول زندگی زناشویی شما لحظاتی رخ می دهند که از یکدیگر تا سرحد مرگ متنفر خواهید شد و اصلا هیچ نشانه ای از علاقه الآنتان در دل خود پیدا نخواهید کرد.\r\n  در آن لحظات حتی حاضرنخواهید بود که یک لحظه چهره همدیگر را ببینید.\r\n  اما در آن لحظات عجله نکنید و بگذارید ابرهای ناپایدار نفرت از آسمان عشق شما پراکنده شوند و دوباره خورشید محبت بر کانون گرمتان پرتوافکنی کند.\r\n  در این ایام اصلا به فکر جدایی نیافتید و بدانید که  \"تاسرحد مرگ متنفر بودن\"  تاوانی است که برای  \"تا سرحد مرگ دوست داشتن\" می پردازید.\r\n  عشق و نفرت دو انتهای آونگ زندگی هستند که اگر زیاد به کرانه ها بچسبید، این هردو احساس را در زندگی تجربه خواهید کرد.\r\nسعی کنید همیشه حالت تعادل را حفظ کنید و تا لحظه مرگ لحظه ای از هم جدا نشوید..\r\n"},{"id":355,"category_id":4,"category_code":"s4","source_id":30,"title":"دلیل عشق","content":"روزی دختری از پسری که عاشقش بود پرسید : چرا مرا دوست داری ؟ چرا عاشقم هستی ؟ پسر گفت : نمی توانم دلیل خاصی را بگویم اما از اعماق قلبم دوستت دارم دختر گفت : وقتی نمی توانی دلیلی برای دوست داشتن پیدا کنی چگونه می توانی بگویی عاشقم هستی ؟!!!!\r\n پسر گفت : واقعا دلیلش را نمی دانم اما میتوانم ثابت کنم که دوستت دارم دختر گفت : اثبات؟!!!! نه من فقط دلیل عشقت را می خواهم ..\r\n شوهر دوستم به راحتی دلیل دوست داشتنش را برای او توضیح می دهد اما تو نمی توانی این کار را بکنی !!!! پسر گفت : خوب … من تو رو دوست دارم چون زیبا هستی … چون صدای تو گیراست …. چون جذاب و دوست داشتنی هستی …. چون باملاحظه و بافکر هستی …… چون به من توجه و محبت می کنی … تو را به خاطر لبخندت دوست دارم ……….. به خاطر تمامی حرکاتت دوست دارم … دختر از سخنان پسر بسیار خشنود شد چند روز بعد دختر تصادف کرد و به کما رفت پسر نامه ای را کنار تخت او گذاشت نامه بدین شرح بود \r\nعزیز دلم !!!تو رو به خاطر صدای گیرایت دوست دارم ….. اکنون دیگر حرف نمی زنی پس نمیتوانم دوستت داشته باشم دوستت دارم چون به من توجه و محبت میکنی ……  چون اکنون قادر به محبت کردن به من نیستی نمی توانم دوستت داشته باشم تو را به خاطر لبخندت و تمامی حرکاتت دوست دارم ….. آیا اکنون می توانی بخندی ؟ می توانی هیچ حرکتی بکنی ؟  پس دوستت ندارم اگر عشق احتیاج به دلیل داشته باشد در زمان هایی مثل الان ….. هیچ دلیلی برای دوست داشتنت ندارم آیا عشق واقعا به دلیل نیاز دار؟ نه …… و من هنوز دوستت دارم … عاشقت هستم. \r\n"},{"id":356,"category_id":4,"category_code":"s4","source_id":31,"title":"اجازه ی پدر","content":"روسری اش را جلو کشید و موهای سیاه و براقش را زیر آن پنهان کرد ، رو کرد به جوان و با ذوق گفت : چه حلقه ی قشنگی !!! نگاه کن ، اندازه انگشتمه ، فکر نمیکردم اینقدر خوش سلیقه باشی ؟! یکدفعه لحن صدایش عوض شد ، انگار چیزی یادش آمده بود ؛ آرام گفت : پدرم نامه هایت را دید ، حالا دیگر همه چیز را میداند. اما تو نگران نباش ، گفت باید با تو حرف بزند. اگر بتوانی خودت را نشان بدهی و دلش را به دست بیاوری حتما موافقت میکند. دل کوچک و مهربانی دارد.\r\nمن که رفتم ، دسته گل را بردار و به دیدنش برو ، راحت پیدایش میکنی … چند قطعه آنطرف تر از تو ، کنار درخت نارون ، مزارش آنجاست\r\n"},{"id":357,"category_id":4,"category_code":"s4","source_id":32,"title":"دستها","content":"دستاشو مشت کرده بود\r\nپرسیدم توی مشتت چیه ؟\r\nگفت : خودت نگاه کن \r\nدستاشو گرفتم و آروم باز کردم … توی دستاش چیزی نبود \r\nگفتم : چیزی نیست که ؟\r\nدستامو که توی دستاش بود فشرد و گفت : نبود ولی حالا هست \r\nدستام گرم شد و اون لبخند زد \r\n"},{"id":358,"category_id":4,"category_code":"s4","source_id":33,"title":"تکه کاغذ","content":"یه دختر و پسر که زمانی همدیگرو با تمام وجود دوست داشتن بعد از پایان ملاقاتشون با هم سوار یه ماشین شدن و آروم کنار هم نشستن … دختر میخواست چیزی رو به پسر بگه ولی روش نمیشد ! پسر هم کاغذی رو آماده کرده بود که چیزی رو که نمیتونست به دختر بگه توش نوشته بود ؛ پسر وقتی دید داره به مقصد نزدیک میشه کاغذ رو به دختر داد ، دختر هم از این فرصت استفاده کرد و حرفشو به پسر گفت که شاید بعد از پایان حرفش پسر از ماشین پیاده بشه و دیگه اونو نبینه \r\nدختر قبل از این که نامه ی پسرو بخونه به اون گفت که دیگه از اون خسته شده ، دیگه عشقش رو نسبت به اون از دست داده و الان پسری پیدا شده که بهتر از اونه … پسر در حالی که بغض تو گلوش بود و اشک توی چشماش جمع شده بود با ناراحتی از ماشین پیاده شد که در همین حال ماشینی به پسر زد و پسر درجا مرد … دختر که با تمام وجود در حال گریه بود یاد کاغذی افتاد که پسر بهش داده بود ، وقتی کاغذ رو باز کرد پسر نوشته بود: \r\n“اگه یه روز ترکم کنی میمیرم”\r\n"},{"id":359,"category_id":4,"category_code":"s4","source_id":34,"title":"اتفاق","content":"ته پیاز و رنده رو پرت کردم توی سینک، اشک از چشم و چارم جاری بود. در یخچال رو باز کردم و تخم مرغ رو شکستم روی گوشت، روغن رو ریختم توی ماهیتابه و اولین کتلت رو کف دستم پهن کردم و خوابوندم کَفِش، برای خودش جلز جلز خفیفی کرد که زنگ در رو زدند. پدرم بود، بازم نون تازه آورده بود. نه من و نه اصغر حس و حال صف نونوایی رو نداشتیم. بابام میگفت “نون خوب خیلی مهمه ! من که بازنشسته‌ام، کاری هم ندارم، هروقت برای خودمون گرفتم برای شما هم می‌گیرم.” در می‌زد و نون رو همون دم در می‌داد و می‌رفت؛ هیچوقت هم بالا نمیومد، هیچ وقت … دستم چرب بود، اصغر در رو باز کرد و دوید توی راه پله. پدرم رو خیلی دوست داشت. کلا پدرم از اون جور آدم‌هایی بود که بیشتر آدم‌ها دوستش دارن، این البته زیاد شامل مادرم نمی‌شد. صدای اصغر از توی راه پله می‌اومد که به اصرار تعارف می‌کرد و پدر و مادرم رو برای شام دعوت می‌کرد بالا؛ برای یه لحظه خشکم زد. ما خانواده‌ی سرد و نچسبی بودیم، روی هم رو نمی‌بوسیدیم، بغل نمی‌کردیم، قربون صدقه هم نمیرفتیم و از همه مهم‌تر سرزده و بدون دعوت جایی نمیرفتیم. ولی خانواده‌ی اصغر اینجوری نبود، در می‌زدن و میومدن تو، روزی هفده بار با هم تلفنی حرف می‌زدن؛ قربون صدقه هم می‌رفتن و قبیله‌ای بودن. برای همین هم اصغر نمی‌فهمید کاری که داشت می‌کرد مغایر اصول تربیتی من بود و هی اصرار می‌کرد و اصرار می‌کرد. آخر سر در باز شد و پدر و مادرم وارد شدند ولی من اصلا خوشحال نشدم. خونه نامرتب بود؛ خسته بودم. تازه از سر کار برگشته بودم، توی یخچال میوه نداشتیم. چیزهایی که الان وقتی فکرش رو می‌کنم خنده‌دار به نظر میاد اما اون روز لعنتی خیلی مهم به نظر می‌رسید … اصغر توی آشپزخونه اومد تا برای مهمان‌ها چای بریزه که اخم‌های درهم رفته‌ی من رو دید. پرسیدم برای چی این قدر اصرار کردی ؟ گفت خب دیدم کتلت داریم گفتم با هم بخوریم. گفتم ولی من این کتلت‌هارو برای فردا هم درست می‌کردم. گفت حالا مگه چی شده ؟ گفتم چیزی نیست اما... \r\nدر یخچالو باز کردم و چندتا گوجه فرنگی رو با عصبانیت بیرون آوردم و زیر آب گرفتم. پدرم سرش رو توی آشپزخونه کرد و گفت دختر جون، ببخشید که مزاحمت شدیم. می‌خوای نون‌ها رو برات ببُرم ؟ تازه یادم افتاد که حتی بهشون سلام هم نکرده بودم. تمام شب عین دوتا جوجه کوچولو روی مبل کز کرده بودن. وقتی شام آماده شد پدرم یک کتلت بیشتر برنداشت. مادرم هم به بهانه‌ی گیاه‌خواری چند قاشق سالاد کنار بشقابش ریخت و بازی بازی کرد. خورده و نخورده خداحافظی کردند و رفتند و این داستان فراموش شد و پانزده سال گذشت.\r\nچند روز پیش برای خودم کتلت درست می‌کردم که این داستان مثل برق از سرم گذشت : پیش خودم گفتم نکنه وقتی با اصغر حرف می‌زدم پدرم صحبت‌های ما را شنیده بود ؟ نکنه برای همین شام نخورد ؟ از تصورش مهره‌های پشتم تیر می‌کشید و دردی مثل دشنه توی دلم فرو می رفت. با حسرت به خودم میگفتم چرا هیچوقت برای اون نون سنگک‌ها ازش تشکر نکردم ؟ آخرین کتلت رو از روی ماهیتابه برداشتم، یه قطره روغن چکید توی ظرف و جلز محزونی کرد که بازم به خودم گفتم واقعا چهارتا کتلت چه اهمیتی داشت ؟ حقیقت مثل یک تکه آجر توی صورتم می‌خورد که “من آدم زمختی هستم” ؛ زمختی یعنی ندانستن قدر لحظه‌ها، یعنی نفهمیدن اهمیت چیزها، یعنی توجه به جزییات احمقانه و ندیدن مهم‌ترین‌ها. حالا دیگه چه اهمیتی داشت این سر دنیا وسط آشپزخونه‌ی خالی چنگال به دست کنار ماهیتابه‌ای که بوی کتلت می‌داد آه بکشم ؟؟؟ آخ که چقدر دلم تنگ شده براشون؛ فقط … فقط اگر الان پدر و مادرم از در تو میومدن، دیگه چه اهمیتی داشت خونه تمیز بود یا نه ؟ میوه داشتیم یا نه ؟ همه چیز کافی بود : من بودم و بوی عطر روسری مادرم ، دست پدرم و نون سنگک \r\nپدرم راست می‌گفت : نون خوب خیلی مهمه. من این روزها هرقدر بخوام می‌تونم کتلت درست کنم اما دیگه کسی زنگ این درو نمیزنه، کسی که توی دست‌هاش نون سنگک گرم و تازه و بی‌منتی بود که بوی مهربونی می‌داد. اما دیگه چه اهمیتی داره ؟ چیزهایی هست که وقتی از دستش دادی اهمیتش را می‌فهمی. \r\n"},{"id":360,"category_id":4,"category_code":"s4","source_id":35,"title":"قایم باشک","content":"زمانهای بسیار قدیم وقتی هنوز پای بشر به زمین نرسیده بودفضیلت ها و تباهی ها در همه جا شناور بودند\r\nآنها از بیکاری خسته و کسل شده بودند\r\nروزی همه فضابل و تباهی ها دور هم جمع شدند خسته تر و کسل تر از همیشه\r\nناگهان ذکاوت ایستاد و گفت: بیایید یک بازی بکنیم؛\r\nمثلا قایم باشک؛ همه از این پیشنهاد شاد شدند و دیوانگی فورا\r\nفریاد زد من چشم می گذارم من چشم می گذارم\r\nو از آنجایی که هیچ کس نمی خواست به دنبال دیوانگی برود همه قبول\r\nکردند او چشم بگذارد و به دنبال آنها بگردد\r\nدیوانگی جلوی درختی رفت و چشمهایش را بست و شروع کرد به\r\nشمردن ....یک...دو...سه...چهار...همه رفتند تا جایی پنهان شوند؛\r\nلطافت خود را به شاخ ماه آویزان کرد؛\r\nخیانت داخل انبوهی از زباله پنهان شد؛\r\nاصالت در میان ابرها مخفی گشت؛\r\nهوس به مرکز زمین رفت؛\r\nدروغ گفت زیر سنگی می روم اما به ته دریا رفت؛\r\nطمع داخل کیسه ای که دوخته بود مخفی شد\r\nو دیوانگی مشغول شمردن بود\r\nهفتاد و نه...هشتاد...هشتاد و یک\r\nهمه پنهان شده بودند به جز عشق که همواره مردد بود و نمیتوانست\r\nتصمیم بگیرد. و جای تعجب هم نیست چون همه می دانیم پنهان کردن عشق مشکل است\r\nدر همین حال دیوانگی به پایان شمارش می رسید\r\nنود و ینج ...نود و شش...نود و هفت... هنگامیکه دیوانگی به صد\r\nرسید, عشق پرید و در بوته گل رز پنهان شد\r\nدیوانگی فریاد زد دارم میام دارم میام\r\nاولین کسی را که پیدا کرد تنبلی بود؛ زیرا تنبلی، تنبلی اش آمده بود جایی\r\nپنهان شود و لطافت را یافت که به شاخ ماه آویزان بود\r\nدروغ ته چاه؛ هوس در مرکز زمین؛ یکی یکی همه را پیدا کرد جز عشق\r\nاو از یافتن عشق ناامید شده بود\r\nحسادت در گوشهایش زمزمه کرد؛ تو فقط باید عشق را پیدا کنی و او\r\nپشت بوته گل رز است\r\nدیوانگی شاخه چنگک مانندی را از درخت کند و با شدت و هیجان زیاد\r\nآن را در بوته گل رز فرو کرد. و دوباره، تا با صدای ناله ای متوقف\r\nشد . عشق از پشت بوته بیرون آمد با دستهایش صورت خود را پوشانده\r\nبود و از میان انگشتانش قطرات خون بیرون می زد\r\nشاخه ها به چشمان عشق فرو رفته بودند و او نمی توانست جایی را ببیند\r\nاو کور شده بود\r\nدیوانگی گفت من چه کردم؛ من چه کردم؛ چگونه می تواتم تو را درمانکنم\r\nعشق یاسخ داد: تو نمی توانی مرا درمان کنی، اما اگر می خواهی کاری بکنی؛ راهنمای من شو\r\nو اینگونه شد که از آن روز به بعد عشق کور است\r\nو دیوانگی همواره در کنار اوست\r\n"},{"id":361,"category_id":4,"category_code":"s4","source_id":36,"title":" جعبه ی مخفی","content":"زن وشوهری بیش از ۶۰ سال با یکدیگر زندگی مشترک داشتند. آنها همه چیز را به طور مساوی بین خود تقسیم کرده بودند. در مورد همه چیز با هم صحبت می کردند و هیچ چیز را از یکدیگر مخفی نمیکردند مگر یک چیز:\r\nیک جعبه کفش در بالای کمد پیرزن بود که از شوهرش خواسته بود هرگز آن را باز نکند و در مورد آن هم چیزی نپرسد.در همه ی این سالها پیرمرد آن را نادیده گرفته بود و در مورد جعبه فکر نمی کرد. اما بالاخره یکروز پیرزن به بستر بیماری افتاد و پزشکان از او قطع امید کردند.\r\nدر حالی که با یکدیگر امور باقی را رفع رجوع می کردند پیرمرد جعبه کفش را از بالای کمد آورد و نزد همسرش برد. پیرزن تصدیق کرد که وقت آن رسیده که همه چیز را در مورد آن جعبه به شوهرش بگوید. واز او خواست تا در جعه را باز کند. وقتی پیرمرد در جعبه را باز کرد دو عروسک بافتنی و دسته ای پول بالغ بر ۹۵هزار دلار پیدا کرد. پیرمرد در این باره ازهمسرش سوال کرد.\r\nپیرزن گفت:هنگامی که ما قول و قرار ازدواج گذاشتیم مادر بزرگم به من گفت که راز خوشبختی زندگی مشترک در این است که هیچ وقت مشاجره نکنید. او به من گفت که هر وقت از دست تو عصبانی شدم باید ساکت بمانم و یک عروسک ببافم.\r\nپیرمرد به شدت تحت تاثیر قرار گرفت. تمام سعی خود را به کار برد تا اشک هایش سرازیر نشود. فقط دو عروسک در جعبه بودند. پس همسرش فقط دو بار در طول تمام این سال های زندگی و عشق از او رنجیده بود. از این بابت در دلش شادمان شد.\r\nسپس به همسرش رو کرد و گفت:عزیزم، خوب، این در مورد عروسک ها بود. ولی در مورد این همه پول چطور؟ اینها از کجا آمده؟\r\nپیرزن در پاسخ گفت: آه عزیزم، این پولی است که از فروش عروسک ها بدست آورده ام..\r\n"},{"id":362,"category_id":4,"category_code":"s4","source_id":37,"title":"دوستت دارم...","content":"وقتی 15 سالت بود و من بهت گفتم که دوستت دارم ...صورتت از شرم قرمز شد و سرت رو به زیر انداختی و لبخند زدی...\r\nوقتی که 20 سالت بود و من بهت گفتم که دوستت دارم\r\nسرت رو روی شونه هام گذاشتی و دستم رو تو دستات گرفتی انگار از این که منو از دست بدی وحشت داشتی...\r\nوقتی که 25 سالت بود و من بهت گفتم که دوستت دارم \r\nصبحانه مو آماده کردی وبرام آوردی ..پیشونیم رو بوسیدی و\r\nگفتی بهتره عجله کنی ..داره دیرت می شه\r\nوقتی 30 سالت شد و من بهت گفتم دوستت دارم ..بهم گفتی اگه راستی راستی دوستم داری...\r\n.بعد از کارت زود بیا خونه\r\nوقتی 40 ساله شدی و من بهت گفتم که دوستت دارم\r\nتو داشتی میز شام رو تمیز می کردی و گفتی .باشه عزیزم ولی الان وقت اینه که بری\r\nتو درسها به بچه مون کمک کنی\r\nوقتی که 50 سالت شد و من بهت گفتم که دوستت دارم تو همونجور که بافتنی می بافتی\r\nبهم نکاه کردی و خندیدی\r\nوقتی 60 سالت شد بهت گفتم که چقدر دوستت دارم و تو به من لبخند زدی....\r\nوقتی که 70 ساله شدی و من بهت گفتم دوستت دارم در حالی که روی صندلی راحتیمون نشسته بودیم من نامه های عاشقانه ات رو که 50 سال پیش برای من نوشته بودی رو می خوندم و دستامون تو دست هم بود\r\nوقتی که 80 سالت شد ..این تو بودی که گفتی که من رو دوست داری\r\nنتونستم چیزی بگم ..فقط اشک در چشمام جمع شد\r\nاون روز بهترین روز زندگی من بود ..چون تو هم گفتی که منو دوست داری\r\nبه کسی که دوستش داری بگو که چقدر بهش علاقه داری\r\nو چقدر در زندگی براش ارزش قائل هستی\r\nچون زمانی که از دستش بدی\r\nمهم نیست که چقدر بلند فریاد بزنی\r\nاون دیگر صدایت را نخواهد شنید...\r\n"},{"id":363,"category_id":4,"category_code":"s4","source_id":38,"title":"قضاوت ","content":"دست عاطفه در دستم بود ، با هر بار دیدن دختر بچه ای که جسورانه از بالای سرسره پایین می آمد ، پاهایش جمع تر و فشار دستش به دست من بیش تر می شد ، توی دلم خاله ام را به خاطر تربیت نادرست عاطفه ملامت می کردم . اون که چیزی کم نداشت ، چرا باید آنقدر ترسو بار می آمد ؟\r\nنمی دانستم پدر و مادر آن بچه چه کسانی بودند ، اما برای یک لحظه آرزو کردم که ای کاش عاطفه هم بچه همان پدر و مادر بود ، تا فقط کمی از جسارت آن ها را به ارث می برد . از آن جا دور شدیم ، کمی بعد همان بچه را دیدیم که با دست های کوچکش پدر معلول و مادر نابینایش را هدایت می کرد. \r\nو این بار برای یک لحظه آرزو کردم که خدا مرا ببخشد ، عاشقانه عاطفه را بغل کردم و خدا را به خاطر کار های عجیب ولی زیبایش شکر کردم. \r\n"},{"id":364,"category_id":4,"category_code":"s4","source_id":39,"title":"ملاقات ممنوع","content":"زمانی که فیض کاشانی در قمصر کاشان زندگی می کرد ، پدر خانمش ، ملاصدرا ، چند روزی را به عنوان میهمان نزد او در قمصر به سر می برد. \r\nدر همان ایام در قمصر ، جوانی به خواستگاری دختری رفت . والدین دختر پس از قبول خواستگار ، شرط کردند که تا زمان عقد نه داماد حق دارد برای دیدن عروس به خانه عروس بیاید و نه عروس حق دارد به بیرون خانه برود. \r\nاز این رو ، عروس و داماد که عاشق و شیدای همدیگر بودند و می خواستند همدیگر را ببینند ، به فکر چهره ای افتادند که نه با شرط مخالفت بشود و نه والدین عروس متوجه بشوند . لذا عروس حیله ای زد و گفت : من فلان موقع به قصد تکاندن فرش به پشت بام می آیم و تو هم داخل کوچه بیا ، همدیگر را ببینیم. \r\nدر آن وقت مقرر ، دختر فرش خانه را به قصد تکاندن به پشت بام برد و فرش را تکان می داد و داماد هم از داخل کوچه نظاره گر جمال دلنشین عروس خانم بود و مدام این جملات را می خواند: \r\nاومدی به پشت بوندی اومدی فرش و تکوندی\r\nاومدی گردی نبوندی اومدی خودت و نشوندی\r\nدر این حال ، عارف بزرگوار ، ملاصدرا از کوچه عبور می کرد و این ماجرا را دید و شروع به گریه کردن کرد . او یک شبانه روز بلند گریه می کرد تا این که فیض کاشانی از او پرسید: \r\nچرا این گونه گریه می کنی ؟ \r\nملاصدرا گفت : من امروز پسری را دیدم که با معشوقه خود با خوشحالی سخن می گفت . گریه من از این جهت است که این همه سال درس خوانده ام و فلسفه نوشتم و خود را عاشق خدای متعال می دانم اما هنوز با این حال و صفایی که این پسر با معشوقه خود داشت من نتوانستم با خدای خود چنین سخن بگویم . لذا به حال خود گریه می کنم\r\n"},{"id":365,"category_id":4,"category_code":"s4","source_id":40,"title":"پدر و پسر ","content":"در روزگاری نه چندان دور، کشاورزی بود پیر و از کار افتاده. تنها کمکش پسری بود که ماموران فدرال او را به زندان برده بودند. فصل شخم نزدیک بود و کشاورز نمی دانست چگونه به تنهایی زمینش را شخم بزند.  \r\nروزی کشاورز به پسرش نامه ای نوشت و با او درد دل کرد: پسرم، زمان شخم زدن نزدیک است و من هم هیچ کسی را ندارم تا مرا کمک کند حال باید چه کنم؟ چاره ای بیاندیش. \r\nپسر چاره ایی اندیشید و جواب داد: پدر جان! مبادا زمین را شخم بزنی که من در آن زمین اسلحه ای پنهان کرده ام که اگر کسی آن را پیدا کند، من در درد سر بزرگی خواهم افتاد. \r\nروز بعد گروهی از ماموران دولتی درجستجوی اسلحه به زمین پیرمرد هچوم آوردند، و تمام آن مزرعه را به امید یافتن اسلحه زیر و رو کردند، اما اسلحه ایی پیدا نشد!\r\nچند روز بعد پسر نامه ایی دیگر فرستاد: پدرم! تنها روشی که می توانستم در شخم زدن زمین به تو کمک کنم، چنین بود. اکنون زمین آماده بذرپاشی است، امیدوارم ماموران دولتی آن را برایت خوب شخم زده باشند\r\n"},{"id":366,"category_id":4,"category_code":"s4","source_id":41,"title":"مادر ","content":"مادر من فقط یک چشم داشت . من از اون متنفر بودم ... اون همیشه مایه خجالت من بود0 \r\nاون برای امرار معاش خانواده برای معلم ها و بچه مدرسه ای ها غذا می پخت. \r\nیک روز اومده بود دم در مدرسه که به من سلام کنه و منو با خود به خونه ببره. \r\nخیلی خجالت کشیدم . آخه اون چطور تونست این کار رو با من بکنه ؟\r\nبه روی خودم نیاوردم ، فقط با تنفر بهش یه نگاه کردم و فورا از اون جا دور شدم. \r\nروز بعد یکی از همکلاسی ها منو مسخره کرد و گفت هووو .. مامان تو فقط یک چشم داره. \r\n فقط دلم می خواست یک جوری خودم رو گم و گور کنم . کاش زمین دهن وا می کرد و منو .. کاش مادرم یه جوری گم و گور می شد... \r\nروز بعد بهش گفتم اگه واقعا میخوای منو شاد و خوشحال کنی چرا نمی میری ؟\r\nاون هیچ جوابی نداد... \r\nحتی یک لحظه هم راجع به حرفی که زدم فکر نکردم ، چون خیلی عصبانی بودم.  \r\nاحساسات اون برای من هیچ اهمیتی نداشت.  \r\nدلم می خواست از اون خونه برم و دیگه هیچ کاری با اون نداشته باشم. \r\nسخت درس خوندم و موفق شدم برای ادامه تحصیل به سنگاپور برم. \r\nاون جا ازدواج کردم ، واسه خودم خونه خریدم ، زن و بچه و زندگی... \r\nاز زندگی ، بچه ها و آسایشی که داشتم خوشحال بودم. \r\nتا اینکه یه روز مادرم اومد به دیدن من \r\nاون سال ها منو ندیده بود و همین طور نوه هاشو \r\nوقتی ایستاده بود دم در بچه ها به اون خندیدند و من سرش داد کشیدم که چرا خودش رو دعوت کرده که بیاد اینجا ، اونم بی خبر  \r\nسرش داد زدم : \" چطور جرات کردی بیای به خونه من و بجه ها رو بترسونی ؟! گم شو از اینجا ! همین حالا!!!\"  \r\nاون به آرامی جواب داد : \" اوه خیلی معذرت می خوام مثل اینکه آدرس رو عوضی اومدم \" و بعد فورا رفت و از نظر ناپدید شد. \r\nیک روز یک دعوت نامه اومد در خونه من در سنگاپور برای شرکت در جشن تجدید دیدار دانش آموزان مدرسه. \r\nولی من به همسرم به دروغ گفتم که به یک سفر کاری میرم. \r\nبعد از مراسم ، رفتم به اون کلبه قدیمی خودمون ؛ البته فقط از روی کنجکاوی.  \r\nهمسایه ها گفتن که اون مرده.  \r\nولی من حتی یک قطره اشک هم نریختم. \r\nاونا یک نامه به من دادند که اون ازشون خواسته بود که به من بدن. \r\nای عزیزترین پسر من ، من همیشه به فکر تو بوده ام ، منو ببخش که به خونت تو سنگاپور اومدم و بچه هاتو ترسوندم.  \r\nخیلی خوشحال شدم وقتی شنیدم داری میآی اینجا  \r\nولی من ممکنه که نتونم از جام بلند شم که بیام تورو ببینم \r\nوقتی داشتی بزرگ می شدی از اینکه دائم باعث خجالت تو شدم خیلی متاسفم \r\nآخه می دونی ... وقتی تو خیلی کوچیک بودی تو یه تصادف یک چشمت رو از دست دادی \r\nبه عنوان یک مادر نمی تونستم تحمل کنم و ببینم که تو داری بزرگ می شی با یک چشم\r\nبنابراین چشم خودم رو دادم به تو. \r\nبرای من افتخار بود که پسرم می تونست با اون چشم به جای من دنیای جدید رو بطور کامل ببینه\r\n"},{"id":367,"category_id":4,"category_code":"s4","source_id":42,"title":"با عشق ","content":"فرمانروایی که می کوشید تا مرزهای جنوبی کشورش را گسترش دهد ، با مقاومت های سرداری محلی مواجه شد و مزاحمت های سردار به حدی رسید که خشم فرمانروا را برانگیخت . بنابراین او تعداد زیادی سرباز را مامور دستگیری سردار کرد . عاقبت سردار و همسرش به اسارت نیرو های فرمانروا در آمدند و برای محاکمه و مجازات به پایتخت فرستاده شدند. \r\nفرمانروا از سردار پرسید : ای سردار ، اگر من از گناهت بگذرم و آزادت کنم ، چه می کنی ؟\r\nسردار پاسخ داد : ای فرمانروا ، اگر از من بگذری به وطنم باز خواهم گشت و تا آخر عمر فرمانبردار تو خواهم بود.\r\nفرمانروا پرسید : و اگر از جان همسرت در گذرم ، آن گاه چه خواهی کرد ؟ \r\nسردار گفت : آن وقت جانم را فدایت خواهم کرد! \r\nفرمانروا از پاسخی که شنید آن چنان یکه خورد که نه تنها سردار و همسرش را بخشید ، بلکه او را به عنوان استاندار سرزمین جنوبی انتخاب کرد. \r\nسردار هنگام بازگشت از همسرش پرسید : آیا دیدی سرسری کاخ فرمانروا چقدر زیبا بود ؟ دقت کردی صندلی فرمانروا از طلای ناب ساخته شده بود ؟\r\nهمسر سردار گفت : راستش را بخواهی ، من به هیچ چیز توجه نکردم. \r\nسردار با تعجب پرسید : پس حواست کجا بود ؟ همسرش در حالی که به چشمان سردار نگاه می کرد به او گفت : تمام حواسم به تو بود . به چهره مردی نگاه می کردم که گفت حاضر است به خاطر من جانش را فدا کند!\r\n"},{"id":368,"category_id":4,"category_code":"s4","source_id":43,"title":"کلاف نخ  ","content":"وقتی حضرت یوسف رو آوردن تو بازار برده فروشای مصر، همه جمع شدن، حتی بزرگای مصر هم اومدن. تو جمعیت یه پیرزن بود که دو تا کلاف نخ تو دستش بود، یه نفر که کنارش ایستاده بود، ازش پرسید: \"اینا چیه؟\"\r\nپیرزن گفت: \"کلاف نخ\"!\r\nپرسید: \"واسه چی آوردی؟\"\r\nگفت : \"آوردم تا باهش یوسف رو بخرم\"\r\nطرف خندید گفت : \"آخه با دو تا کلاف نخ که نمیشه فردی مثل یوسف رو خرید، اونم جایی که بزرگای مصر اومدن تا اونو بخرن.\"\r\nپیرزن اشک تو چشاش جمع شد و گفت: \"می دونم با دو تا کلاف نمیشه یوسف رو خرید، اما میشه اسم من رو هم جز خریداراش نوشت!\"\r\n"},{"id":369,"category_id":4,"category_code":"s4","source_id":44,"title":"شاخه گل","content":"مردی مقابل گل فروشی ایستاده بود و میخواست دسته گلی برای مادرش که در شهر دیگری بود سفارش دهد تا برایش پست شود. \r\nوقتی از گل فروشی خارج شد، دختری را دید که روی جدول خیابان نشسته بود و هق هق گریه میکرد. مرد نزدیک رفت و از او پرسید: دختر خوب چرا گریه میکنی؟\r\nدختر در حالی که گریه میکرد، گفت: میخواستم برای مادرم یک شاخه گل رز بخرم ولی\r\nفقط 75 سنت دارم، درحالی که گل رز 2 دلار میشود. مرد لبخند زد و گفت: با من بیا، من برای تو یک شاخه گل رز قشنگ میخرم. \r\nوقتی از گلفروشی خارج میشدند، مرد به دختر گفت:\r\nمادرت کجاست؟ میخواهی ترا برسانم؟ \r\nدختر دست مرد را گرفت و گفت: آنجا و به طرف قبرستان اشاره کرد. \r\nمرد او را به قبرستان برد و دختر روی یک قبر تازه نشست و گل را آنجا گذاشت. \r\nمرد دلش گرفت و طاقت نیاورد، به گل فروشی برگشت، دسته گل را گرفت و 200 مایل رانندگی کرد تا خودش دسته گل را به مادرش بدهد\r\n"},{"id":370,"category_id":4,"category_code":"s4","source_id":45,"title":" بنده ی خدا","content":"شب کریسمس بود و هوا ، سرد و برفی \r\nپسرک ، در حالی ‌که پاهای برهنه ‌اش را روی برف جابه‌ جا می ‌کرد تا شاید سرمای برف‌ های کف پیاده ‌رو کم ‌تر آزارش بدهد ، صورتش را چسبانده بود به شیشه سرد فروشگاه و به داخل نگاه می ‌کرد. \r\nدر نگاهش چیزی موج می ‌زد ، انگاری که با نگاهش ، نداشته ‌هاش رو از خدا طلب می ‌کرد ، انگاری با چشم‌ هاش آرزو می ‌کرد.\r\nخانمی که قصد ورود به فروشگاه را داشت ، کمی مکث کرد و نگاهی به پسرک که محو تماشا بود انداخت و بعد رفت داخل فروشگاه . چند دقیقه بعد ، در حالی ‌که یک جفت کفش در دستانش بود بیرون آمد. \r\nآهای ، آقا پسر \r\nپسرک برگشت و به سمت خانم رفت . چشمانش برق می ‌زد وقتی آن خانم ، کفش‌ ها را به ‌او داد . پسرک با چشم ‌های خوشحالش و با صدای لرزان پرسید: \r\nشما خدا هستید ؟\r\nنه پسرم ، من تنها یکی از بندگان خدا هستم. \r\nآها ، می‌ دانستم که با خدا نسبتی دارید\r\n"},{"id":371,"category_id":4,"category_code":"s4","source_id":46,"title":"قلب پیرمرد ","content":"مرد جوانی وسط شهری ایستاده بود و ادعا می‌کرد که زیباترین قلب را در آن شهر دارد. جمعیت زیادی گرد آمدند. قلب او کاملا سالم بود و هیچ خدشه ای بر آن وارد نشده بود. پس همه تصدیق کردند که قلب او به راستی زیباترین قلبی است که تا کنون دیده اند.\r\nمرد جوان، در کمال افتخار با صدایی بلندتر به تعریف از قلب خود پرداخت. ناگهان پیر مردی مقابل جمعیت آمد و گفت: اما قلب تو به زیبایی قلب من نیست. مرد جوان و بقیه جمعیت به قلب پیر مرد نگاه کردند. قلب او با قدرت تمام می‌تپید، اما پر از زخم بود. قسمت‌هایی از قلب او برداشته شده و تکه‌هایی جایگزین آن شده بود. اما آنها به درستی جاهای خالی را پر نکرده بودند و گوشه‌هایی دندانه دندانه در قلب او دیده می‌شد. در بعضی نقاط شیار‌های عمیقی وجود داشت که هیچ تکه ای آنها را پر نکرده بود. مردم با نگاهی خیره به او می‌نگریستند و با خود فکر می‌کردند این پیر مرد چطور ادعا می‌کند که قلب زیباتری دارد. \r\nمرد جوان به قلب پیر مرد اشاره کرد و با خنده گفت: تو حتما شوخی می‌کنی، قلبت را با قلب من مقایسه کن. قلب تو، تنها مشتی زخم و خراش و بریدگی است.\r\nپیر مرد گفت: درست است قلب تو سالم به نظر می‌رسد، اما من هرگز قلبم را با قلب تو عوض نمی‌کنم. می‌دانی، هر کدام از این زخمها نشانگر انسانی است که من عشقم را به او داده ام، در واقع من بخشی از قلبم را جدا کرده و به او بخشیده ام. گاهی او هم بخشی از قلب خود را به من داده که به جای آن تکه بخشیده شده قرار داده ام. اما چون این تکه‌ها مثل هم نبوده اند، گوشه‌هایی دندانه دندانه در قلبم دارم که برایم عزیزند، چرا که یاد آور عشق میان دو انسان هستند.\r\nبعضی قسمت های قلبم را به کسانی بخشیده ام. اما آنها چیزی از قلب خود به من نداده اند. اینها همین شیارهایی عمیق هستند. گرچه دردآورند، اما یادآور عشقی هستند که داشته ام امیدوارم که آنها هم روزی بازگردند و این شیار‌های عمیق را با تکه ای که من در انتظارش بوده ام، پر کنند.\r\nحالا می‌بینی زیبایی واقعی چیست؟ مرد جوان بی هیچ سخنی ایستاد. در حالی که اشک از گونه‌هایش سرازیر بود، به سمت پیر مرد رفت. از قلب جوان و سالم خود تکه ای بیرون آورد و با دستهای لرزان به پیر مرد تقدیم کرد.\r\nپیرمرد آن را گرفت و در قلبش جای داد و بخشی از قلب پیر و زخمی‌ خود را جای زخم مرد جوان گذاشت. مرد جوان به قلبش نگاه کرد، دیگر سالم نبود، اما از همیشه زیباتر بود. عشق از قلب پیر مرد به قلب او نفوذ کرده بود\r\n"},{"id":372,"category_id":4,"category_code":"s4","source_id":47,"title":"انتظار","content":"امروز صبح که بیدار شدی ، نگاهت می کردم... و امیدوار بودم که با من حرف بزنی ، حتی برای چند کلمه... نظرم را بپرسی یا برای اتفاق خوبی که دیروز در زندگی ات افتاد ، از من تشکر کنی... اما متوجه شدم که خیلی مشغولی ، مشغول انتخاب لباسی که می خواستی بپوشی... وقتی داشتی این طرف و آن طرف می دویدی تا حاضر شوی فکر می کردم چند دقیقه ای وقت داری که بایستی و به من بگوی : سلام... \r\nاما تو خیلی مشغول بودی... یک بار مجبور شدی منتظر بشوی و برای مدت یک ربع کاری نداشتی....جز آنکه روی یک صندلی بنشینی. بعد دیدمت که از جا پریدی . خیال کردم می خواهی با من صحبت کنی... اما به طرف تلفن دویدی و در عوض به دوستت تلفن کردی تا از آخرین شایعات با خبر شوی... \r\nتمام روز با صبوری منتظر بودم... با اون همه کارهای مختلف گمان می کنم که اصلا وقت نداشتی با من حرف بزنی... \r\nمتوجه شدم قبل از نهار هی دور و برت را نگاه می کنی ، شاید چون خجالت می کشیدی که با من حرف بزنی، سرت را به سوی من خم نکردی... \r\nتو به خانه رفتی و به نظر می رسید که هنوز خیلی کارها برای انجام دادن داری... بعد از انجام دادن چند کار ، تلویزیون را روشن کردی... \r\nنمی دانم تلویزیون دوست داری یا نه ؟ در آن چیز های زیادی نشان می دهند و تو هر روز مدت زیادی از روزت را جلوی آن می گذرانی، در حالی که درباره هیچ چیز فکر نمی کنی و فقط از برنامه هایش لذت می بری... \r\nباز هم صبورانه انتظارت را کشیدم... و تو در حالی که تلویزیون را نگاه می کردی شام خوردی ، و باز هم با من صحبت نکردی.\r\nموقع خواب ... فکر می کنم خیلی خسته بودی... بعد از آنکه به اعضای خانوادت شب بخیر گفتی ، به رختخواب رفتی و فورا به خواب رفتی... \r\nاشکالی ندارد. احتمالا متوجه نشدی که من همیشه در کنارت و برای کمک به تو آماده ام... من صبورم ، بیش از آنچه تو فکرش را بکنی... حتی دلم می خواهد یادت بدهم که تو چطور با دیگران صبور باشی ... من آنقدر دوستت دارم که هر روز منتظرت هستم... منتظر یک سر تکان دادن ، دعا ، فکر ، یا گوشه ای از قلبت که متشکر باشد... خیلی سخت است که یک مکالمه یک طرفه داشته باشی .... خوب ، من باز هم منتظرت هستم، سراسر پر از عشق تو ... به امید آنکه شاید امروز کمی هم به من وقت بدهی ... آیا وقت داری که این را برای فرد دیگری هم بفرستی؟ اگر نه ، عیبی ندارد ، می فهمم و هنوز هم دوستت دارم. روز خوبی داشته باشی...\r\nدوست و دوستدارت خدا\r\n"},{"id":373,"category_id":4,"category_code":"s4","source_id":48,"title":" دو برادر","content":"دو برادر با هم در یک مزرعه‌ی خانوادگی کار می‌کردند. یکی از برادرها متأهل بود و خانواده‌ی بزرگی داشت و دیگری مجرد بود.\r\nآن ‌دو در پایان هر روز، ماحصل کار و زحمت‌شان را به‌طور مساوی بین هم تقسیم می‌کردند.\r\nروزی برادر مجرد پیش خود اندیشید: این منصفانه نیست که ماحصل کار و زحمت‌مان را به‌طور مساوی با هم تقسیم کنیم. من مجرد هستم و تنها، و بالطبع نیازم هم خیلی کم است. به‌همین خاطر، او هر شب کیسه‌ای گندم از انبار کوچک خود برمی‌داشت. مزرعه‌ی مابین منزل خود و برادرش را پنهانی می‌پیمود و کیسه‌ی گندم را به انبار برادرش حمل می‌کرد.\r\nاز طرف دیگر، برادر متأهل هم پیش خود اندیشید: این منصفانه نیست که ماحصل کار و زحمت‌مان را به‌طور مساوی با هم تقسیم کنیم. از هرچه که بگذریم، من متأهل هستم و صاحب زن و بچه‌هایی که می‌توانند در سال‌های آتی زندگی، به یاری‌ام بشتابند. برادرم تک و تنهاست و کسی را ندارد تا در آن سال‌ها یار و یاورش باشد. به‌همین خاطر، او نیز هر شب کیسه‌ای گندم از انبار کوچک خود برمی‌داشت، مزرعه‌ی مابین منزل خود و برادرش را پنهانی می‌پیمود و کیسه‌ی گندم را به انبار برادرش حمل می‌کرد.\r\nسال‌های متمادی، هر دو برادر گیج و مبهوت بودند، چون گندم انبار آن‌دو هرگز کم نمی‌شد.\r\nیک‌شب تاریک، زمانی که هر دو برادر، پنهانی در حال حمل گندم به انبار برادر دیگر بودند، به‌ناگاه به هم برخوردند.\r\nآن‌دو پس از یک مکث طولانی متوجه حادثه‌ای که در طی سالیان گذشته به‌وقوع می‌پیوست شدند.\r\nدو برادر، کیسه‌های گندم را بر زمین نهادند و همدیگر را در آغوش کشیدند.\r\n"},{"id":374,"category_id":4,"category_code":"s4","source_id":49,"title":"کلاغ ","content":"مردی ۸۵ ساله با پسر تحصیل کرده ۴۵ ساله اش روی مبل خانه خود نشسته بودند ناگهان کلاغی کنار پنجره‌شان نشست. پدر از فرزندش پرسید: این چیه؟ پسر پاسخ داد: کلاغ\r\nپس از چند دقیقه دوباره پرسید این چیه؟ پسر گفت : بابا من که همین الان بهتون گفتم: کلاغه\r\nبعد از مدت کوتاهی پیر مرد برای سومین بار پرسید: این چیه؟ عصبانیت در پسرش موج میزد و با همان حالت گفت: کلاغه کلاغ...!\r\nپدر به اتاقش رفت و با دفتر خاطراتی قدیمی برگشت. صفحه ای را باز کرد و به \r\nپسرش گفت که آن را بخواند.\r\nدر آن صفحه این طور نوشته شده بود:\r\nامروز پسر کوچکم ۳ سال دارد. و روی مبل نشسته است هنگامی که کلاغی روی پنجره نشست پسرم ۲۳ بار نامش را از من پرسید و من ۲۳ بار به او گفتم که نامش کلاغ است.\r\nهر بار او را عاشقانه بغل می‌کردم و به او جواب می‌دادم و به هیچ وجه عصبانی  نمی‌شدم و در عوض علاقه بیشتری نسبت به او پیدا می‌کردم\r\n"},{"id":375,"category_id":4,"category_code":"s4","source_id":50,"title":"نقاشی ","content":"مادر خسته از خريد برگشت و به زحمت زنبيل سنگين را داخل خانه آورد.\r\nپسر بزرگش که منتظر بود،جلو دويد و گفت مامان،مامان! وقتي من در حياط بازي مي‏کردم و بابا داشت با تلفن صحبت مي‏کرد،تامي با ماژيک روي ديوار اتاقي که شما تازه رنگش کرده ايد،نقاشي کرد!\r\nمادر عصباني به اتاق تامي کوچولو رفت.\r\nتامي از ترس زير تخت قايم شده بود، مادر فرياد زد: تو پسر خيلي بدي هستي و تمام ماژيک‏هايش را در سطل آشغال ريخت.تامي از غصه گريه کرد. ده دقيقه بعد وقتي مادر وارد اتاق پذيرائي شد،قلبش گرفت.\r\nتامي روي ديوار با ماژيک قرمز يک قلب بزرگ کشيده بود و داخلش نوشته بود: مادر دوست دارم!\r\nمادر در حاليکه اشک مي‏ريخت به آشپزخانه برگشت و يک قاب خالي آورد و آن را دور قلب آويزان کرد.  تابلوي قرمز هنوز هم در اتاق پذيرائي بر ديوار است\r\n"},{"id":376,"category_id":4,"category_code":"s4","source_id":51,"title":"خواب ","content":" خوابی دیدم\r\nخواب دیدم در ساحل با خدا قدم می زنم. بر پهنه آسمان صحنه هایی از زندگی ام برق زد. در هر صحنه، دو جفت جای پا روی شن ها دیدم. یکی متعلق به من و دیگری متعلق به خدا. وقتی آخرین صحنه در مقابلم برق زد، به پشت سر و به جای پاهای روی شن نگاه کردم. متوجه شدم که چندین بار در طول مسیر زندگی ام، فقط یک جفت جای پا روی شن بوده است. همچنین متوجه شدم که این در سخت ترین و غمگین ترین دوران زندگی ام بوده است. این واقعا\" برایم ناراحت کننده بود و درباره اش از خدا سئوال کردم: \r\nخدایا، تو گفتی اگر به دنبال تو بیایم، در تمام راه با من خواهی بود. ولی دیدم که در سخت ترین دوران زندگی ام، فقط یک جفت جای پا وجود داشت. نمی فهمم چرا هنگامی که بیش از هر وقت دیگر به تو نیاز داشتم، مرا تنها گذاشتی.\r\nخدا پاسخ داد: \r\nبنده بسیار عزیزم، من در کنارت هستم و هرگز تنهایت نخواهم گذاشت. اگر در آزمون ها و رنج ها، فقط یک جفت جای پا دیدی، زمانی بود که تو را در آغوشم حمل می کردم\r\n"},{"id":377,"category_id":4,"category_code":"s4","source_id":52,"title":"فرشته ی زمینی ","content":"تقدیم به همه مادرهای مهربان\r\nکودکی که آماده تولد بود، نزد خدا رفت و پرسید : می گویند شما می خواهید مرا به زمین بفرستید، اما من به این کوچکی و بدون هیچ کمکی چگونه می توانم برای زندگی به آنجا بروم؟\r\nخداوند پاسخ داد : از میان تعداد زیاد فرشتگانم، من یک فرشته برای تو در نظر گرفته ام. او در انتظار توست و از تو نگهداری خواهد کرد. \r\nاما کودک علاقه ایی به رفتن نداشت: اینجا در بهشت، من هیچ کاری جز خندیدن و آواز خواندن ندارم و اینها برای شادی و خوشی من کافی هستند. \r\nخداوند لبخندی زد و گفت : فرشته تو برایت آواز خواهد خواند و هر روز به تو لبخند خواهد زد. تو عشق او را احساس خواهی کرد و شاد خواهی بود. \r\nکودک ادامه داد: من چطور می توانم بفهمم مردم چه می گویند، وقتی زبان آنها را نمی دانم؟\r\nخداوند او را نوازش کرد و گفت :فرشته تو ، زیباترین و شیرین ترین واژه هایی را که ممکن است بشنوی در گوش تو زمزمه خواهد کرد. او با دقت و صبوری به تو یاد خواهد داد که چگونه صحبت کنی.\r\nکودک با ناراحتی گفت : وقتی می خواهم با شما صحبت کنم، چه کنم؟ \r\nخدا برای این سوالش هم پاسخ داد: فرشته ات دستهایت را در کنار هم خواهد گذاشت و به تو یاد خواهد داد که چگونه دعا کنی. \r\nکودک سرش را برگرداند و پرسید: شنیده ام در زمین انسان های بدی هم زندگی می کنند. چه کسی از من محافظت خواهد کرد؟ \r\n!- فرشته ام از تو مواظبت خواهد کرد حتی اگر به قیمت جانش تمام شود \r\nکودک با نگرانی ادامه داد : اما من همیشه به این دلیل که دیگر نمی توانم شما را ببینم ناراحت خواهم بود.\r\nخداوند لبخند زد و گفت: فرشته ات همیشه در مورد من برایت صحبت خواهد کرد. و به تو راه بازگشت نزد من را خواهد آموخت، گر چه من همیشه در کنار تو خواهم بود. \r\nدر آن هنگام بهشت آرام بود، اما صداهائی از زمین شنیده می شد. کودک ؛ هر چند دوست نداشت؛ ولی می دانست که باید به زودی سفرش را آغاز کند. او به آرامی یک سؤال دیگر از خداوند پرسید : خدایا! اگر من باید همین حالا بروم ، لطفاً نام فرشته ام را به من بگوئید. \r\nخداوند او را نوازش کرد و پاسخ داد: نام فرشته ات اهمیتی ندارد. می توانی او را مادر صدا کنی\r\n"},{"id":378,"category_id":4,"category_code":"s4","source_id":53,"title":"دو بیمار ","content":"در بیمارستانی، دو بیمار در یک اتاق بستری بودند. یکی از بیماران اجازه داشت که هر روز بعد از ظهر یک ساعت روی تختش که کنار تنها پنجره اتاق بود بنشیند ولی بیمار دیگر مجبور بود هیچ تکانی نخورد و همیشه پشت به هم اتاقیش روی تخت بخوابد. آنها ساعتها با هم صحبت می‏کردند؛ از همسر، خانواده، خانه، سربازی یا تعطیلاتشان با هم حرف می‏زدند و هر روز بعد از ظهر، بیماری که تختش کنار پنجره بود، می‏نشست و تمام چیزهائی که بیرون از پنجره می‏دید.\r\nبرای هم اتاقیش توصیف می‏کرد. پنجره، رو به یک پارک بود که دریاچه زیبائی داشت. مرغابیها و قوها در دریاچه شنا می‏کردند و کودکان با قایقهای تفریحیشان در آب سرگرم بودند. درختان کهن، به منظره بیرون، زیبایی خاصی بخشیده بود و تصویری زیبا از شهر در افق دور دست دیده می‏شد. همان‏طور که مرد کنار پنجره این جزئیات را توصیف می‏کرد، هم اتاقیش چشمانش را می‏بست و این مناظر را در ذهن خود مجسم می‏کرد و روحی تازه می‏گرفت.روزها و هفته‏ها سپری شد. تا اینکه روزی مرد کنار پنجره از دنیا رفت و مستخدمان بیمارستان جسد او را از اتاق بیرون بردند. مرد دیگر که بسیار ناراحت بود تقاضا کرد که تختش را به کنار پنجره منتقل کنند. \r\nپرستار این کار را با رضایت انجام داد. مرد به آرامی و با درد بسیار، خود را به سمت پنجره کشاند تا اولین نگاهش را به دنیای بیرون از پنجره بیندازد. بالاخره می‏توانست آن منظره زیبا را با چشمان خودش ببیند ولی در کمال تعجب، با یک دیوار بلند مواجه شد! مرد متعجب به پرستار گفت که هم اتاقیش همیشه مناظر دل انگیزی را از پشت پنجره برای او توصیف می‏کرده است.\r\nپرستار پاسخ داد:\r\nولی آن مرد کاملا نابینا بود!\r\n"},{"id":379,"category_id":4,"category_code":"s4","source_id":54,"title":"ایثار ","content":"مرد و زن جوانی سوار بر موتور در دل شب می راندند. آنها عاشقانه یکدیگر را دوست داشتند. \r\nزن: یواش تر برو, من می ترسم. \r\nمرد : نه, اینجوری خیلی بهتره. \r\nزن : خواهش میکنم, من خیلی می ترسم. \r\nمرد : خوب, اما اول باید بگی که دوستم داری. \r\nزن : دوستت دارم, حالا میشه یواش تر برونی. \r\nمرد : منو محکم بگیر.\r\nزن: \r\nخوب حالا میشه یواش تر بری.\r\nمرد : باشه به شرط اینکه کلاه کاسکت منو برداری و روی سر خودت بذاری, آخه نمیتونم \r\nراحت برونم. اذیتم میکنه. \r\nروز بعد واقعه ای در روزنامه ثبت شده بود. برخورد موتور سیکلت با ساختمان حادثه \r\nآفرید. در این سانحه که به دلیل بریدن ترمز موتورسیکلت رخ داد, یکی از دو سرنشی \r\nزنده ماند و دیگری درگذشت. مرد جوان از خالی شدن ترمز آگاهی یافته بود. پس بدون \r\nاینکه زن جوان را مطلع کند با ترفندی کلاه کاسکت را بر سر او گذاشت و خواست تا برای \r\nآخرین بار دوستت دارم را از زبان او بشنود و خودش رفت تا او زنده بماند. \r\n"},{"id":380,"category_id":4,"category_code":"s4","source_id":55,"title":"میوه فروش ","content":"شب سردی بود …. پیرزن بیرون میوه فروشی زل زده بود به مردمی که میوه میخریدن... شاگرد میوه فروش تند تند پاکت های میوه رو توی ماشین مشتری ها میذاشت و انعام میگرفت. \r\nپیرزن باخودش فکر میکرد چی میشد اونم میتونست میوه بخره ببره خونه … رفت نزدیک تر … چشمش افتاد به جعبه چوبی بیرون مغازه که میوه های خراب و گندیده داخلش بود … با خودش گفت چه خوبه سالم ترهاشو ببره خونه … میتونست قسمت های خراب میوه ها رو جدا کنه وبقیه رو بده به بچه هاش … هم اسراف نمیشد هم\r\nبچه هاش شاد میشدن... \r\nبرق خوشحالی توی چشماش دوید ..دیگه سردش نبود !پیرزن رفت جلو نشست پای جعبه میوه …. تا دستش رو برد داخل جعبه شاگرد میوه فروش گفت : دست نزن نِنه ! وَخه برو دُنبال کارت ! پیرزن زود بلند شد …خجالت کشید ! چند تا از مشتریها نگاهش کردند  صورتش رو قرص گرفت … دوباره سردش شد ! راهش رو کشید رفت...! \r\nچند قدم دور شده بود که یه خانمی صداش زد : مادر جان …مادر جان ! پیرزن ایستاد … برگشت و به زن نگاه کرد ! زن مانتویی لبخندی زد و بهش گفت اینارو برای شما گرفتم ! سه تا پلاستیک دستش بود پر از میوه … موز و پرتغال و انار...  \r\nپیرزن گفت : دستِت دَرد نِکُنه نِنه….. مُو مُستَحق نیستُم! \r\nزن گفت : اما من مستحقم مادر من … مستحق داشتن شعور انسان بودن و به هم نوع توجه کردن …اگه اینارو نگیری دلمو شکستی ! جون بچه هات بگیر! \r\n... زن منتظر جواب پیرزن نموند … میوه هارو داد دست پیرزن و سریع دور شد  \r\nپیرزن هنوز ایستاده بود و رفتن زن رو نگاه میکرد … قطره اشکی که تو چشمش جمع شده بود غلتید روی صورتش … دوباره گرمش شده بود … با صدای لرزانی گفت : پیر شی ننه …. پیر شی ! خیر بیبینی این شب چله مادر\r\n"},{"id":381,"category_id":4,"category_code":"s4","source_id":56,"title":"یک ساعت ","content":"مردی، دیروقت، خسته از سرکار به خانه بازگشت. دم در، پسر پنج ساله اش را دید که در انتظار او بود:\r\nبابا! یک سوال از شما بپرسم؟ \r\nبله حتما\". چه سوالی؟\r\nبابا، شما برای هر ساعت کار، چقدر پول می گیرید؟\r\nمرد با عصبانیت پاسخ داد:\r\nاین به تو ربطی ندارد. چرا چنین سوالی می کنی؟\r\nفقط می خواهم بدانم. بگویید برای هرساعت کار، چقدر پول می گیرید؟\r\nاگر باید بدانی خوب می گویم، 20 دلار\r\nپسر کوچک؛ در حالی که سرش پایین بود؛ آه کشید. سپس به مرد نگاه کرد و گفت:\r\nمی شود لطفا\" 10 دلار به من قرض بدهید؟\r\nمرد بیشتر عصبانی شد و گفت:\r\n- اگر دلیلت برای پرسیدن این سوال، فقط این بود که پولی برای خریدن یک اسباب بازی مزخرف از من بگیری، سریع به اتاقت برو، فکر کن و ببین که چرا این قدر خودخواه هستی. من هر روز، سخت کار می کنم و برای چنین رفتارهای کودکانه ای وقت ندارم\r\nپسر کوچک ، آرام به اتاقش رفت و در را بست.\r\nمرد نشست و باز هم عصبانی تر شد:\r\n- چطور به خودش اجازه می دهد برای گرفتن پول از من چنین سوالی بپرسد؟ \r\nبعد از حدود یک ساعت، مرد آرام تر شد و فکر کرد که شاید با پسر کوچکش خیلی تند و خشن رفتار کرده است. شاید واقعا\" چیزی بوده که او برای خریدش به 10 دلار نیاز داشته است. به خصوص اینکه خیلی کم پیش می آمد پسرک از پدرش درخواست پول کند. مرد به سمت اتاق پسر رفت و در را باز کرد:\r\nخواب هستی پسرم؟\r\nنه پدر، بیدارم\r\n- فکر کردم شاید با تو خشن رفتار کرده ام. امروز کارم سخت و طولانی بود و همه ناراحتی هایم را سر تو خالی کردم. بیا این 10 دلاری که خواسته بودی. \r\nپسر کوچولو نشست، خندید و فریاد زد:\r\nمتشکرم بابا\r\nبعد دستش را زیر بالشش برد و چند اسکناس مچاله شده در آورد. \r\nمرد وقتی دید پسر کوچولو خودش هم پول داشته است، دوباره عصبانی شد و غرولند کنان گفت:\r\n- با اینکه خودت پول داشتی، چرا باز هم پول خواستی؟\r\nپسر کوچولو پاسخ داد:\r\n- برای اینکه پولم کافی نبود، ولی الان هست. حالا من 20 دلار دارم\r\nآیا می توانم یک ساعت از کار شما را بخرم تا فردا زودتر به خانه بیایید؟ دوست دارم با شما، شام بخورم...\r\n"},{"id":382,"category_id":4,"category_code":"s4","source_id":57,"title":"اعتماد","content":"پسر به دختر گفت اگه یه روزی به قلب احتیاج داشته باشی اولین نفری هستم\r\nكه میام تا قلبمو با تمام وجودم تقدیمت كنم.دختر لبخندی زد و گفت ممنونم\r\nتا اینكه یك روز اون اتفاق افتاد..حال دختر خوب نبود..نیاز فوری به قلب داشت..از \r\nپسر خبری نبود..دختر با خودش میگفت :میدونی كه من هیچوقت نمیذاشتم تو \r\nقلبتو به من بدی و به خاطر من خودتو فدا كنی..ولی این بود اون حرفات..حتی \r\nبرای دیدنم هم نیومدی...شاید من دیگه هیچوقت زنده نباشم.. آرام گریست و \r\nدیگر چیزی نفهمید...\r\nچشمانش را باز كرد..دكتر بالای سرش بود.به دكتر گفت چه اتفاقی افتاده؟دكتر \r\nگفت نگران نباشید پیوند قلبتون با موفقیت انجام شده.شما باید استراحت \r\nكنید..درضمن این نامه برای شماست.\r\nدختر نامه رو برداشت.اثری از اسم روی پاكت دیده نمیشد. بازش كرد و درون آن \r\nچنین نوشته شده بود:\r\nسلام عزیزم.الان كه این نامه رو میخونی من در قلب تو زنده ام.از دستم ناراحت \r\nنباش كه بهت سر نزدم چون میدونستم اگه بیام هرگز نمیذاری كه قلبمو بهت \r\nبدم..پس نیومدم تا بتونم این كارو انجام بدم..امیدوارم عملت موفقیت آمیز باشه.\r\n(عاشقتم تا بینهایت)\r\nدختر نمیتوانست باور كند..اون این كارو كرده بود..اون قلبشو به دختر داده بود... \r\nآرام اسم پسر را صدا كرد و قطره های اشك روی صورتش جاری شد..و به \r\nخودش گفت چرا هیچوقت حرفاشو باور نكردم..\r\n"},{"id":383,"category_id":4,"category_code":"s4","source_id":58,"title":"پل ","content":"سال ها دو برادر با هم در مزرعه ای که از پدرشان به ارث رسیده بود ، زندگی می کردند  یک روز به خاطر یک سوء تفاهم کوچک ، با هم جرو بحث کردند . پس از چند هفته سکوت ، اختلاف آنها زیاد شد و از هم جدا شدند.\r\nیک روز صبح در خانه برادر بزرگ تر به صدا درآمد . وقتی در را باز کرد ، مرد نجاری را دید . نجار گفت : من چند روزی است که دنبال کار می گردم ، فکر کردم شاید شما کمی خرده کاری در خانه و مزرعه داشته باشید ، آیا امکان دارد که کمکتان کنم ؟ \r\nبرادر بزرگ تر جواب داد : بله ، اتفاقاً من یک مقدار کار دارم . به آن نهر در وسط مزرعه نگاه کن ، آن همسایه در حقیقت برادر کوچک تر من است . او هفته گذشته چند نفر را استخدام کرد تا وسط مزرعه را کندند و این نهر آب بین مزرعه ما افتاد . او حتماً این کار را بخاطر کینه ای که از من به دل دارد ، انجام داده. \r\nسپس به انبار مزرعه اشاره کرد و گفت : در انبار مقداری الوار دارم ، از تو می خواهم تا بین مزرعه من و برادرم حصار بکشی تا دیگر او را نبینم. \r\nنجار پذیرفت و شروع کرد به اندازه گیری و اره کردن الوار . برادر بزرگ تر به نجار گفت : من برای خرید به شهر می روم ، اگر وسیله ای نیاز داری برایت بخرم. \r\nنجار در حالی که به شدت مشغول کار بود ، جواب داد : نه ، چیزی لازم ندارم. \r\nهنگام غروب وقتی برادر بزرگ تر به مزرعه برگشت ، چشمانش از تعجب گرد شد . حصاری در کار نبود . نجار به جای حصار یک پل روی نهر ساخته بود.  \r\nبرادر بزرگ تر با عصبانیت رو به نجار کرد و گفت : مگر من به تو نگفته بودم برایم حصار بسازی ؟ \r\nدر همین لحظه برادر کوچک تر از راه رسید و با دیدن پل فکر کرد که برادرش دستور ساختن آن را داده ، از روی پل عبور کرد و برادر بزرگترش را در آغوش گرفت و از او برای کندن نهر معذرت خواست. \r\nوقتی برادر بزرگ تر برگشت ، نجار را دید که جعبه ابزارش را روی دوشش گذاشته و در حال رفتن است. \r\nنزد او رفت و بعد از تشکر ، از او خواست تا چند روزی مهمان او و برادرش باشد. \r\nنجار گفت : دوست دارم بمانم ولی پل های زیادی هست که باید آنها را بسازم.\r\n"},{"id":384,"category_id":4,"category_code":"s4","source_id":59,"title":"مادر شوهر ","content":"دختری ازدواج کرد و به خانه شوهر رفت ولی هرگز نمی توانست با مادر شوهرش کنار بیاید و هر روز باهم جرّ و بحث می کردند.\r\nعاقبت روزی دختر نزد داروسازی که دوست صمیمی پدرش بود رفت و از او تقاضا کرد تا سمی به او بدهد تا بتواند مادر شوهرش را بکشد!\r\nداروساز گفت که اگر سم خطرناکی به او بدهد و مادر شوهرش کشته شود همه به او شک خواهند برد. پس معجونی به دختر داد و گفت : که هر روز مقداری از آن را در غذای مادر شوهرت بریز تا سم معجون کم کم در او اثر کند و او را بکشد و توصیه کرد تا در این مدت با مادر شوهر مدارا کند تا کسی به او شک نکند. \r\nدختر معجون را گرفت و خوشحال به خانه برگشت و هر روز مقداری از آن را در غذای مادر شوهر می ریخت و با مهربانی به او می داد.\r\nهفته ها گذشت و با مهر و محبت عروس، اخلاق مادر شوهر هم بهتر و بهتر شد تا آنجا که یک روز دختر نزد داروساز رفت و به او گفت: آقای دکتر عزیز دیگر از مادر شوهرم متنفر نیستم. حالا او را مانند مادرم دوست دارم و دیگر دلم نمی خواهد بمیرد. خواهش می کنم داروی دیگری به من بدهید تا سم را از بدنش خارج کند.\r\nداروساز لبخندی زد و گفت: دخترم نگران نباش آن معجونی که به تو دادم سم نبود، بلکه سم در ذهن خود تو بود که حالا با عشق به مادر شوهرت از بین رفته است.\r\n"},{"id":385,"category_id":4,"category_code":"s4","source_id":60,"title":"آخرین سفر ","content":"چند ماهی بود نامزد شده بودند پسر خوبی بود لاغر اندام بلند قد با صورتی زیبا و باوجودی پر از محبت و گرمای خالص زندگی .ولی هنوزاون نتونسته بوداونطوری که باید بهش نزدیک بشه وهمیشه یه جوری ازش فراری بود .خودش هم نمیدونست چرا؟شاید بخاطر اعتقادات شدید مذهبی مادرش ویا سخت گیری های پدرش ویا موعظه های بی پایان کشیش .اما هر چی بود مثل یک حباب نامریی بینشان فاصله انداخته بود تا اینکه ارتش تمام جوانان را برای سربازی فراخواند.\r\nجنگ جهانی دوم شروع شده بود.همه چی خیلی سریع اتفاق افتاد وقتی بخودش اومد که داشت تو ایستگاه قطار براش دست تکون میداد قبل از اینکه قطار کاملا از ایستگاه دور بشه سرش رو از پنجره قطار بیرون اورد و با همون زیبایی معصومانش داد زد قول بده منتظرم بمونی برمیگردم .هفته های اول معمولی و مثل قبل بود اما کم کم روزا شروع کرد به کش اومدن و یواش یواش تلخ شدن.یه بی قراری و پریشونی و نگرانی سراغش اومده بود انگار چیزی رو گم کرده بود.اخبار جنگ هر روز وحشتناک تر میشد و خبرهای بدی از جبهه ها میرسید.و این غصه هاش رو بیشتر میکرد.پدرش نوشتن هر نامه ای رو برای هر دو تاشون ممنوع کرده بود چون به نظر پدرش مخالف اعتقادات دینیشان بود.تا اینکه اونروز نحس فرارسید.از طرف ارتش یه تاج گل فرستادن به همراه یک مدال شجاعت واینکه تو یک عملیات مردانه در راه وطنش کشته شده .و ابراز تاسف از اینکه هم قطارهاش نتونستند جسدش رو برگردوند.\r\nیه چیزی تو وجودش شکست ارام بی صدا.سعی کرد تحمل بکنه.اما روزی که وسایلش رو بهش تحویل دادن یه بسته توش پیدا کرد که توش دهها نامه نوشته شده اما پست نشده بود همشون رو خوند صدها بار و عاشقانه گریست و عاشقانه شکست .در پایان تمام نامه ها قول داده بود بر گرده و شجاعت بخرج بده و اونو جلوی همه, عاشقانه صدها بار ببوسه.از این موضوع 60 سال گذشته اما هنوزم هر روز یک پیرزن سالخورده هر روز ساعت ها تو ایستگاه قطار منتظر برگشتن قطاریه که نامزد اونو از جبهه برگردونه جوانک زیبایی که عاشقانه دوستش داشته تا اونو صدها بار جلوی همه ببوسه.\r\n"},{"id":386,"category_id":4,"category_code":"s4","source_id":61,"title":"عشق مادر","content":"یک روز گرم تابستان ، پسر کوچکی با عجله لباسهایش را در آورد و خنده کنان داخل دریاچه شیرجه رفت. \r\nمادرش از پنجره نگاهش می کرد و از شادی کودکش لذت میبرد. مادر ناگهان تمساحی را دید که به سوی پسرش شنا می کرد. \r\nمادر وحشتزده به سمت دریاچه دوید و با فریادش پسرش را صدا زد . پسرش سرش را برگرداند ولی دیگر دیر شده بود. \r\nتمساح با یک چرخش پاهای کودک را گرفت تا زیر آب بکشد، مادر از راه رسید و از روی اسکله بازوی پسرش را گرفت. تمساح پسر را با قدرت می کشید ولی عشق مادر...\r\nآنقدر زیاد بود که نمی گذاشت پسر در کام تمساح رها شود.کشاورزی که در حال عبور از آن حوالی بود ، صدای فریاد مادر را شنید، به طرف آنها دوید و با چنگک محکم بر سر تمساح زد و او را فراری داد. \r\nپسر را سریع به بیمارستان رساندند. دو ماه گذشت تا پسر بهبودی پیدا کند. پاهایش با آرواره های تمساح سوراخ سوراخ شده بود و روی بازوهایش جای زخم ناخنهای مادرش مانده بود. \r\nخبرنگاری که با کودک مصاحبه می کرد از او خواست تا جای زخمهایش را به او نشان دهد. پسر شلوارش را کنار زد و با ناراحتی زخمها را نشان داد ،سپس با غرور بازوهایش را نشان داد و گفت ،  \r\nاین زخمها را دوست دارم ، اینها خراشهای عشق مادرم هستند\r\n"},{"id":387,"category_id":4,"category_code":"s4","source_id":62,"title":"تشویق ","content":"دختری در چین زندگی می كرد که با جدیت درس نمی خواند . وی اصلا نمی دانست که آینده اش چیست و به دنبال چه هدفی می باشد . روزی از روزها ، قبل از امتحانات مدرسه ، دوست این دختر به وی خبر داد كه به سوالات امتحانی دست یافته است . در حقیقت ، دختر می توانست برای شركت در امتحان از همین ورقه استفاده كند . دختر کلیه پاسخ های ورقه را كه در دست داشت حفظ كرد . با توجه به ضعف درسی وی گمان بر این بود كه او در این امتحانات از نمره 100 فقط 30 نمره خواهد گرفت . اما او موفق شد در آزمون مدرسه نمره 98 بگیرد. این مساله باعث شد كه دانش آموزان دچار تردید شوند كه مبادا دختر در امتحان تقلب كرده است . با وجود این اتفاق معلم دختر را ستایش و تشویق و ابراز اطمینان کرد که وی از آن به بعد موفقیت های بیشتری به دست خواهد آورد . دختر نیز كه هیجان زده شده بود ، شروع به گریه كرد .\r\n او از سخنان معلم بی نهایت خوشحال شده بود و دریافته بود كه اگر خوب درس بخواند ، افتخارات بیشتری كسب خواهد کرد . از آن به بعد ، دختر برای آنکه ثابت کند تلقب نکرده است و برای اینكه معلمش را نا امید نکند ، با جدیت درس می خواند و از لذت درس خواندن را احساس می كرد .\r\n چند سال بعد ، او در یكی از دانشگاه های معروف پکن پذیرفته شد . در واقع بدون آن ورقه امتحان سرنوشت دختر این گونه تغییر نمی كرد و آینده خوبی در انتظار وی نبود . اما همان اتفاق فرصتی برای دختر فراهم آورد و مسیر زندگی وی را متحول كرد . بعد از سالها ، دختر به مدرسه باز گشت و برای معلم خود حقیقت را فاش كرد .\r\n معلم که دیگر سالمند شده بود ، گفت : عزیزم ، آن زمان می دانستم که تو تلقب کرده ای  زیرا توانایی های تو را می شناختم و می دانستم كه تو نمی توانی نمره 98 بگیری . اما فکر کردم که امکان دارد تو با استفاده از این فرصت بیشتر کوشش کنی . بدین سبب ، تو را تشویق کردم و نسبت به تو اطمینان داشتم .\r\n دختر با شنیدن این سخنان به گریه افتاد . وی می دانست که در لحظه کلیدی حیات وی ، معلم او را تشویق کرده و همین مساله راه زندگی وی را تغییر داده است. بله دوستان ، در واقع ، در حیات ما اتفاقات و فرصت های زیادی رخ داده و بوجود می آید . لذا نباید به این آسانی این فرصت ها را از دست داد.\r\n"},{"id":388,"category_id":4,"category_code":"s4","source_id":63,"title":"خونه ی خدا ","content":"\r\nالو … الو … سلام\r\nکسی اونجا نیست ؟؟؟\r\nمگه اونجا خونه ی خدا نیست ؟\r\nپس چرا کسی جواب نمیده ؟\r\nیهو یه صدای مهربون بگوش کودک نواخته شد ! مثل صدای یه فرشته...\r\n- بله با کی کار داری کوچولو ؟\r\n- خدا هست ؟ باهاش قرار داشتم ، قول داده امشب جوابمو بده\r\n- بگو من میشنوم\r\nکودک متعجب پرسید : مگه تو خدایی ؟ من با خود خدا کار دارم... \r\n- هر چی میخوای به من بگو قول میدم به خدا بگم\r\nصدای بغض آلودش آهسته گفت یعنی خدام منو دوست نداره ؟؟؟\r\n- فرشته ساکت بود . بعد از مکثی نه چندان طولانی گفت نه خدا خیلی دوستت داره . مگه کسی میتونه تو رو دوست نداشته باشه ؟\r\nبلور اشکی که در چشمانش حلقه زده بود با فشار بغض شکست و بر روی گونه اش غلطید و با همان بغض گفت : اصلا اگه نگی خدا باهام حرف بزنه گریه میکنما... \r\nبعد از چند لحظه هیاهوی سکوت شکسته شد: \r\nندایی صدایش در گوش و جان کودک طنین انداز شد : بگو زیبا بگو . هر آنچه را که بر دل کوچکت سنگینی می کند بگو... \r\nدیگر بغض امانش را بریده بود بلند بلند گریه کرد و گفت : خدا جون خدای مهربون ، خدای قشنگم می خواستم بهت بگم تو رو خدا نذار بزرگ شم تو رو خدا... \r\n- چرا ؟ ولی این مخالف با تقدیره . چرا دوست نداری بزرگ بشی ؟\r\nآخه خدا من خیلی تو رو دوست دارم قد مامانم ، ده تا دوستت دارم . اگه بزرگ شم نکنه مثل بقیه فراموشت کنم ؟ نکنه یادم بره که یه روزی بهت زنگ زدم ؟ نکنه یادم بره هر شب باهات قرار داشتم ؟ مثل بقیه که بزرگ شدن و حرف منو نمی فهمن .\r\n مثل بقیه که بزرگن و فکر میکنن من الکی میگم با تو دوستم . مگه ما با هم دوست نیستیم ؟ پس چرا کسی حرفمو باور نمیکنه ؟ خدا چرا بزرگا حرفاشون سخت سخته ؟ مگه اینطوری نمی شه باهات حرف زد ؟\r\nخدا پس از تمام شدن گریه های کودک : آدم ، محبوب ترین مخلوق من ، چه زود خاطراتش رو به ازای بزرگ شدن فراموش میکنه ، کاش همه مثل تو به جای خواسته های عجیب من رو از خودم طلب میکردند تا تمام دنیا در دستشان جا میگرفت . کاش همه مثل تو مرا برای خودم و نه برای خودخواهی شان میخواستند . دنیا خیلی برای تو کوچک است … بیا تا برای همیشه کوچک بمانی و هرگز بزرگ نشوی... \r\nو کودک کنار گوشی تلفن ، درحالی که لبخندی شیرین بر لب داشت در آغوش خدا به خوابی عمیق و شگفت انگیز فرو رفته بود..\r\n"},{"id":389,"category_id":4,"category_code":"s4","source_id":64,"title":"هدیه  ","content":"\r\nسلام . دلم برات خيلي تنگ شده بود.\r\nپسرک از شادي تو پوست خود نمي گنجيد... راست ميگفت ...خيلي وقت بود که نديده بودش..دلش واسش يه ذره شده بود..تو چشاي سياهش زل زد همون چشمايي که وقتي چند سال بيشتر نداشت باعث شد تا پسرک عاشق شود و با تهديد و داد و هوارو عربده بالاخره کاري کرد که باهم دوست شدن...  \r\nدخترک نگاهي به ساعتش کرد و ميون حرفاي پسرک پريد و گفت: من ديرم شده زودي بايد برم خونه...\r\nهميشه همين جور بوده هر وقت دخترک پسرک را ميديد زود بايد بر ميگشت.\r\nپسرک معطل نکرد و کادويي که براي دخترک خريده بود رو با کلي اشتياق به دخترک داد.\r\nدخترک بي تفاوت بسته را گرفت و تشکري خشک و خالي کرد...حتي کنجکاويي نکرد داخل بسته رو ببنيد...\r\nپسرک خواست سر سخن روباز کند که دخترک گفت : واي ديرم شد..من ديگه برم خداحافظ\r\nخداحافظي کردند و پسرک در سوک لحظه جدايي ماتم گرفت و رفتن معشوق را نظاره کرد \r\nدخترک هراسان و دل نگران بود...در راه نيم نگاهي به بسته انداخت ...يه خرس عروسکي خوشگل بود.. هوا ديگه داشت کمکم سرد ميشد وسرعت ماشين هاي که رد ميشدند ترس دخترک رو از دير رسيدن بيشتر ميکرد.\r\nپسره مثل هميشه5 دقيقه تاخير داشت اما بازم مثل هميشه ريلکس بود...دخترک سلام کرد و پسر پاسخ گفت.\r\nدخترک بي درنگ بسته را به پسر داد و نگاه پر شوقش را به نگاه پسر دوخت.پسر نيم نگاهي به بسته انداخت و گفت: مرسي...بسته را باز کرد و ناگاه چشمش به نامه اي افتاد که عاشق خوش خيال دخترک براي او نوشته بود... لبخندي زد و به روي خود نياورد...چند دقيقه اي را با هم سپري کردن و باز مثل هميشه خداحافظي و نگاه ملتمس عاشقي که از لحظه ي وداع بيزار است..اين بار دخترک عاشق بود و پسره معشوق او..معشوقي که شايد جسم اون سر قرار با 5 دقيقه تاخير حاضر شده بود ، اما دلش از لحظه اول جاي ديگه اي بود... \r\nکمي آن طرف تر صداي جيغ لاستيکي دخترک و پسر را متوجه نقطه اي در آن طرف کرد..پسرکي در زير چرخ هاي ماشين جان مي داد و آخرين نگاهش دوخته شده به معشوقه اي بود که به او خيانت کرده بود..\r\n"},{"id":390,"category_id":4,"category_code":"s4","source_id":65,"title":"زیبایی پایدار ","content":"در یک روز آرام ، روشن ، شیرین و آفتابی یک فرشته مخفیانه از بهشت پایین آمد و به این دنیای قدیمی پا گذاشت. در دشت ، جنگل ، شهر و دهکده گشتی زد. هنگامی که خورشید در حال پایین آمدن بود او بالهایش را باز کرد و گفت:\r\nحالا که دیدار من از زمین پایان یافته ، باید به دنیای روشنایی برگردم. اما قبل از رفتن باید چند یادگاری از اینجا ببرم. \r\nفرشته به باغ زیبایی از گلها نگاه کرد و گفت:\r\nچه گلهای دوست داشتنی و خوشبویی روی زمین وجود دارد!\r\nبی نظیرترین گلهای رز را چید و یک دسته گل درست کرد و با خود گفت:\r\nمن چیزی زیباتر و خوشبوتر از این گلها در زمین ندیدم، این گلها را همراه خود به بهشت خواهم برد.\r\nاما اندکی که بیشتر نگاه کرد کودکی را با چشم های روشن و گونه های گلگون در حال خندیدن به چهره مادرش دید. فرشته با خود گفت:\r\nآه! خنده این کودک زیباتر از این دسته گل هست من آن را هم با خود خواهم برد.\r\nسپس فرشته آن طرف گهواره کودک را نگاه کرد و آنجا محبت مادری وجود داشت که مانند یک رودخانه در حال فوران به سوی گهواره و به سوی کودک سراریز می شد. فرشته با خود گفت:\r\nآه! محبت مادر زیباترین چیزی است که من تا به حال بر روی زمین دیده ام من آن را هم با خود به بهشت خواهم برد.\r\nبه همراه سه چیز ارزشمند و گرانبها؛ فرشته بالی زد و به سمت دروازهای مروارید مانند بهشت پرواز کرد. خارج از بهشت رو به روی دروازه ها فرود آمد و با خود گفت:\r\nقبل از اینکه وارد بهشت شوم یادگاری ها را ببینم.\r\nبه گلها نگاه کرد. آنها پلاسیده شده بودند! به لبخند کودک نگاه کرد ، آن هم محو شده بود! فقط یکی مانده بود ... به محبت مادر نگاه کرد. محبت مادر هنوز آنجا بود با همه زیبایی همیشگی اش. فرشته گلها و لبخند محو شده کودک را به گوشه ای انداخت و به سمت دروازه های بهشت پرواز کرد. تمام بهشتیان را جمع کرد و و گفت:\r\nمن چیزی در زمین یافتم که زیبایی بی نظیرش را در تمام راه ، تا رسیدن به بهشت حفظ کرد و آن محبت یک مادر است\r\n"},{"id":391,"category_id":4,"category_code":"s4","source_id":66,"title":"مسافر بهشت ","content":"تا کريسمس چند روز بيشتر نمانده بود و جنب و جوش مردم براي خريد هديه کريسمس روز به روز بيشتر ميشد. من هم به فروشگاه رفته بودم و براي پرداخت پول هدايايي که خريده بودم، در صف صندوق ايستاده بودم. جلوي من دو بچه، پسري 5 ساله و دختري کوچکتر ايستاده بودند. پسرک لباس مندرسي بر تن داشت، کفشهايش پاره شده بود و چند اسکناس را در دستهايش مي‏فشرد. لباسهاي دخترک هم دست کمي از مال برادرش نداشت ولي يک جفت کفش نو در دست داشت. وقتي به صندوق رسيديم، دخترک آهسته کفشها را روي پيشخوان گذاشت، چنان رفتار مي‏کرد که انگار گنجينه‏اي پر ارزش را در دست دارد.\r\n. صندوقدار قيمت کفشها را گفت: 6 دلار. پسرک پولهايش را روي پيشخوان ريخت و آنها را شمرد: 3 دلار و 15 سنت. بعد رو کرد به خواهرش و گفت: فکر مي‏کنم بايد کفشها رو بگذاري سرجايش... \r\nدخترک با شنيدن اين حرف به شدت بغض کرد و با گريه گفت: نه! نه! پس مامان تو بهشت با چي راه بره؟ پسرک جواب داد: گريه نکن، شايد فردا بتوانيم پول کفشها را در بياوريم. من که شاهد ماجرا بودم، به سرعت 3 دلار از کيفم بيرون آوردم و به صندوقدار دادم. دخترک دو بازوي کوچکش را دور من حلقه کرد و با شادي گفت: متشکرم خانم … متشکرم خانم.\r\nبه طرفش خم شدم و پرسيدم: منظورت چي بود که گفتي: پس مامان تو بهشت با چي راه بره؟  پسرک جواب داد: مامان خيلي مريض است و بابا گفته که ممکنه قبل از عيد کريسمس به بهشت بره! دخترک ادامه داد: معلم ديني ما گفته که رنگ خيابانهاي بهشت طلائي است، به نظر شما اگر مامان با اين کفش هاي طلائي تو خيابانهاي بهشت قدم بزنه، خوشگل نميشه؟  چشمانم پر از اشک شد و در حالي که به چشمان دخترک نگاه ميکردم، گفتم: چرا عزيزم، حق با تو است مطمئنم که مامان شما با اين کفشها تو بهشت خيلي قشنگ مي‏شه\r\n"},{"id":392,"category_id":4,"category_code":"s4","source_id":67,"title":"مسافر","content":"عاشق می خواست به سفر برود. روزها و ماه ها و سال ها بود که چمدان می بست\r\nهی هفته ها را تا می کرد و توی چمدان می گذاشت. هی ماه ها را مرتب می کرد و روی هم می چید و هی سال ها را جمع می کرد و به چمدانش اضافه میکرد.  \r\n او هر روز توی جیب های چمدانش شنبه و یکشنبه می ریخت و چه قرن هایی را که ته ته چمدانش جا داده بود. و سال ها بود که خدا تماشایش می کرد و لبخند می زد و چیزی نمی گفت. اما سرانجام روزی خدا به او گفت: عزیز عاشق، فکر نمی کنی سفرت دارد دیر می شود؟\r\nو سال ها بود که خدا تماشایش می کرد و لبخند می زد و چیزی نمی گفت. اما سرانجام روزی خدا به او گفت: عزیز عاشق، فکر نمی کنی سفرت دارد دیر می شود؟ چمدانت زیادی سنگین است. با این همه سال و قرن و این همه ماه و هفته چه می خواهی بکنی؟\r\n عاشق گفت : خدایا! عشق، سفری دور و دراز است. من به همه این ماه ها و هفته ها احتیاج دارم. به همه این سال ها و قرن ها، زیرا هر قدر که عاشقی کنم، باز هم کم است.\r\n خدا گفت : اما عاشقی، سبکی است. عاشقی، سفر ثانیه است. نه درنگ قرن ها و سال ها. بلند شو و برو و هیچ چیز با خودت نبر، جز همین ثانیه که من به تو می دهم.\r\nعاشق گفت : چیزی با خود نمی برم، باشد. نه قرنی و نه سالی و نه ماه و هفته ای را. اما خدایا ! هر عاشقی به کسی محتاج است. به کسی که همراهی اش کند. به کسی که پا به پایش بیاید. به کسی که اسمش معشوق است.\r\n خدا گفت : نه ؛ نه کسی و نه چیزی. \"هیچ چیز\" توشه توست و \"هیچ کس\" معشوق تو، در سفری که نامش عشق است.\r\n و آنگاه خدا چمدان سنگین عاشق را از او گرفت و راهی اش کرد  عاشق راه افتاد و سبک بود و هیچ چیز نداشت. جز چند ثانیه که خدا به او داده بود.\r\n عاشق راه افتاد و تنها بود و هیچ کس را نداشت. جز خدا که همیشه با او بود\r\n"},{"id":393,"category_id":4,"category_code":"s4","source_id":68,"title":"بیماری لیزا ","content":"سال ها پیش زمانی که به عنوان داوطلب در بیمارستان استانفورد مشغول کار بودم با دختری به نام لیزا آشنا شدم که از بیماری جدی و نادری رنج میبرد. \r\nظاهرا تنها شانس بهبودی او گرفتن خون از برادر پنج ساله خود بود که او نیز قبلا مبتلا به این بیماری بود و به طرز معجزه آسایی نجات یافته بود و هنوز نیاز به مراقبت پزشکی داشت.پزشک معالج وضعیت بیماری خواهرش را توضیح داد و پرسید آیا برای بهبودی خواهرت مایل به اهدای خون هستی؟؟\r\nبرادر خردسال اندکی تردید کرد و...\r\nسپس نفس عمیقی کشید و گفت:بله من اینکار را برای نجات لیزا انجام خواهم داد.\r\nدر طول انتقال خون کنار تخت لیزا روی تختی دراز کشیده بود و مثل تمامی انسان ها که با مشاهده اینکه رنگ به چهره خواهرش باز میگشت خوشحال بود و لبخند میزد.سپس رنگ چهره اش پریده بیحال شده و لبخند بر لبانش خشکید.\r\nنگاهی به دکتر انداخته و با صدای لرزانی گفت:آیا میتوانم زودتر بمیرم؟؟؟\r\nپسر خردسال به خاطر سن کمش توضیحات دکتر معالج را عوضی فهمیده بود و تصور میکرد باید تمام خونش را به لیزا بدهدو با شجاعت خود را آماده مرگ کرده بود\r\n"},{"id":394,"category_id":4,"category_code":"s4","source_id":69,"title":"شرط عشق ","content":"\r\nدختر جوانی چند روز قبل از عروسی آبله سختی گرفت و بستری شد\r\nنامزد وی به عیادتش رفت و در میان صحبتهایش از درد چشم خود نالید.\r\nبیماری زن شدت گرفت و آبله تمام صورتش را پوشاند.\r\nمرد جوان عصا زنان به عیادت نامزدش می رفت و از درد چشم می نالید.\r\nموعد عروسی فرا رسید.\r\nزن نگران صورت خود که آبله آنرا از شکل انداخته بود و شوهرهم که کور شده بود.\r\nهمه مردم می گفتند چه خوب! عروس نازیبا همان بهتر که شوهرش نابینا باشد.\r\n۲۰سال بعد از ازدواج زن از دنیا رفت،\r\nمرد عصایش را کنار گذاشت و چشمانش را گشود.همه تعجب کردند.\r\nمرد گفت: من کاری جز شرط عشق را به جا نیاوردم\r\n"},{"id":395,"category_id":4,"category_code":"s4","source_id":70,"title":"کاسه ی چوبی ","content":"پیرمردی ضعیف و رنجور تصمیم گرفت با پسر و عروس و نوه ی چهارساله اش زندگی کند. دستان پیرمرد می لرزید چشمانش تار شده بود و گام هایش مردد و لرزان بود.\r\nاعضای خانواده هر شب برای خوردن شام دور هم جمع می شدند اما دستان لرزان پدربزرگ و ضعف چشمانش خوردن غذا را برایش مشکل می ساخت. نخود فرنگی ها از توی قاشقش قل می خوردند و روی زمین می ریختند. یا وقتی لیوان را می گرفت شیر از داخل آن به روی میز می ریخت. پسر و عروسش از آن همه ریخت و پاش کلافه شدند.\r\nپسر گفت باید فکری برای پدربزرگ کرد. به قدر کافی ریختن شیر و غذا خوردن پر سر و صدا و ریختن غذا بر روی زمین را تحمل کرده ام. پس زن و شوهر برای پیر مرد در گوشه ای از اتاق میز کوچکی قرار دادند. در آنجا پیر مرد به تنهایی غذایش را می خورد. در حالی که سایر اعضای خانواده سر میز از غذایشان لذت می بردند و از آنجا که پیرمرد یکی دو ظرف را شکسته بود حالا در کاسه ای چوبی به او غذا می دادند.\r\nگهگاه آنها که چشمشان به پیرمرد می افتاد و متوجه می شدند همچنان که در تنهایی غذا می خورد چشمانش پر از اشک است.\r\nاما تنها چیزی که این پسر و عروس به زبان می آوردند تذکرهای تند و گزنده بود که موقع افتادن چنگال یا ریختن غذا به او می دادند.\r\nاما کودک 4 ساله شان در سکوت شاهد تمام آن رفتارها بود. یک شب قبل از شام مرد جوان پسرش را سرگرم بازی با تکه های چوبی دید که روی زمین ریخته بود.پس با مهربانی از اوپرسید:\r\nپسرم داری چی می سازی؟\r\nپسرک هم با ملایمت جواب داد:یک کاسه ی چوبی کوچک. تا وقتی بزرگ شدم با اون به تو و مامان غذا بدم! و بعد لبخندی زد و به کارش ادامه داد.\r\n"},{"id":396,"category_id":4,"category_code":"s4","source_id":71,"title":"بچگیها ","content":"وقتی بزرگ می شوی دیگر خجالت می کشی به گربه ها سلام کنی و برای پرنده هایی که آوازهای نقره ای می خوانند دست تکان دهی\r\nخجالت می کشی دلت شور بزند برای جوجه قمری هایی که مادرشان بر نگشته، فکر می کنی آبرویت می رود.\r\nاگر یک روز مردم ـ همان هایی که خیلی بزرگ شده اند ـ دل شوره های قلبت را ببینند و به تو بخندند وقتی بزرگ می شوی دیگر نمی ترسی که نکند فردا صبح خورشید نیاید،حتی دلت نمی خواهد پشت کوه ها سرک بکشی و خانه خورشید را از نزدیک ببینی\r\nدیگر دعا نمی کنی برای آسمان که دلش گرفته،حتی آرزو نمی کنی کاش قدت می رسید و اشکهای آسمان را پاک می کردی!\r\nوقتی بزرگ می شوی قدت کوتاه می شود\r\nآسمان بالا می رود و تو دیگر دستت به ابرها نمی رسد و برایت مهم نیست که توی کوچه پس کوچه های پشت ابرها ستاره ها چگونه بازی می کنند\r\nآنها آنقدر دورند که تو حتی لبخندشان را هم نمی بینی و ماه ، همبازی قدیم تو آنقدر کمرنگ می شود که اگر تمام شب را هم دنبالش بگردی پیدایش نمی کنی\r\nوقتی بزرگ می شوی دور قلبت سیم خاردار می کشی و درمراسم تدفین درخت ها شرکت می کنی و فاتحه تمام آوازها و پرنده ها را می خوانی\r\nو یک روز یادت می افتد که تو سال هاست چشمانت را گم کرده ای و دستانت را در کوچه های کودکی جا گذاشته ای ،\r\nفردای آنروز تو را به خاک می دهند ومی گویند:\r\nخیلی بزرگ شده!\r\nآنروز دیگر خیلی دیر شده است...\r\n"},{"id":397,"category_id":4,"category_code":"s4","source_id":72,"title":"نهایت عشق ","content":"\r\nیک روز آموزگار از دانش آموزانی که در کلاس بودند پرسید آیا می توانید راهی غیر تکراری برای ابراز عشق ، بیان کنید؟\r\nبرخی از دانش آموزان گفتند با بخشیدن عشقشان را معنا می کنند. برخی «دادن گل و هدیه» و «حرف های دلنشین» را راه بیان عشق عنوان کردند. شماری دیگر هم گفتند «با هم بودن در تحمل رنجها و لذت بردن از خوشبختی» را راه بیان عشق می دانند.\r\nدر آن بین ، پسری برخاست و پیش از این که شیوه دلخواه خود را برای ابراز عشق بیان کند،\r\nداستان کوتاهی تعریف کرد:\r\nیک روز زن و شوهر جوانی که هر دو زیست شناس بودند طبق معمول برای تحقیق به جنگل رفتند. آنان وقتی به بالای تپّه رسیدند درجا میخکوب شدند. یک قلاده ببر بزرگ، جلوی زن و شوهر ایستاده و به آنان خیره شده بود. شوهر، تفنگ شکاری به همراه نداشت و دیگر راهی برای فرار نبود. رنگ صورت زن و شوهر پریده بود و در مقابل ببر، جرات کوچک ترین حرکتی نداشتند. ببر، آرام به طرف آنان حرکت کرد. همان لحظه، مرد زیست شناس فریاد زنان فرار کرد و همسرش را تنها گذاشت. بلافاصله ببر به سمت شوهر دوید و چند دقیقه بعد ضجه های مرد جوان به گوش زن رسید. ببر رفت و زن زنده ماند. \r\nداستان به اینجا که رسید دانش آموزان شروع کردند به محکوم کردن آن مرد. راوی اما پرسید : آیا می انید آن مرد در لحظه های آخر زندگی اش چه فریاد می زد؟\r\nبچه ها حدس زدند حتما از همسرش معذرت خواسته که او را تنها گذاشته است! راوی جواب داد: نه، آخرین حرف مرد این بود که \"عزیزم ، تو بهترین مونسم بودی.از پسرمان خوب مواظبت کن و به او بگو پدرت همیشه عاشقت بود.\"\r\nقطره های بلورین اشک، صورت راوی را خیس کرده بود که ادامه داد: همه زیست شناسان می دانند ببر فقط به کسی حمله می کند که حرکتی انجام می دهد و یا فرار می کند. پدر من در آن لحظه وحشتناک ، با فدا کردن جانش پیش مرگ مادرم شد و او را نجات داد. این صادقانه ترین و بی ریاترین ترین راه پدرم برای بیان عشق خود به مادرم و من بود\r\n"},{"id":398,"category_id":4,"category_code":"s4","source_id":73,"title":"دیوار چوبی ","content":"این داستانی که در زیر نقل می شود یک داستان کاملا واقعیست که در ژاپن اتفاق افتاده است: \r\nشخصی مشغول تخریب دیوار قدیمی خانه اش بود تا آنرا نوسازی کند . توضیح اینکه منازل ژاپنی بنابر شرایط محیطی دارای فضایی خالی بین دیوار های چوبی هستند. \r\nاین شخص در حین خراب کردن دیوار در بین آن مارمولکی را دید که میخی از بیرون به پشتش فرو رفته بود. \r\nدلش سوخت و یک لحظه کنجکاو شد . وقتی میخ را بررسی کرد خیلی تعجب کرد ! این میخ چهار سال پیش ، هنگام ساختن خانه کوبیده شده بود! \r\nاما براستی چه اتفاقی افتاده بود ؟ که در یک قسمت تاریک آنهم بدون کوچکترین حرکت ، یک مارمولک توانسته بمدت چهار سال در چنین موقعیتی زنده مانده! \r\nچنین چیزی امکان ندارد و غیر قابل تصور است . متحیر از این مساله کارش را تعطیل و مارمولک را مشاهده کرد. \r\nدر این مدت چکار می کرده ؟ چگونه و چی می خورده ؟\r\nهمانطور که به مارمولک نگاه می کرد یکدفعه مارمولکی دیگر ، با غذایی در دهانش ظاهر شد! \r\nمرد شدیدا منقلب شد ! چهار سال مراقبت . واقعا که چه عشق قشنگی ! یک موجود کوچک با عشقی بزرگ ! عشقی که برای زیستن و ادامه ی حیات ، حتی در مقابله با مرگ همنوعش او را دچار هیچگونه کوتاهی نکرده بود! \r\nاگه موجودی به این کوچکی بتونه عشقی به این بزرگی داشته باشه پس تصور کنید ما تا چه حد می توانیم عاشق همدیگه باشیم و شاید هم باید پایبندی رو از این موجود درس بگیریم ، البته اگر سعی کنیم خیلی بهتر از اینها می توانیم چرا که باید به خود اییم و بخواهیم و بدانیم ، ‏که انسان باشیم..\r\n"},{"id":399,"category_id":4,"category_code":"s4","source_id":74,"title":" و خدا نزدیک است... ","content":"ظهر یک روز سرد زمستانی وقتی امیلی به خانه برگشت پشت در ، پاکت نامه ای را دید که نه تمبری داشت و نه مُهر اداره پست روی آن بود؛ فقط نام و آدرس خودش روی پاکت نوشته شده بود. او با تعجب پاکت را باز کرد و نامه داخل آن را خواند:\r\nامیلی عزیز!\r\nعصر امروز به دیدن تو می آیم، تا تو را ملاقات کنم.\r\nبا عشق خدا \r\nامیلی همان طور که بادست های لرزان نامه را روی میز می گذاشت با خود فکر کرد که چرا خدا می خواهد او را ملاقات کند؟ او که آدم مهمی نبود. در همین فکرها بود که کابینت خالی آشپزخانه را به یاد آورد و با خود گفت: من که چیزی برای پذیرایی ندارم. پس نگاهی به کیف پولش انداخت او فقط 5 دلار و 40 سنت داشت. با این حال به سمت فروشگاه بیرون آمد برف به شدت در حال بارش بود و او عجله داشت تا زودتر به خانه برگردد و عصرانه را برای خداوند حاضر کند! \r\nدر راه برگشت زن و مرد فقیری به امیلی گفتتند: \"خانم! ما خانه و پولی نداریم بسیار سردمان است و گرسنه هستیم، آیا امکان دارد به ما کمکی بکنید؟\"\r\nامیلی جواب داد: \"متاسفم، من دیگر پولی ندارم و این نان ها و غذا را هم برای مهمانم خریده ام.\"\r\nمرد گفت: \"بسیار خوب خانم، متشکرم\" و بعد دستش را روی شانه ی همسرش گذاشت و به حرکت ادامه دادند.\r\nهمان طور که مرد و زن فقیر در حال دور شدن بودند امیلی ناراحتی شدیدی را در درونش احساس کرد به سرعت دنبال آنها دوید.\r\n\"آقا! ، خانم! خواهش می کنم صبر کنید\"\r\nوقتی امیلی به زن و مرد فقیر رسید، سبد غذا را به آنها داد و بعد کتش را هم در آورد و روی شانه های زن انداخت. مرد از او تشکر کرد و برایش دعا کرد.. \r\nوقتی امیلی به خانه رسید، ناراحت بود. چون خدا می خواست به ملاقاتش بیاید و او دیگر چیزی برای پذیرایی از خدا نداشت. همان طور که در را باز می کرد پاکت نامه دیگری را روی زمین دید. نامه را برداشت و باز کرد: \r\nامیلی عزیز!\r\nاز پذیرایی خوب و کت زیبایت متشکرم \r\nبا عشق خدا\r\n"},{"id":400,"category_id":4,"category_code":"s4","source_id":75,"title":"آلزایمر ","content":"پیرمردی صبح زود از خانه‌اش خارج شد. در راه با یک ماشین تصادف کرد و آسیب دید. عابرانی که رد می‌شدند به سرعت او را به اولین درمانگاه رساندند.\r\nپرستاران ابتدا زخمهای پیرمرد را پانسمان کردند سپس به او گفتند: باید ازتو عکسبرداری شود تا جایی از بدنت آسیب ندیده باشد. پیرمرد غمگین شد و گفت عجله دارد و نیازی به عکسبرداری نیست.\r\nپرستاران از او دلیلش را پرسیدند. پیرمرد گفت زنم در خانه سالمندان است. هر صبح آنجا می‌روم و صبحانه را با او می‌خورم. نمی‌خواهم دیر شود!\r\nپرستاری به او گفت: خودمان به او خبر می‌دهیم. پیرمرد با اندوه گفت: خیلی متأسفم. او آلزایمر دارد. چیزی را متوجه نخواهد شد! حتی مرا هم نمی‌شناسد!\r\nپرستار با حیرت گفت: وقتی که نمی داند شما چه کسی هستید، چرا هر روز صبح برای صرف صبحانه پیش او می‌روید؟\r\nپیرمرد با صدایی گرفته، به آرامی گفت:\r\nاما من که می‌دانم او چه کسی است...!\r\n"},{"id":401,"category_id":4,"category_code":"s4","source_id":76,"title":"کلوچه ها ","content":"زن جوانی بسته‌ای کلوچه و کتابی خرید و روی نیمکتی در قسمت ویژه فرودگاه نشست که استراحت و مطالعه کند تا نوبت پروازش برسد.\r\nدر کنار او مردی نیز نشسته بود که مشغول خواندن مجله بود,\r\nوقتی او اولین کلوچه‌اش را برداشت، مرد نیز یک کلوچه برداشت.\r\nدر این هنگام احساس خشمی به زن دست داد، اما هیچ نگفت فقط با خود فکر کرد: عجب رویی داره! \r\nهر بار که او کلوچه‌ای برداشت مرد نیز کلوچه ای برمیداشت. این عمل او را عصبانی تر می کرد، اما از خود واکنشی نشان نداد.\r\nوقتی که فقط یک کلوچه باقی مانده بود، با خود فکر کرد: “حالا این مردک چه خواهد کرد؟\"\r\nمرد آخرین کلوچه را نصف کرد و نصف آن را برای او گذاشت...!\r\nزن دیگر نتوانست تحمل کند، کیف و کتابش را برداشت و با عصبانیت به سمت سالن رفت.\r\nوقتی که در صندلی هواپیما قرار گرفت، در کیفش را باز کرد تا عینکش را بردارد، که در نهایت تعجب دید بسته کلوچه‌اش، دست نخورده مانده. \r\nتازه یادش آمد که اصلا بسته کلوچه‌اش را از کیفش درنیاورده بود.\r\nمرد بدون اینکه خشمگین یا عصبانی شود بسته کلوچه‌اش را با او تقسیم کرده بود\r\n"},{"id":402,"category_id":4,"category_code":"s4","source_id":77,"title":"گریه ","content":"یك پسر كوچك از مادرش پرسید : چرا گریه می كنی؟\r\nمادرش به او گفت: زیرا من یك زن هستم\r\nپسر بچه گفت: من نمی فهمم!\r\nمادرش او را در آغوش گرفت و گفت: تو هیچگاه نخواهی فهمید!\r\nبعدها پسر كوچك از پدرش پرسید: چرا مادر بی دلیل گریه می كند؟\r\nپدرش تنها توانست به او بگوید : تمام زنها برای هیچ و پوچ گریه می كنند!\r\nپسر كوچك بزرگ شد و به یك مرد تبدیل گشت ولی هنوز نمی دانست چرا زن ها بی دلیل گریه می كنند؟\r\nبالاخره سوالش را برای یك فرشته مطرح كرد و مطمئن بود كه فرشته جواب را می داند \r\n او از فرشته پرسید: چرا زن ها به آسانی گریه می كنند؟\r\nفرشته گفت خدا زمانی كه زن را خلق كرد می خواست كه او موجود به خصوصی باشد بنابراین شانه های او را آن قدر قوی آفرید تا بار همه دنیا را به دوش بكشد و همچنین شانه هایش آن قدر نرم باشد كه به بقیه آرامش بدهد... \r\nبه او یك نیروی درونی قوی داد تا توانایی تحمل زایمان بچه هایش را داشته باشد وقتی آن ها بزرگ شدند توانایی تحمل بی اعتنایی آن ها را نیز داشته باشد!\r\nبه او توانایی داد كه در جایی كه همه از جلو رفتند نا امید شده اند او تسلیم نشود و همچنان پیش برود به او توانایی نگهداری از خانواده اش را داد حتی زمانی كه مریض یا پیر شده است بدون این كه شكایتی بكند... \r\n به او عشقی داده كه در هر شرایطی بچه هایش را عاشقانه دوست داشته باشد حتی اگر آنها به او آسیبی برسانند . به او توانایی داد كه شوهرش را دوست داشته باشد و از تقصیرات او بگذرد و همیشه تلاش كند تا جایی در قلب شوهرش داشته باشد به او این شعور را داد كه درك كند. یك شوهر خوب هرگز به همسرش آسیب نمی رساند اما گاهی اوقات توانایی همسرش را آزمایش می كند و به او این توانایی را داد كه تمامی این مشكلات را حل كرده و با وفاداری كامل در كنار شوهرش باقی بماند و در آخر به او اشك هایی دادم كه بریزد این اشك ها فقط مال اوست و تنها برای استفاده اوست در هر زمانی كه به آنها نیاز داشته باشد او به هیچ دلیلی نیاز ندارد تا توضیح دهد چرا اشك می ریزد \r\nفرشته گفت: زیبایی یك زن در چشمانش نهفته است زیرا چشم های او دریچه روح اوست و در قلب او جایی كه عشق او به دیگران در آن قرار دارد... \r\n"},{"id":403,"category_id":4,"category_code":"s4","source_id":78,"title":"کاغذ کادو ","content":"روزی مردی به خونه اومد و دید که دختر سه ساله اش قشنگترین و گرونترین کاغذ کادوی موجود در کمد اون رو تیکه تیکه کرده و با اون یه جعبه کفش قدیمی رو تزیین کرده! مرد دخترک رو به خاطر این کار تنبیه کرد و دختر کوچولو اون شب با گریه به رختخواب رفت و خوابید.\r\nفردا صبح وقتی مرد از خواب بیدار شد و چشاش رو باز کرد، دید که دخترک بالای سرش نشسته و جعبه تزیین شده رو به طرف اون دراز کرده! مرد تازه یادش اومد که امروز، روز تولدشه و دختر کوچولوش اون کاغذ رو برای تزیین کادوی تولد اون استفاده کرده. با شرمندگی دخترش رو بوسید و جعبه رو از اون گرفت و درش رو باز کرد. اما در کمال تعجب دید که جعبه خالیه! مرد دوباره به دخترش پرخاش کرد که: جعبه خالی که هدیه نمیشه!! باید توش یه چیزی میذاشتی!\r\nدخترک با تعجب به صورت پدرش خیره شد و گفت: «اما این جعبه خالی نیست. من دیشب هزار تا بوس توش گذاشتم تا هروقت دلت برام تنگ شد یکی از اونا رو برداری و استفاده کنی.\r\nاز اون روز به بعد، پدر همیشه اون جعبه رو همراه خودش داشت و هر وقت دلتنگ دخترش می شد در اون رو باز می کرد و با برداشتن یه بوسه آروم می گرفت. هدیه کار خودش رو کرده بود\r\n"},{"id":404,"category_id":4,"category_code":"s4","source_id":79,"title":"شب برفی ","content":"\r\nدکتر اس. وایر میچل متخصص برجسته ی اعصاب در فیلادلفیا، در یک غروب زمستانی بعد از کار روزانه بر روی صندلی به خواب رفته بود، که با صدای زنگ در بیدار شد و دید که دختر لا غری که از سرما می لرزد تقاضا دارد که مادرش را معاینه و معالجه کند. او توضیح داد که حال مادرش وخیم است. دختر کفشهای فرسوده به پا و شال نخ نمایی به دور گردنش پیچیده بود.\r\nدکتر به دنبال او در خیابان های پوشیده از برف محلات قدیمی روانه شد. از پله های عمارتی قدیمی بالا رفتند. در طبقه‌ی بالا دکتر زنی مریض را دید که سابقا پیشخدمت خانه ی او بود. او بیماری زن را سینه پهلو تشخیص داد و داروهای لازم را تجویز کرد و دارویی نیز به او خوراند که حال زن را بهتر کرد سپس به او برای داشتن چنان دختر وظیفه شناسی تبریک گفت.\r\nزن پیر با کمال تعجب گفت که دخترش ماهها قبل مرده و کفشها و شال او در گنجه است. دکتر نگاه کرد و همان شال و کفشها را دید که بر تن دختری بود که او را به اینجا آورده بود. اما هر دوی آن ها خشک بود و نمی توانست در آن شب برفی مورد استفاده قرار گرفته باشد.\r\nتحقیقات نشان داد که آن دختر به راستی سال ها قبل مرده و دکتر وایر میچل شاهد واقعه ای ماوراء الطبیعه بوده است!\r\nهر چند که خیلی ها معتقدند این فقط میتواند حاصل عشق حقیقی دختر به مادرش باشد\r\n"},{"id":405,"category_id":4,"category_code":"s4","source_id":80,"title":"هدیه ی پدر","content":"مرد جوانی ، از دانشکده فارغ التحصیل شد . ماهها بود که ماشین اسپرت زیبایی ، پشت شیشه های یک نمایشگاه به سختی توجهش را جلب کرده بود و از ته دل آرزو می کرد که روزی صاحب آن ماشین شود . مرد جوان ، از پدرش خواسته بود که برای هدیه فارغ التحصیلی ، آن ماشین را برایش بخرد . او می دانست که پدر توانایی خرید آن را دارد. \r\nبالاخره روز فارغ التحصیلی فرا رسید و پدرش او را به اتاق مطالعه خصوصی اش فرا خواند و به او گفت : من از داشتن پسر خوبی مثل تو بی نهایت مغرور و شاد هستم و تو را بیش از هر کس دیگری در دنیا دوست دارم .\r\n سپس یک جعبه به دست او داد . پسر ، کنجکاو ولی ناامید ، جعبه را گشود و در آن یک انجیل زیبا ، که روی آن نام او طلا کوب شده بود ، یافت . با عصبانیت فریادی بر سر پدر کشید و گفت : با تمام مال و دارایی که داری ، یک انجیل به من می دهی ؟ کتاب مقدس را روی میز گذاشت و پدر را ترک کرد. \r\nسالها گذشت و مرد جوان در کار و تجارت موفق شد . خانه زیبایی داشت و خانواده ای فوق العاده، اما مدتی در این فکر بود که حتما پدرش خیلی پیر شده و باید سری به او بزند . از روز فارغ التحصیلی دیگر او را ندیده بود .\r\n اما قبل از اینکه اقدامی بکند ، تلگرامی به دستش رسید که خبر فوت پدر در آن بود و حاکی از این بود که پدر ، تمام اموال خود را به او بخشیده است . بنابراین لازم بود فوراً خود را به خانه برساند و به امور رسیدگی نماید. \r\nهنگامی که به خانه پدر رسید ، در قلبش احساس غم و پشیمانی کرد . اوراق و کاغذ های مهم پدر را گشت و آنها را بررسی نمود و در آنجا ، همان انجیل قدیمی را باز یافت . در حالیکه اشک می ریخت انجیل را باز کرد و صفحات آن را ورق زد و ناگهان کلید یک ماشین را پشت جلد آن پیدا کرد . در کنار آن ، یک برچسب با نام همان نمایشگاه که ماشین مورد نظر او را داشت ، وجود داشت . روی برچسب تاریخ روز فارغ التحصیلی اش بود و روی آن نوشته شده بود : تمام مبلغ پرداخت شده است\r\n"},{"id":406,"category_id":4,"category_code":"s4","source_id":81,"title":"شیرین ترین دارو ","content":"این داستان در باره یک دختر که معلم روستا بود و یک پسر باغبان است . بزرگترین آرزوی پسر این بود که هر روز در کنار پنجره صدای زیبای دختر را بشنود . او فکر می کرد که هیچ کسی همانند این دختر صدای نرم و دلنشین ندارد .\r\n اما روزی از روزها ، پسر متوجه شد که صدای دختر گرفته است . او در گوشه ای از حیاط مدرسه مخفیانه به داخل کلاس نگاه می کرد و متوجه شد دختر از نهایت درد گلو چهره اش تغییر کرده است .\r\n پس از پایان کلاس ، پسر به سراغ دختر رفت و متوجه که دختر اهل جنوب است و تحمل آب و هوای خشک شمالی را ندارد و به همین دلیل صدایش نیز تغییر کرده است . روز بعد ، دختر متوجه فنجان آبی شد که روی میزش گذاشته شده بود . آب را نوشید . سپس ابرو در هم کشید و گفت : چقدر تلخ است . اما پسر متوجه شد که صدای دختر پس از نوشیدن آب بهتر شده است .\r\n زیرا او این آب را از جوانه نیلوفر تهیه کرده بود که با خوردن آن درد انسان کاهش می یابد . پسر هر روز به این کار ادامه می داد و پس از چیدن جوانه ها ، دوایی آماده کرده و قبل از کلاس مخفیانه روی میز دختر می گذاشت . روزی از روزها ، دختر زودتر از پسر به کلاس آمد و در پشت در,پنهانی به تماشای حرکات پسر پرداخت و به ماجرا پی برد . در همین جا از پسر پرسید : پس تو هر روز جوانه نیلوفر را برای من تهیه می کنی ؟ پسر سری تکان داد و با لکنت زبان جواب داد : بله ، بله ، متوجه شدم صدای شما تغییر کرده است و این دوا برای کاهش درد شما مناست است .\r\n از آن به بعد ، پسر هر روز تخم نیلوفر را می چید و دوای دختر را آماده می کرد . روزی از روزها ، پسر از معلم روستایی پرسید : تو دیگر از تلخی این دوا نمی ترسی ؟ دختر لبخندی زد و گفت : این شیرین ترین دارو جهان است.\r\n"},{"id":407,"category_id":4,"category_code":"s4","source_id":82,"title":"دختر نابینا ","content":"\r\nدختري بود نابينا\r\nکه از خودش تنفر داشت\r\nکه از تمام دنيا تنفر داشت\r\nو فقط يکنفر را دوست داشت\r\nدلداده اش را\r\nو با او چنين گفته بود\r\nاگر روزي قادر به ديدن باشم\r\nحتي اگر فقط براي يک لحظه بتوانم دنيا را ببينم\r\nعروس حجله گاه تو خواهم شد \r\n***\r\nو چنين شد که آمد آن روزي\r\nکه يک نفر پيدا شد\r\nکه حاضر شود چشمهاي خودش را به دختر نابينا بدهد\r\nو دختر آسمان را ديد و زمين را\r\nرودخانه ها و درختها را\r\nآدميان و پرنده ها را\r\nو نفرت از روانش رخت بر بست\r\n***\r\nدلداده به ديدنش آمد\r\nو ياد آورد وعده ديرينش شد: \r\nبيا و با من عروسي کن\r\nببين که سالهاي سال منتظرت مانده ام \r\n***\r\nدختر برخود بلرزيد\r\nو به زمزمه با خود گفت: \r\n« اين چه بخت شومي است که مرا رها نمي کند ؟ »\r\nدلداده اش هم نابينا بود\r\nو دختر قاطعانه جواب داد:\r\nقادر به همسري با او نيست\r\n***\r\nدلداده رو به ديگر سو کرد\r\nکه دختر اشکهايش را نبيند\r\nو در حالي که از او دور مي شد گفت\r\n« پس به من قول بده که مواظب چشمانم باشي\r\n"},{"id":408,"category_id":4,"category_code":"s4","source_id":83,"title":"گوژپشت","content":"موسی مندلسون، پدر بزرگ آهنگساز شهیر آلمانی، انسانی زشت و عجیب الخلقه بود. قدّی بسیار كوتاه و قوزی بد شكل بر پشت داشت. \r\nموسی روزی در هامبورگ با تاجری آشنا شد كه دختری بسیار زیبا و دوست داشتنی به نام فرمتژه داشت. موسی در كمال ناامیدی، عاشق آن دختر شد، ولی فرمتژه از ظاهر و هیكل از شكل افتاده او منزجر بود.\r\nزمانی كه قرار شد موسی به شهر خود بازگردد، آخرین شجاعتش را به كار گرفت تا به اتاق دختر برود و از آخرین فرصت برای گفتگو با او استفاده كند. دختر حقیقتاً از زیبایی به فرشته ها شباهت داشت، ولی ابداً به او نگاه نكرد و قلب موسی از اندوه به درد آمد. موسی پس از آن كه تلاش فراوان كرد تا صحبت كند، با شرمساری پرسید:  \r\n- آیا می دانید كه عقد ازدواج انسانها در آسمان بسته می شود؟\r\nدختر در حالی كه هنوز به كف اتاق نگاه می كرد گفت:  \r\n- بله، شما چه عقیده ای دارید؟  \r\n- من معتقدم كه خداوند در لحظه تولد هر پسری مقرر می كند كه او با كدام دختر ازدواج كند. هنگامی كه من به دنیا آمدم، عروس آینده ام را به من نشان دادند و خداوند به من گفت:\r\n«همسر تو گوژپشت خواهد بود» \r\nدرست همان جا و همان موقع من از ته دل فریاد برآوردم و گفتم:  \r\nاوه خداوندا! گوژپشت بودن برای یك زن فاجعه است. لطفاً آن قوز را به من بده و هر چی زیبایی است به او عطا كن. \r\nفرمتژه سرش را بلند كرد و خیره به او نگریست و از تصور چنین واقعه ای بر خود لرزید.\r\nاو سال های سال همسر فداكار موسی مندلسون بود.\r\n"},{"id":409,"category_id":4,"category_code":"s4","source_id":84,"title":"چشمها را باید شست","content":"وقتی که نشستم تا مطالعه کنم، نیمکت پارک خالی بود. در زیر شاخه‌های طویل و پیچیده‌ی درخت بید کهنسال، دلسردی از زندگی دلیل خوبی برای اخم کردنم شده بود، چون دنیا می‌خواست مرا درهم بکوبد.\r\nپسر کوچکی با نفس بریده به من نزدیک شد. درست مقابلم ایستاد و با هیجان بسیار گفت:‌“نگاه کن چه پیدا کرده‌ام\"\r\nدر دستش یک شاخه گل بود و چه منظره‌ی رقت‌انگیزی! گلی با گلبرگ های پژمرده. از او خواستم گل پژمرده‌اش را بردارد و برود بازی کند. تبسمی کردم، سپس سرم را برگرداندم. اما او به جای آن که دور شود، کنارم نشست و گل را جلوی بینی اش گرفت و با شگفتی فراوان گفت: مطمئنا بوی خوبی می دهد و زیبا نیز هست! به همین دلیل آن را چیدم. بفرمایید! این مال شماست.\r\n\"آن علف هرز پژمرده شده بود، و رنگی نداشت، اما می‌دانستم که باید آن را بگیرم و گرنه امکان داشت او هرگز نرود. از این‌رو دستم را به سوی گل دراز کردم و پاسخ دادم: “ممنونم، درست همان چیزی است که لازم داشتم.\r\nولی او به جای اینکه گل را در دستم بگذارد، آن را در وسط هوا نگه داشته بود, دلیل یا نقشه‌ای داشت.\r\nآن وقت بود که برای نخستین بار مشاهده کردم پسری که علف هرز را در دست داشت، نمی‌توانست ببیند، او نابینا بود! ناگهان صدایم لرزید، چشمانم از اشک پر شد. او تبسمی کرد و گفت: “قابلی ندارد.\" سپس دوید و رفت تا بازی کند.\r\nتوسط چشمان بچه‌ای نابینا، سرانجام توانستم ببینم، مشکل از دنیا نبود، مشکل از خودم بود و به جبران تمام آن زمانی که خودم نابینا بودم، با خود عهد کردم زیبایی زندگی را ببینم و قدر هر ثانیه‌ای که مال من است را بدانم و آن وقت آن گل پژمرده را جلوی بینی‌ ام گرفتم و رایحه‌ی گل سرخی زیبا را احساس کردم.\r\nمدتی بعد دیدم آن پسرک، علف هرز دیگری در دست دارد، تبسمی کردم: “او در حال تغییر دادن زندگی مرد سالخورده‌ دیگری بود.\"\r\n"},{"id":410,"category_id":4,"category_code":"s4","source_id":85,"title":"عذاب وجدان","content":"\r\nیه پسر و دختر کوچولو داشتن با هم بازی میکردن. پسر کوچولو یه\r\nسری تیله داشت و دختر کوچولو چندتایی شیرینی با خودش داشت.\r\nپسر کوچولو به دختر کوچولو گفت من همه تیله هامو بهت میدم؛ تو\r\nهمه شیرینیاتو به من بده. دختر کوچولو قبول کرد.\r\nپسر کوچولو بزرگترین و قشنگترین تیله رو یواشکی واسه خودش\r\nگذاشت کنار و بقیه رو به دختر کوچولو داد. اما دختر کوچولو همون\r\nجوری که قول داده بود تمام شیرینیاشو به پسرک داد.\r\nهمون شب دختر کوچولو با ارامش تمام خوابیدو خوابش برد. ولی پسر\r\nکوچولو نمی تونست بخوابه چون به این فکر می کرد که همونطوری\r\nخودش بهترین تیله اشو یواشکی پنهان کرده شاید دختر کوچولو هم\r\nمثل اون یه خورده از شیرینیهاشو قایم کرده و همه شیرینی ها رو بهش\r\nنداده .\r\nنتیجه اخلاقی داستان\r\nعذاب وجدان همیشه مال کسی است که صادق نیست\r\nآرامش مال کسی است که صادق است\r\nلذت دنیا مال کسی نیست که با آدم صادق زندگی می کند\r\nآرامش دنیا مال اون کسی است که با وجدان صادق زندگی میکند\r\n"},{"id":411,"category_id":4,"category_code":"s4","source_id":86,"title":"منطق ","content":"دانشجویی پس از اینکه در درس منطق نمره\r\nنیاورد.\r\n به ‏استادش گفت: قربان، شما واقعا چیزی در\r\nمورد موضوع این درس میدانید؟\r\nاستاد جواب ‏داد: بله حتما. در غیر اینصورت\r\nنمیتوانستم یک استاد باشم\r\n دانشجو ادامه داد: بسیار ‏خوب، من مایلم از\r\nشما یک سوال بپرسم ،\r\nاگر جواب صحیح دادید من نمره ام را قبول میکنم\r\n ‏در غیر اینصورت از شما میخواهم به من نمره\r\nکامل این درس رابدهید.\r\n‏استاد قبول ‏کرد و دانشجو پرسید: آن چیست\r\nکه قانونی است ولی منطقی نیست،\r\n منطقی است ولی قانونی ‏نیست و نه قانونی\r\nاست و نه منطقی؟\r\nاستاد پس از تاملی طولانی نتوانست جواب\r\nبدهد و ‏مجبور شد\r\nنمره کامل درس را به آن دانشجو بدهد\r\n‏بعد از مدتی استاد با بهترین ‏شاگردش تماس\r\nگرفت و همان سوال را پرسید\r\n: و شاگردش بلافاصله جواب داد\r\n‏قربان شما 63 ‏سال دارید و با یک خانم 35\r\nساله ازدواج کردید که البته قانونی است ولی\r\nمنطقی ‏نیست\r\n‏همسر شما یک معشوقه 25 ساله دارد که\r\nمنطقی است ولی قانونی نیست\r\nواین ‏حقیقت که شما به معشوقه همسرتان\r\nنمره کامل دادید در صورتیکه\r\n باید آن درس را رد میشد ‏نه قانونی است و نه\r\nمنطقی\r\n"},{"id":412,"category_id":4,"category_code":"s4","source_id":87,"title":"شمع فرشته","content":"\r\n مردی که همسرش را از دست داده بود دختر سه ساله اش را بسیــار دوست می داشت\r\nدخترک به بیماری سختی مبتلا شد\r\n پدر به هر دری زد تا کودک سلامتی اش را دوباره بدست بیاورد، هرچه پول داشت برای درمان او خرج کرد\r\nولی بیماری جان دخترک را گرفت و او مرد...\r\nپدر در خانه اش را بست و گوشه گیر شد. با هیچکس صحبت نمی کرد\r\nسرکار نمی رفت. دوستان و آشنایانش خیلی سعی کردند تا او را به زندگی عادی برگردانند\r\nولی موفق نشدند. شبی پدر رویای عجیبی دید، دید که در بهشت است\r\nو صف منظمی از فرشتگان کوچک در جاده ای طلایی به سوی کاخی مجلل در حرکت هستند\r\nهمه فرشته های کوچک در حال شادی بودنند. \r\nهر فرشته شمعی در دست داشت و شمع همه فرشتگان به جز یکی روشن بود\r\nمرد جلوتر رفت و دید فرشته ای که شمعش خاموش است، همان دختر خودش است\r\nپدر فرشته غمگینش را در آغوش گرفت و او را نوازش داد\r\n از او پرسید : دلبندم، چرا غمگینی؟ چرا شمع تو خاموش است؟\r\nدخترک به پدرش گفت: باباجان، هر وقت شمع من روشن می شود، اشکهای تو آن را خاموش می کند و\r\n هر وقت تو دلتنگ می شوی، من هم غمگین می شوم هر وقت تو گوشه گیر می شوی من نیز گوشه\r\n. گیر می شوم نمی توانم همانند بقیه شاد باشم \r\nپدر در حالی که اشک در چشمانش حلقه زده بود، از خواب پرید.\r\nاشکهایش را پاک کرد، ناراحتی و غم را رها کرد و به زندگی عادی خود بازگشت.\r\n"},{"id":413,"category_id":4,"category_code":"s4","source_id":88,"title":"کرگدنها هم عاشق می شوند","content":"\r\nکرگردن گفت : نه امکان ندارد ، کرگدن ها نمی توانند با کسی دوست شوند.\r\nدم جنبانک گفت : اما پشت تو می خارد ، لای چینهای پوستت پر از حشره های ریز است یکی باید پشت تو را بخاراند . یکی باید حشره های تو رو بردارد .\r\nکرگدن گفت :اما من نمی توانم با کسی دوست شوم پوست من خیلی کلفت است همه به من می گویند پوست کلفت ...\r\nدم جنبانک گفت : اما دوست عزیز دوست داشتن به قلب مربوط میشود نه ، به پوست.\r\nکرگدن گفت : من که قلب ندارم من فقط پوست دارم .\r\nدم جنبانک گفت : این امکان ندارد همه قلب دارند .\r\nکرگدن گفت : کو ، کجاست ؟ من که قلب خودم را نمی بینم .\r\nدم جنبانک گفت : خوب چون از قلبت استفاده نمی کنی قلبت را نمی بینی ، ولی من مطمئنم که زیر این پوست کلفت یه قلب نازک داری .\r\nکرگدن گفت : نه من قلب نازک ندارم ، من حتما یه قلب کلفت دارم .\r\nدم جنبانک گفت : نه تو حتما یه قلب نازک داری چون بجای اینکه دم جنبانک را بترسانی بجای اینکه لگدش کنی بجای اینکه دهن گشاد و گنده ات را باز کنی و آن را بخوری داری با آن حرف می زنی .\r\nکرگدن گفت : خوب این یعنی چی ؟\r\nدم جنبانک گفت : وقتی یه کرگدن پوست کلفت یک قلب نازک دارد یعنی چی ؟ یعنی اینکه می تواند دوست داشته باشد یعنی می تواند عاشق شود .\r\nکرگدن گفت : اینها که میگی یعنی چی؟\r\nدم جنبانک گفت : یعنی .... بزار روی پوست کلفت و قشنگت بنشینم ..... بگذار...\r\nکرگدن چیزی نگفت یعنی داشت دنبال یه جمله مناسب می گشت . فکر کرد بهتر است همان جمله اولش را بگوید .\r\nاما دم جنبانک پشت کرگدن نشسته بود و داشت پشتت را می خاراند . داشت حشره های ریز لای چین پوستش را بر می داشت .\r\nکرگدن احساس کرد چقدر خوشش می آید ... اما نمی دانست از چی خوشش می آید !\r\n*کرگدن گفت : اسم این دوست داشتن است ؟ اسم اینکه من دلم می خواهد تو روی پشت من بمانی و مزاحم های کوچولوی پشتم را بخوری ؟\r\nدم جنبانک گفت : نه اسم این نیاز است من دارم به تو کمک می کنم و تو از اینکه نیازت بر طرف می شود احساس خوبی داری یعنی احساس رضایت میکنی اما دوست داشتن از این مهمتر است *\r\nکرگدن نفهمید که دم جنبانک چه می گوید .\r\nروزها گذشت روزها ، هفته ها ، و ماه ها و دم جنبانک هر روز می آمد و پشت کرگدن می نشست هر روز پشتش را می خاراند و حشره های کوچک و مزاحم را از لای پوستش کلفتش بر می داشت و کرگدن هر روز احساس خوبی داشت .\r\nیک روز کرگدن به دم جنبانک گفت :به نظر تو این موضوع که کرگدنی از اینکه دم جنبانکی پشتش را می خاراند و حشره های مزاحمش را می خورد احساس خوبی دارد برای یک کرگدن کافی است ؟\r\nدم جنبانک گفت : نه کافی نیست .\r\nکرگدن گفت : درست است کافی نیست . چون من حس میکنم چیزهای دیگری هم دوست دارم راستش من بیشتر دوست دارم تو را تماشا کنم ....\r\nدم جنبانک چرخی زد و پرواز کرد چرخی زد و آواز خواند جلوی چشمهای کرگدن ، کرگدن تماشا کرد و تماشا کرد و تماشا کرد ...... اما سیر نشد .\r\nکرگدن می خواست همین طور تماشا کند . کرگدن با خودش فکر کرد این صحنه قشنگترین صحنه دنیاست و این دم جنبانک قشنگترین دم جنبانک دنیا و او خوشبخترین کرگدن توی دنیا . وقتی که کرگدن به اینجا رسید احساس کرد که یک چیز نازک از چشمش افتاد !\r\nکرگدن ترسید و گفت : دم جنبانک ، دم جنبانک عزیزم من قلبم را دیدم همان قلب نازکم را که می گفتی ! اما قلبم از چشمم افتاد حالا چه کنم ؟\r\nدم جنبانک برگشت و اشک های کرگدن را دید . آمد و روی سر او نشست و گفت : غصه نخور دوست عزیز ، تو یک عالم از این قلبهای نازک داری .\r\nکرگدن گفت : راستی اینکه کرگدن دوست دارد دم جنبانکی را تماشا کند و ، وقتی تماشایش می کند قلبش از چشمش می افتد یعنی چی ؟\r\nدم جنبانک چرخی زد و گفت : یعنی اینکه کرگردن ها هم عاشق می شوند !\r\nکرگدن گفت عاشق یعنی چی ؟\r\nدم جنبانک گفت : یعنی کسی که قلبش از چشمهایش می چکند .\r\nکرگدن باز هم منظور دم جنبانک را نفهمید ، اما دوست داشت دم جنبانک باز حرف بزند ، باز پرواز کند ، و باز او تماشایش کند و باز قلبش از چشمهایش بیفتند .\r\nکرگدن فکر کرد اگر قلبش همین طور از چشمهایش بریزد یک روز حتما قلبش تمام می شود .\r\nآن وقت لبخند زد و با خودش گفت : من که اصلا قلب نداشتم حالا که دم جنبانک به من قلب داد چه عیبی دارد ؟ بگذار تمام قلبم را برای او از چشمهایم بریزم ....\r\n"},{"id":414,"category_id":4,"category_code":"s4","source_id":89,"title":"عاشقانه","content":"\r\nدختره از پسره پرسید من خوشگلم؟گفت نه .گفت دوستم داری؟گفت نوچ؟گفت اگه بمیرم برام گریه میکنی؟ گفت اصلا؟دختره چشماش پر از اشک شد. هیچی نگفت:پسره بغلش کرد گفت:تو خوشگل نیستی زیبا ترین هستی.تورودوست ندارم چون عاشقتم. اگه تو بمیری برات گریه نمیکنم چون من هم میمرم .\r\n"},{"id":415,"category_id":4,"category_code":"s4","source_id":90,"title":"جوانی","content":"گفتم زندگی چند بخش است؟؟ گفت:: دو بخش گفتم کدامند؟؟ گفت : کودکی، پیری گفتم: پس جوانی چه شد؟؟ گفت : با عشق ساخت...... با بی وفایی سوخت."},{"id":416,"category_id":4,"category_code":"s4","source_id":91,"title":"زن گمشده","content":"\r\nمردی هنگام غروب به کلانترى می رود تا گم شدن همسرش را اطلاع بدهد...\r\nمرد : زنم از صبح رفته خرید ولى هنوز برنگشته خونه! \r\nپلیس : قدش چقدره ؟\r\nمرد : تا حالا دقت نکردم \r\nپلیس : لاغره ؟ چاقه ؟\r\nمرد : یک کم شاید لاغر یا چاق !؟\r\nپلیس : رنگ چشمهاش ؟\r\nمرد : دقیقاً نمی دونم !؟\r\nپلیس : رنگ موهاش ؟\r\nمرد : راستش موهاشو هى رنگ می کنه \r\nپلیس : چى پوشیده بود ؟\r\nمرد : پیراهن !؟ … یا مانتو !؟ … نمی دونم \r\nپلیس : با ماشین رفته بود ؟\r\nمرد : بله\r\nپلیس : اسم ، رنگ و شماره ماشین ؟\r\nمرد : یک مگان مشکى 1600 تیپ2 -4سیلندر با115 اسب بخار – حداکثر گشتاور خروجی:151نیوتن متر-5 دنده با سرعت 193 کیلومتر برساعت- مونتاژ داخلی-استاندارد آلایندگی: یورو3\r\n(مرد ناگهان می زند زیر گریه)\r\nپلیس : گریه نکنید آقا! آروم باشید. ما ماشینتون رو براتون پیدا می کنیم!\r\n"},{"id":417,"category_id":4,"category_code":"s4","source_id":92,"title":"خلقت خدا ","content":"\r\nمردی بر همسر خود در آشپزخانه وارد شد و از او پرسید\r\nکدام یک از فرزندان خود را بیش از دیگر فرزندانت دوست داری؟\r\nهمسر او گفت همه آنها را بزرگشان و کوچکشان...\r\nدختر و پسر همه یکسانند و همه را به یک اندازه دوست دارم\r\nشوهر گفت: چگونه دل تو برای آنها همه جا دارد؟\r\nهمسر جواب داد:\r\nاین خلقت خدا است که مادر دلش برای همه فرزندان خود وسعت دارد..\r\nمرد لبخندی زد و گفت:\r\nاکنون شاید بتوانی بفهمی که چگونه دل مرد برای چهار زن همزمان وسعت دارد\r\nخدایش بیامرزد روش والایی در قانع کردن داشت،\r\nلکن موقعیتش در آشپزخانه غلط بود\r\nمراسم آن تازه درگذشته صبح و بعد از ظهر فردا برگزار می شود!!\r\n"},{"id":418,"category_id":4,"category_code":"s4","source_id":93,"title":"معجزه ی عشق","content":"\r\nسالها پیش , در کشور آلمان , زن و شوهری زندگی می کردند.آنها هیچ گاه صاحب فرزندی نمی شدند.یک روز که برای تفریح به اتفاق هم از شهر خارج شده و به جنگل رفته بودند , ببر کوچکی در جنگل , نظر آنها را به خود جلب کرد.مرد معتقد بود : نباید به آن بچه ببر نزدیک شد.به نظر او ببرمادر جایی در همان حوالی فرزندش را زیر نظر داشت.پس اگر احساس خطر می کرد به هر دوی آنها حمله می کرد و صدمه می زد.اما زن انگار هیچ یک از جملات همسرش را نمی شنید , خیلی سریع به سمت ببر رفت و بچه ببر را زیر پالتوی خود به آغوش کشید , دست همسرش را گرفت و گفت :عجله کن!ما باید همین الآن سوار اتوموبیلمان شویم و از اینجا برویم.آنها به آپارتمان خود باز گشتند و به این ترتیب ببر کوچک , عضوی از ا عضای این خانواده ی کوچک شد و آن دو با یک دنیا عشق و علاقه به ببر رسیدگی می کردند. سالها از پی هم گذشت و ببر کوچک در سایه ی مراقبت و محبت های آن زن و شوهر حالا تبدیل به ببر بالغی شده بود که با آن خانواده بسیار مانوس بود.در گذر ایام , مرد درگذشت و...\r\nمدت زمان کوتاهی پس از این اتفاق , دعوتنامه ی کاری برای یک ماموریت شش ماهه در مجارستان به دست آن خانم رسید.زن , با همه دلبستگی بی اندازه ای که به ببری داشت که مانند فرزند خود با او مانوس شده بود , ناچار شده بود شش ماه کشور را ترک کند و از دلبستگی اش دور شود.پس تصمیم گرفت : ببر را برای این مدت به باغ وحش بسپارد.\r\nدر این مورد با مسوولان باغ وحش صحبت کرد و با تقبل کل هزینه های شش ماهه , ببر را با یک دنیا دلتنگی به باغ وحش سپرد و کارتی از مسوولان باغ وحش دریافت کرد تا هر زمان که مایل بود , بدون ممانعت و بدون اخذ بلیت به دیدار ببرش بیاید.دوری از ببر, برایش بسیار دشوار بود.روزهای آخر قبل از مسافرت , مرتب به دیدار ببرش می رفت و ساعت ها کنارش می ماند و از دلتنگی اش با ببر حرف می زد.سر انجام زمان سفر فرا رسید و زن با یک دنیا غم دوری , با ببرش وداع کرد.\r\nبعد از شش ماه که ماموریت به پایان رسید , وقتی زن , بی تاب و بی قرار به سرعت خودش را به باغ وحش رساند , در حالی که از شوق دیدن ببرش فریاد می زد : عزیزم , عشق من , من بر گشتم , این شش ماه دلم برایت یک ذره شده بود , چقدر دوریت سخت بود , اما حالا من برگشتم , و در حین ابراز این جملات مهر آمیز , به سرعت در قفس را گشود  آغوش را باز کرد و ببر را با یک دنیا عشق و محبت و احساس در آغوش کشید.ناگهان , صدای فریادهای نگهبان قفس , فضا را پر کرد:نه , بیا بیرون , بیا بیرون : این ببر تو نیست.ببر تو بعد از اینکه اینجا رو ترک کردی , بعد از شش روز از غصه دق کرد و مرد.این یک ببر وحشی گرسنه است.اما دیگر برای هر تذکری دیر شده بود. ببر وحشی با همه عظمت و خوی درندگی , میان آغوش پر محبت زن , مثل یک بچه گربه , رام و آرام بود.اگرچه , ببر مفهوم کلمات مهر آمیزی را که زن به زبان آلمانی ادا کرده بود , نمی فهمید , اما محبت و عشق چیزی نبود که برای درکش نیاز به دانستن زبان و رسم و رسوم خاصی باشد.\r\n"},{"id":419,"category_id":4,"category_code":"s4","source_id":94,"title":"آرزوی دو همسر 60 ساله","content":"یک زوج انگلیسی در اوایل 60 سالگی، در یک رستوران کوچیک رمانتیک سی و پنجمین سالگرد ازدواجشان را جشن گرفته بودن.\r\nناگهان یک پری کوچولوِ قشنگ سر میزشون ظاهر شد و گفت:چون شما زوجی اینچنین مثال زدنی هستین و درتمام این مدت به هم وفادارموندین ،\r\nهر کدومتون می تونین یک آرزو بکنین.\r\nخانم گفت: اووووووووووووووووه ! من می خوام به همراه همسر عزیزم، دور دنیا سفر کنم.\r\nپری چوب جادووییش رو تکون داد و ...اجی مجی لا ترجی\r\nدو تا بلیط برای خطوط مسافربری جدید و شیک در دستش ظاهر شد.\r\nحالا نوبت آقا بود، چند لحظه با خودش فکر کرد و گفت:\r\nباید یه جوری از شر زن پیرم خلاص بشم باید یه دختر خوشگل گیرم بیاد و بعد با کمال پر رویی گفت : خب، این خیلی رمانتیکه ولی چنین موقعیتی فقط یک بار در زندگی آدم اتفاق می افته ، بنابر این، خیلی متاسفم عزیزم ولی آرزوی من اینه که همسری 30 سال جوانتر از خودم داشته باشم.\r\nخانم و پری واقعا نا امید شده بودن ولی آرزو، آرزوه دیگه\r\nپری چوب جادوییش و چرخوند و... \r\nاجی مجی لا ترجی\r\nو آقا 92 ساله شد!\r\nخانمش تا چشمش به صورت پر از چروک و دستان لرزان همسر پیرش افتاد از جاش بلافاصله بلند شد و گفت تو دیگه همسر من نیستی پیرمرد !!\r\nمرد با چشمانی گریان بدنبال همسرش با پشتی خمیده می دوید و می گفت : من عاشقتم !!! \r\n"},{"id":420,"category_id":4,"category_code":"s4","source_id":95,"title":"معنای عشق واقعی","content":"\r\nاستاد شیوانا با دو نفر از شاگردانش همراه کاروانی به شهری دور می رفتند.\r\nبا توجه به مسافت طولانی راه و دوری مقصد طبیعی بود که بسیاری از مردان کاروان بدون همسرانشان و تنها سفر می کردند.\r\nو وقتی به استراحتگاهی می رسیدند بعضی از مردان پی خوشگذرانی می رفتند.\r\nهمسفران نزدیک شیوانا و شاگردانش دو مرد تاجر بودند که هر دو اهل دهکده شیوانا بودند\r\nیکی از مردان همیشه برای عیش و خوشگذرانی از بقیه جدا می شد.\r\nاما آن دیگری همراه شیوانا و شاگردانش و بسیاری دیگر از کاروانیان از گروه جدا نمی شد\r\nیک روز در حین پیاده روی یکی از شاگردان شیوانا از او سوالی در مورد معنای واقعی عشق پرسید:\r\nهمسفر خوشگذران این سوال را شنید و خود را علاقه مند نشان داد و گفت: \r\nعشق یعنی برخورد من با زندگی تجربه های شیرین زندگی را برخودم حرام نمی کنم\r\nهمسرم که در دهکده از کارهای من خبر ندارد\r\nتازه اگر هم توسط شما یا بقیه خبردار شد با خرید هدیه ای او را راضی به چشم پوشی می کنم.\r\nبه هر صورت وقتی که به دهکده برگردم او چاره ای جز بخشیدن من ندارد\r\nبنابراین من از هیچ تجربه لذت بخشی خودم را محروم نکردم و هم با خرید هدایای فراوان عشق همسرم را حفظ کردم.\r\nاین می شود معنای واقعی عشق\r\nشیوانا رو به شاگرد کرد و گفت این دوست ما از یک لحاظ حق دارد\r\nعشق یعنی انجام کارهایی که محبوب را خوشحال می کند\r\nاما این همه عشق نیست\r\nبلکه چیزی مهم تر از آن هست که این رفیق دوم ما که در طول سفر به همسر خود وفادار است\r\nو حتی در غیبت او خیانت هم نمی کند دارد به آن عمل می کند.\r\nبیائید از او بپرسیم چرا همچون همکارش پی عیاشی و عشرت نمی رود؟\r\nمرد دوم که سربه زیر و پابند اخلاقیات بود تبسمی کرد و گفت: \r\nبه نظر من عشق فقط این نیست که کارهایی که محبوب را خوشایند است انجام دهیم\r\nبلکه معنای آن این است که از کارهایی که موجب ناراحتی و آزردگی خاطر محبوب می شود دوری جوئیم.\r\nمن چون می دانم که انجام حرکتی زشت از سوی من حتی اگر همسرم هم خبردار نشود\r\nمی تواند روزی روزگاری موجب آزردگی خاطر او شود\r\nو چه بسا این روزی روزگار در آن دنیا و پس از مرگ باشد\r\nبازهم دلم نمی آید خاطر او را مکدر سازم.\r\nو به همین خاطر به عنوان نگهبان امانت او به شدت اصول اخلاقی را در مورد خودم اجرا می کنم و نسبت به آن سخت گیر هستم\r\nشیوانا سرش را به علامت تائید تکان داد و گفت: \r\nدقیقا این معنای عشق است.\r\nمهم نیست که برای ربودن دل محبوب چقدر از خودت مایه می گذاری و چقدر زحمت می کشی\r\nو چه کارهای متنوعی را انجام می دهی تا خود را برای او دلپذیر سازی\r\nو سمت نگاهش را به سوی خود بگردانی\r\nبلکه عشق یعنی مواظب رفتار و حرکات خود باشی و عملی مرتکب نشوی که محبوب ناراحت شود.\r\nاین معنای واقعی دوست داشتن است.\r\n"},{"id":421,"category_id":4,"category_code":"s4","source_id":96,"title":"عشق پیر و جوان","content":"\r\nشیوانا با چند تن از شاگردانش همراه کاروانی راه می سپردند\r\nدر این کاروان یک زوج جوان بودند و یک زوج پیر و میانسال\r\nزوج جوان تازه ازدواج کرده بودند و زوج پیر سال ها از ازدواجشان گذشته و گرد سفید پیری بر سر و چهره شان پاشیده شده بود.\r\nدر یکی از استراحتگاه ها زن جوان به همراه بانوی پیر به همراه زنان دیگری از کاروان برای چیدن علف های گیاهی از کاروان فاصله گرفتند.\r\nو شوهران آنها کنار شیوانا و شاگردانش در سایه نشستند و از دور مواظب آنها بودند.\r\nدر این هنگام زن جوان و زن پیر روی زمین نشستند و با ناراحتی به پاهای خود چسبیدند. \r\nیکی از شاگردان شیوانا به آن دو اشاره کرد و گفت: \r\nآنجایی که آنها ایستاده اند پر از خارهای گزنده است و اگر این خارها در پای انسان فرو روند درد زیادی را به همراه دارند\r\nبه گمانم این خارها در پای آنها فرو رفته است\r\nمرد جوان بیخیال با خنده گفت: \r\nبگذار عذاب بکشند تا دیگر هوس علف چینی به سرشان نزند\r\nمرد پیر در حالی که چهره اش بسیار درهم شده بود و انگاری داشت درد می کشید از جا پرید و به سمت همسرش دوید و به کمک او رفت.\r\nمرد جوان هم با خنده دنبال او رفت تا به همسرش کمک کند\r\nشب هنگام موقع استراحت شیوانا با شاگردانش کنار آتش نشسته بودند\r\nو راجع به وقایع روزانه صحبت می کردند\r\nشیوانا در حین صحبت گفت : متوجه شدید مرد پیر چقدر همسرش را از مرد جوان بیشتر دوست دارد؟ دارد؟ حتی بیشتر از \r\nیکی از شاگردان با تعجب گفت : از کجا فهمیدید که عشق مرد پیر بیشتر از جوان بود؟ هر دو برای کمک نزد همسرانشان شتافتند؟\r\nشیوانا تبسمی کرد و گفت: از روی چهره شان\r\nمرد پیر وقتی متوجه شد به پای همسرش خار گزنده فرو رفته همان لحظه درد تمام وجودش را فراگرفت.\r\nو چهره اش در هم رفت و چنان از جا پرید انگار همزمان او هم به پایش خار فرو رفته است و همپای همسرش داشت زجر می کشید.\r\nاما مرد جوان با وجودی که زن جوانش داشت عذاب می کشید با او هم احساس نبود و درد او را درک نمی کرد و می خندید.\r\nو جملاتی می گفت تا خودش را توجیه کند و همسرش را سزاوار ناراحتی بداند\r\nعشق واقعی یعنی ناراحت شدن از درد محبوب و شاد شدن از شادی او\r\n"},{"id":422,"category_id":4,"category_code":"s4","source_id":97,"title":"اشک","content":"\r\nزن جوانی همراه همسرش کنار دیوار ایستاده بود و به شدت اشک می ریخت\r\nشیوانا از مقابل آنها عبور کرد.\r\nوقتی گریه زن را دید ایستاد و علت را از او پرسید.\r\nزن گفت : همسرم جوان است و گاه گاه با کلامی زشت مرا می رنجاند\r\nاو مرد لایق و خوبی است.\r\nو تنها عیب که دارد بد دهنی و زشت کلامی اوست که گاهی مرا به گریه وا می دارد\r\nشیوانا با تاسف سری تکان داد و خطاب به مرد گفت :\r\nهیچ انسانی لیاقت اشک های انسان دیگر را ندارد.\r\nو اگر انسان لایقی در دنیا پیدا شد او هرگز دلش نمی آید\r\nکه دل دیگری را به درد و اشک او را در آورد.\r\n"},{"id":423,"category_id":4,"category_code":"s4","source_id":98,"title":"عشق بی وفا","content":"روزی شیوانا پیر معرفت یکی از شاگردانش را دید که زانوی غم بغل گرفته و گوشه ای غمگین نشسته است.\r\nشیوانا نزد او رفت و جویای حالش شد\r\nشاگرد لب به سخن گشود و از بی وفائی یار صحبت کرد و اینکه دختر مورد علاقه اش به او جواب منفی داده و پیشنهاد ازدواج با دیگری را پذیرفته است.\r\nشاگرد گفت که سال های متمادی عشق دختر را در قلب خود حفظ کرده بود و با رفتن دختر به خانه مرد دیگر او احساس می کند باید برای همیشه با عشقش خداحافظی کند\r\nشیوانا با تبسم گفت :  اما عشق تو به دخترک چه ربطی به دخترک دارد؟\r\nشاگرد با حیرت گفت : ولی اگر او نبود این عشق و شور و هیجان هم در وجود من نبود\r\nشیوانا با لبخند گفت : چه کسی چنین گفته است.\r\nتو اهل دل و عشق ورزیدن هستی و به همین دلیل آتش عشق و شوریدگی دل تو را هدف قرار داده است.\r\nاین ربطی به دخترک ندارد.\r\nهر کس دیگری هم جای دختر بود ، تو این آتش عشق را به سمت او می فرستادی\r\nبگذار دختر برود ! این عشق را به سوی دختر دیگری بفرست\r\nمهم این است که شعله این عشق را در دلت خاموش نکنی\r\nمعشوق فرقی نمی کند چه کسی باشد \r\nدختر اگر رفت با رفتنش پیغام دادکه لیاقت این آتش ارزشمند را ندارد\r\nچه بهتر ! بگذار او برود تا صاحب واقعی این شور و هیجان فرصت جلوه گری و ظهور پیدا کند! \r\nبه همین سادگی!\r\n"},{"id":424,"category_id":4,"category_code":"s4","source_id":99,"title":"معنای خوشبختی","content":"\r\nدخترک شانزده ساله بود که برای اولین بار عاشق پسر شد.. پسر قدبلند بود، صدای بمی داشت و همیشه شاگرد اول کلاس بود. دختر خجالتی نبود اما نمی خواست احساسات خود را به پسر ابراز کند، از اینکه راز این عشق را در قلبش نگه می داشت و دورادور او را می دید احساس خوشبختی می کرد.\r\nدر آن روزها، حتی یک سلام به یکدیگر، دل دختر را گرم می کرد. او که ساختن ستاره های کاغذی را یاد گرفته بود هر روز روی کاغذ کوچکی یک جمله برای پسر می نوشت و کاغذ را به شکل ستاره ای زیبا تا می کرد و داخل یک بطری بزرگ می انداخت. دختر با دیدن پیکر برازنده پسر با خود می گفت پسری مثل او دختری با موهای بلند و چشمان درشت را دوست خواهد داشت.\r\nدختر موهایی بسیار سیاه ولی کوتاه داشت و وقتی لبخند می زد، چشمانش به باریکی یک خط می شد.\r\nدر 19 سالگی دختر وارد یک دانشگاه متوسط شد و پسر با نمره ممتاز به دانشگاهی بزرگ در پایتخت راه یافت. یک شب، هنگامی که همه دختران خوابگاه برای دوست پسرهای خود نامه می نوشتند یا تلفنی با آنها حرف می زدند، دختر در سکوت به شماره ای که از مدت ها پیش حفظ کرده بود نگاه می کرد. آن شب برای نخستین بار دلتنگی را به معنای واقعی حس کرد.\r\nروزها می گذشت و او زندگی رنگارنگ دانشگاهی را بدون توجه پشت سر می گذاشت. به یاد نداشت چند بار دست های دوستی را که به سویش دراز می شد، رد کرده بود. در این چهار سال تنها در پی آن بود که برای فوق لیسانس در دانشگاهی که پسر درس می خواند، پذیرفته شود. در تمام این مدت دختر یک بار هم موهایش را کوتاه نکرد.\r\nدختر بیست و دو ساله بود که به عنوان شاگرد اول وارد دانشگاه پسر شد. اما پسر در همان سال فارغ التحصیل شد و کاری در مدرسه دولتی پیدا کرد. زندگی دختر مثل گذشته ادامه داشت و بطری های روی قفسه اش به شش تا رسیده بود.\r\nدختر در بیست و پنج سالگی از دانشگاه فارغ التحصیل شد و در شهر پسر کاری پیدا کرد. در تماس با دوستان دیگرش شنید که پسر شرکتی باز کرده و تجارت موفقی را آغاز کرده است. چند ماه بعد، دختر کارت دعوت مراسم ازدواج پسر را دریافت کرد. در مراسم عروسی، دختر به چهره شاد و خوشبخت عروس و داماد چشم دوخته بود و بدون آنکه شرابی بنوشد، مست شد.\r\nزندگی ادامه داشت. دختر دیگر جوان نبود، در بیست و هفت سالگی با یکی از همکارانش ازدواج کرد. شب قبل از مراسم ازدواجش، مثل گذشته روی یک کاغذ کوچک نوشت: فردا ازدواج می کنم اما قلبم از آن توست… و کاغذ را به شکل ستاره ای زیبا تا کرد.\r\n\r\nده سال بعد، روزی دختر به طور اتفاقی شنید که شرکت پسر با مشکلات بزرگی مواجه شده و در حال ورشکستگی است. همسرش از او جدا شده و طلبکارانش هر روز او را آزار می دهند. دختر بسیار نگران شد و به جستجویش رفت.. شبی در باشگاهی، پسر را مست پیدا کرد. دختر حرف زیادی نزد، تنها کارت بانکی خود را که تمام پس اندازش در آن بود در دست پسر گذاشت. پسر دست دختر را محکم گرفت، اما دختر با لبخند دستش را رد کرد و گفت: مست هستید، مواظب خودتان باشید.\r\nزن پنجاه و پنج ساله شد، از همسرش جدا شده بود و تنها زندگی می کرد. در این سالها پسر با پول های دختر تجارت خود را نجات داد. روزی دختر را پیدا کرد و خواست دو برابر آن پول و 20 درصد سهام شرکت خود را به او بدهد اما دختر همه را رد کرد و پیش از آنکه پسر حرفی بزند گفت: دوست هستیم، مگر نه؟\r\nپسر برای مدت طولانی به او نگاه کرد و در آخر لبخند زد.\r\nچند ماه بعد، پسر دوباره ازدواج کرد، دختر نامه تبریک زیبایی برایش نوشت ولی به مراسم عروسی اش نرفت.\r\nمدتی بعد دختر به شدت مریض شد، در آخرین روزهای زندگیش، هر روز در بیمارستان یک ستاره زیبا می ساخت. در آخرین لحظه، در میان دوستان و اعضای خانواده اش، پسر را بازشناخت و گفت: در قفسه خانه ام سی و شش بطری دارم، می توانید آن را برای من نگهدارید؟\r\nپسر پذیرفت و دختر با لبخند آرامش جان سپرد.\r\nمرد هفتاد و هفت ساله در حیاط خانه اش در حال استراحت بود که ناگهان نوه اش یک ستاره زیبا را در دستش گذاشت و پرسید: پدر بزرگ، نوشته های روی این ستاره چیست؟\r\nمرد با دیدن ستاره باز شده و خواندن جمله رویش، مبهوت پرسید: این را از کجا پیدا کردی؟ کودک جواب داد: از بطری روی کتاب خانه پیدایش کردم.\r\nپدربزرگ، رویش چه نوشته شده است؟\r\nپدربزرگ، چرا گریه می کنید؟\r\nکاغذ به زمین افتاد. رویش نوشته شده بود:\r\nمعنای خوشبختی این است که در دنیا کسی هست که بی اعتنا به نتیجه، دوستت دارد.\r\n"},{"id":425,"category_id":4,"category_code":"s4","source_id":100,"title":"سرزنش","content":"\r\nپس از 11 سال زوجی صاحب فرزند پسری شدند. آن دو عاشق هم بودند و پسرشان را بسیار دوست داشتند. فرزندشان حدوداً دو ساله بود که روزی مرد بطری باز یک دارو را در وسط آشپزخانه مشاهده کرد و چون برای رسیدن به محل کار دیرش شده بود به همسرش گفت که درب بطری را ببندد و آنرا در قفسه قرار دهد. مادر پر مشغله موضوع را به کل فراموش کرد.\r\nپسر بچه کوچک بطری را دید و رنگ آن توجهش را جلب کرد به سمتش رفت و همه آنرا خورد. او دچار مسمومیت شدید شد و به زمین افتاد. مادرش سریع او را به بیمارستان رساند ولی شدت مسمومیت به حدی بود که آن کودک جان سپرد. مادر بهت زده شد و بسیار از اینکه با شوهرش مواجه شود وحشت داشت.\r\nوقتی شوهر پریشان حال به بیمارستان آمد و دید که فرزندش از دنیا رفته رو به همسرش کرد و فقط سه کلمه بزبان آورد.\r\nفکر میکنید آن سه کلمه چه بودند؟\r\nشوهر فقط گفت: “عزیزم دوستت دارم!\"\r\nعکس العمل کاملاً غیر منتظره شوهر یک رفتار فراکُنشی بود. کودک مرده بود و برگشتنش به زندگی محال. هیچ نکته ای برای خطا کار دانستن مادر وجود نداشت. بعلاوه اگر او وقت میگذاشت و خودش بطری را سرجایش قرار می داد، آن اتفاق نمی افتاد. هیچ دلیلی برای مقصر دانستن وجود ندارد. مادر نیز تنها فرزندش را از دست داده و تنها چیزی که در آن لحظه نیاز داشت دلداری و همدردی از طرف شوهرش بود. آن همان چیزی بود که شوهرش به وی داد.\r\nگاهی اوقات ما وقتمان را برای یافتن مقصر و مسئول یک روخداد صرف می کنیم، چه در روابط، چه محل کار یا افرادی که می شناسیم و فراموش می کنیم کمی ملایمت و تعادل برای حمایت از روابط انسانی باید داشته باشیم. در نهایت، آیا نباید بخشیدن کسی که دوستش داریم آسان ترین کار ممکن در دنیا باشد؟ داشته هایتان را گرامی بدارید. غم ها، دردها و رنجهایتان را با نبخشیدن دوچندان نکنید.\r\n"},{"id":426,"category_id":4,"category_code":"s4","source_id":101,"title":"آخرین پیام","content":"\r\nدختر، از دوستت دارم گفتنهاي هر شب پسره خسته شده بود ...\r\nيک شب وقتي اس ام اس آمد بدون آن که آنرا بازکند موبايل را گذاشت زير بالشش و خوابيد !\r\nصبح مادرِ پسره به دختره زنگ زد گفت : پــــســــــرم مـــــــــرده ...\r\nدختره شوکه شد و چشم پر از اشک بلافاصله سراغ اس ام اس شب گذشته رفت \r\nپـــســــــره نــوشــتـــه بـــــــود:\r\nتصادف کردم با مشکل خودم را رساندم دم درخانه تان لطفا بياپائين ميخوام براي آخرين بار ببينمت ...\r\n"},{"id":427,"category_id":4,"category_code":"s4","source_id":102,"title":"رموز و آداب عشق","content":"\r\nدیروز بر دروازه ی معبد ایستادم و از رهگذران درباره ی رموز و آداب عشق پرسیدم\r\nمردی میانسال می گذشت. جسمی بی رمق و چهره ای غمگین داشت آهی کشید و گفت عشق میراثی است از اولین انسان که استحکام و توانایی را ضعیف ساخته است \r\nجوانی تنومند و ورزیده می گذشت. با صدایی آهنگین، پاسخ داد عشق، ثباتی است که به بودن افزوده گردیده تا اکنونم را به نسلهای گذشته و آینده پیوند دهد\r\nزنی با نگاهی دلتنگ می گذشت. آهی کشید و گفت عشق زهری مرگ آور است که دم جمع زنندگان عبوس است که در جهنم به خود می پیچند و از آسمان، توام با چرخش، چون ژاله جاری است. فقط به این خاطر که روح های تشنه را در آغوش بگیرد و سپس آنان لحظه ای می نوشند، یک سال هوشیارند، و تا ابد می میرند\r\nدخترکی که گونه ای چون گل سرخ داشت، می گذشت، لبخندی زد و گفت عشق چشمه ای است که روح عروسان را چنان آبیاری می کند تا به روحی عظیم بدل شوند و آنان را با نیایش تا سرحد ستارگان شب بالا می برد تا قبل از طلوع خورشید ترانه ای از ستایش و پرستش سر دهند\r\nمردی می گذشت ، لباسی تیره رنگ به تن داشت با محاسنی بلند ابرو در هم کشید و گفت عشق جهانی است که مانع از دید است در عنفوان جوانی آغاز می شود و با پایانش پایان می یابد مردی خوش منظر با چهره ای گشاده عبور می کرد با خوشحالی گفت عشق دانش علوی است که چشمانمان را باز می کند تا چیزها را همانطور که خداوند می بیند ببینیم\r\nمرد نابینایی می گذشت که با عصایش به زمین ضربه می زد گریه سر داد و گفت عشق مِهی غلیظ است که روح را از هر جهت احاطه کرده است و حدود وجود را مستور نموده است و فقط اجازه دارد شبح تمایلاتش را که در صخره هاسرگردان است ببیند و نسبت به صدای پژواک فریادش در دره ها ناشنوا است\r\nجوانی با گیتار می گذشت و می خواند عشق اشعه ای جادویی از نوری است که از روی انسانهای حساس می درخشد و اطرافشان را آذین می بندد تو جهان را چون کاروانی می بینی که از میان علفزار سبز گذر می کند عشق رؤیایی دوست داشتنی است که بین بیداری و بیداری برپا است\r\nپیرمردی می گذشت پشتش خم شده بود و پاهایش را همانند تکه ای پارچه به دنبال می کشید، با صدایی لرزان گفت عشق آرامش جسم است در خاموش گور و آسایش روح است در عمق ابدیت\r\nکودکی پنج ساله می گذشت لبخندم را پاسخ داد و گفت عشق یعنی پدرم یعنی مادرم فقط پدر و مادرم هستند که عشق را می شناسند روز به پایان رسید کسانی که از معبد عبور می کردند هر یک به زبان خویش تعبیری از عشق داشتند که آمالشان را آشکار می ساخت و بیانگر یکی از رموز زندگی بود\r\nعصر هنگام که عبور رهگذران خاموش شد صدایی از درون معبد به گوشم رسید \r\nعشق دو تصنیف دارد: نیمی صبر و نیمی تندخویی\r\nنیمی از عشق آتش است در آن هنگام وارد معبد شدم با صداقت و در سکوت زانو زدم و به عبادت پرداختم خداوندا مرا طعام شعله ها گردان بار الهی مرا در آتش مقدس بسوزان\r\n"},{"id":428,"category_id":4,"category_code":"s4","source_id":103,"title":"عشق دروغین","content":"دختری به پسری گفت:من عاشقت هستم.پسر گفت:لیاقت شما برادرم است که از من زیباتر است و پشت سرتان ایستاده.\r\nدخترک برگشت ولی کسی را ندید.پسر گفت:تو اگر عاشقم بودی هیچ وقت پشت سرت را نگاه نمیکردی!!\r\n"},{"id":429,"category_id":4,"category_code":"s4","source_id":104,"title":"معرفت","content":"پدر سیلی محکمی به صورت پسر زد و گفت:\r\nمگه این شام چه عیبی داره که لب نمی زنی؟\r\nپسر در حالی که به نون و پنیر و مقداری سبزی چشم دوخته بود\r\nاز پای سفره به گوشه ای خزید و سر به بالین نهاد.\r\nصبح فردا وقتی غذای پسر در بقچه پدر جای می گرفت\r\nپسرک دانست\r\nامروز بابا صبحانه دارد، چشمانش از شادی تر شد!\r\n"},{"id":430,"category_id":4,"category_code":"s4","source_id":105,"title":"آبجی کوچولو...","content":"\r\nداداشـي گـفت: زودي يـه آرزو كـن.\r\n‌آبجـي كوچيكه چشـاشو بسـت و آرزو كرد..\r\nداداشـي گفت: چـپ يا راسـت كوچولو؟\r\nآبجـي كوچيكه گـفت: ررراسـت تاتاجي جون!\r\nداداشـي دست چـپ و راسـتشو \r\nمرور كرد و گـفت: خـب اشكال نداره\r\nدستشـو دراز كـرد و يـه مـ‍‍‍ژه ديگـه\r\n‌از زير چشـم راسـت آجي برداشـت..\r\nديـدي؟؟؟ آرزوت مي خـواد برآورده شـه ،\r\n‌حالا چـي آرزو كردي كوچولو؟\r\nآجـي كوچولو گـفت: آرزو كردم ديـگه مـ‍‍‍ژه هام نريـزه!\r\nبعد سه تايي زدن زير خنده ..\r\nآبجـي كوچيكه و داداشـي و پرسـتار بخش شـيمي درمـاني..... .\r\n"},{"id":431,"category_id":4,"category_code":"s4","source_id":106,"title":"عاشق مادر باش!","content":"\r\nدکتری برای خواستگاری دختری رفت\r\nولی دختر او را رد کرد و گفت به شرطی قبول میکنم که مامانت به عروسی \r\nنیاید\r\nآن جوان در کار خود ماند و پیش یکی از اساتید خود رفت و با خجالت چنین \r\nگفت: \r\nدر سن یک سالگی پدرم مرد ومادرم برا اینکه خرج زندگیمان را تامین کند در\r\nخونه های مردم رخت و لباس میشست \r\nحالا دختری که خیلی دوستش دارم شرط کرده که فقط بدون حضور مادرم \r\nحاضر به ازدواج با من است \r\nنه فقط این بلکه این گذشته مادرم مرا خجالت زده کرده است \r\nبه نظرتان چکار کنم\r\nاستاد به او گفت:از تو خواسته ای دارم \r\nبه منزل برو و دست مامانت را بشور، فردا به نزد من بیا و بهت میگم چکار\r\nکن\r\nو جوان به منزل رفت و اینکار را کرد ولی با حوصله دستای مادرش را در \r\nحالی که اشک بر روی گونه هایش سرازیر شده بود انجام داد\r\nزیرا اولین بار بود که دستان مامانش درحالی که از شدت شستن لباسهای\r\nمردم \r\nچروک شده وتماما تاول زده و ترک برداشته اند را دید ، طوری که\r\nوقتی آب را \r\nروی دستانش میریخت از درد به لرز میفتاد.\r\nپس از شستن دستان مادرش نتونست تا فردا صبر کند و همون موقع به\r\nاستاد خود زنگ زد و گفت:\r\nممنونم که راه درست را بهم نشون دادی \r\nمن مادرم را به امروزم نمیفروشم \r\nچون اون زندگی را برای آینده من تباه کرد\r\nسلامتی تمام مادران.....\r\n"}];
